{
  "name": "CutFlow Barber",
  "description": "A comprehensive barbershop scheduling application with admin management and client booking flow."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Service {
  id: string;
  name: string;
  description: string;
  price: number;
  duration: number; // in minutes
}

export interface Professional {
  id: string;
  name: string;
  role: string;
  photoUrl: string;
}

export interface Coupon {
  id: string;
  code: string;
  type: 'percentage' | 'fixed';
  value: number;
  usageCount: number;
  active: boolean;
}

export interface Appointment {
  id: string;
  clientName: string;
  clientPhone: string;
  serviceIds: string[];
  professionalId: string | null; // null means "no preference"
  date: string; // YYYY-MM-DD
  time: string; // HH:mm
  totalValue: number;
  couponCode?: string;
  createdAt: string;
}

export interface ShopSettings {
  name: string;
  logoUrl: string | null;
  primaryColor: string;
  secondaryColor: string;
}

export interface ShopState {
  services: Service[];
  professionals: Professional[];
  coupons: Coupon[];
  appointments: Appointment[];
  settings: ShopSettings;
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ShopState, Service, Professional, Coupon, Appointment, ShopSettings } from './types';

interface ShopContextType extends ShopState {
  addService: (service: Omit<Service, 'id'>) => void;
  updateService: (id: string, service: Partial<Service>) => void;
  removeService: (id: string) => void;

  addProfessional: (professional: Omit<Professional, 'id'>) => void;
  updateProfessional: (id: string, professional: Partial<Professional>) => void;
  removeProfessional: (id: string) => void;

  addCoupon: (coupon: Omit<Coupon, 'id' | 'usageCount'>) => void;
  updateCoupon: (id: string, coupon: Partial<Coupon>) => void;
  removeCoupon: (id: string) => void;
  incrementCouponUsage: (code: string) => void;

  addAppointment: (appointment: Omit<Appointment, 'id' | 'createdAt'>) => void;

  updateSettings: (settings: Partial<ShopSettings>) => void;
}

const ShopContext = createContext<ShopContextType | undefined>(undefined);

// Initial Mock Data
const INITIAL_STATE: ShopState = {
  settings: {
    name: "CutFlow",
    logoUrl: null,
    primaryColor: "#f97316", // Orange-500
    secondaryColor: "#1e293b", // Slate-800
  },
  services: [
    { id: '1', name: 'Corte Tradicional', description: 'Corte clássico com máquina e tesoura', price: 35, duration: 30 },
    { id: '2', name: 'Corte + Barba', description: 'Corte completo com alinhamento de barba', price: 50, duration: 45 },
    { id: '3', name: 'Barba', description: 'Alinhamento e finalização de barba', price: 25, duration: 20 },
    { id: '4', name: 'Degradê', description: 'Corte degradê moderno', price: 45, duration: 40 },
    { id: '5', name: 'Platinado', description: 'Descoloração completa', price: 120, duration: 90 },
  ],
  professionals: [
    { id: '1', name: 'Carlos Silva', role: 'Especialista em degradê', photoUrl: 'https://picsum.photos/id/1005/200/200' },
    { id: '2', name: 'Rafael Santos', role: 'Master em barbas', photoUrl: 'https://picsum.photos/id/1012/200/200' },
    { id: '3', name: 'Lucas Oliveira', role: 'Cortes clássicos e modernos', photoUrl: 'https://picsum.photos/id/1025/200/200' },
  ],
  coupons: [
    { id: '1', code: 'PRIMEIRA', type: 'percentage', value: 20, usageCount: 15, active: true },
    { id: '2', code: 'VIP10', type: 'fixed', value: 10, usageCount: 8, active: true },
  ],
  appointments: [
    { 
      id: '101', 
      clientName: 'João Pereira', 
      clientPhone: '(11) 99999-9999', 
      serviceIds: ['2'], 
      professionalId: '1', 
      date: '2023-10-25', 
      time: '14:00', 
      totalValue: 50, 
      couponCode: undefined, 
      createdAt: new Date().toISOString() 
    }
  ]
};

export const ShopProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<ShopState>(INITIAL_STATE);

  // --- Services ---
  const addService = (service: Omit<Service, 'id'>) => {
    const newService = { ...service, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, services: [...prev.services, newService] }));
  };
  const updateService = (id: string, updated: Partial<Service>) => {
    setState(prev => ({
      ...prev,
      services: prev.services.map(s => s.id === id ? { ...s, ...updated } : s)
    }));
  };
  const removeService = (id: string) => {
    setState(prev => ({ ...prev, services: prev.services.filter(s => s.id !== id) }));
  };

  // --- Professionals ---
  const addProfessional = (pro: Omit<Professional, 'id'>) => {
    const newPro = { ...pro, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, professionals: [...prev.professionals, newPro] }));
  };
  const updateProfessional = (id: string, updated: Partial<Professional>) => {
    setState(prev => ({
      ...prev,
      professionals: prev.professionals.map(p => p.id === id ? { ...p, ...updated } : p)
    }));
  };
  const removeProfessional = (id: string) => {
    setState(prev => ({ ...prev, professionals: prev.professionals.filter(p => p.id !== id) }));
  };

  // --- Coupons ---
  const addCoupon = (coupon: Omit<Coupon, 'id' | 'usageCount'>) => {
    const newCoupon = { ...coupon, id: Math.random().toString(36).substr(2, 9), usageCount: 0 };
    setState(prev => ({ ...prev, coupons: [...prev.coupons, newCoupon] }));
  };
  const updateCoupon = (id: string, updated: Partial<Coupon>) => {
    setState(prev => ({
      ...prev,
      coupons: prev.coupons.map(c => c.id === id ? { ...c, ...updated } : c)
    }));
  };
  const removeCoupon = (id: string) => {
    setState(prev => ({ ...prev, coupons: prev.coupons.filter(c => c.id !== id) }));
  };
  const incrementCouponUsage = (code: string) => {
     setState(prev => ({
      ...prev,
      coupons: prev.coupons.map(c => c.code === code ? { ...c, usageCount: c.usageCount + 1 } : c)
    }));
  }

  // --- Appointments ---
  const addAppointment = (apt: Omit<Appointment, 'id' | 'createdAt'>) => {
    const newApt = { ...apt, id: Math.random().toString(36).substr(2, 9), createdAt: new Date().toISOString() };
    setState(prev => ({ ...prev, appointments: [...prev.appointments, newApt] }));
    if (apt.couponCode) {
        incrementCouponUsage(apt.couponCode);
    }
  };

  // --- Settings ---
  const updateSettings = (updated: Partial<ShopSettings>) => {
    setState(prev => ({ ...prev, settings: { ...prev.settings, ...updated } }));
  };

  return (
    <ShopContext.Provider value={{
      ...state,
      addService, updateService, removeService,
      addProfessional, updateProfessional, removeProfessional,
      addCoupon, updateCoupon, removeCoupon, incrementCouponUsage,
      addAppointment,
      updateSettings
    }}>
      {children}
    </ShopContext.Provider>
  );
};

export const useShop = () => {
  const context = useContext(ShopContext);
  if (!context) throw new Error("useShop must be used within a ShopProvider");
  return context;
};

import React, { useState, useRef } from 'react';
import { useShop } from '../../store';
import { Users, Scissors, Tag, Palette, LayoutDashboard, LogOut, Plus, Trash2, Edit2, Upload, Search, CalendarCheck } from 'lucide-react';

type AdminTab = 'team' | 'services' | 'coupons' | 'design' | 'appointments';

export const AdminDashboard: React.FC<{ onLogout: () => void }> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<AdminTab>('team');
  const { settings } = useShop();

  const renderContent = () => {
    switch (activeTab) {
      case 'team': return <TeamPanel />;
      case 'services': return <ServicesPanel />;
      case 'coupons': return <CouponsPanel />;
      case 'design': return <DesignPanel />;
      case 'appointments': return <AppointmentsPanel />;
      default: return <TeamPanel />;
    }
  };

  const getTabLabel = (tab: AdminTab) => {
      switch(tab) {
          case 'team': return 'Gerenciar Equipe';
          case 'services': return 'Gerenciar Serviços';
          case 'coupons': return 'Gerenciar Cupons';
          case 'design': return 'Design & Aparência';
          case 'appointments': return 'Vendas & Agenda';
      }
  }

  return (
    <div className="flex h-screen bg-slate-900 text-slate-100 overflow-hidden">
      {/* Sidebar */}
      <aside className="w-64 bg-slate-950 border-r border-slate-800 flex flex-col">
        <div className="p-6 flex items-center gap-3 border-b border-slate-800">
          <div className="w-8 h-8 rounded bg-primary flex items-center justify-center text-white font-bold" style={{ backgroundColor: settings.primaryColor }}>
             <Scissors size={18} />
          </div>
          <span className="font-bold text-xl tracking-tight">{settings.name}</span>
        </div>

        <nav className="flex-1 p-4 space-y-2">
          <SidebarItem icon={<Users size={20} />} label="Equipe" active={activeTab === 'team'} onClick={() => setActiveTab('team')} />
          <SidebarItem icon={<Scissors size={20} />} label="Serviços" active={activeTab === 'services'} onClick={() => setActiveTab('services')} />
          <SidebarItem icon={<Tag size={20} />} label="Cupons" active={activeTab === 'coupons'} onClick={() => setActiveTab('coupons')} />
          <SidebarItem icon={<Palette size={20} />} label="Design" active={activeTab === 'design'} onClick={() => setActiveTab('design')} />
          <SidebarItem icon={<CalendarCheck size={20} />} label="Agendamentos" active={activeTab === 'appointments'} onClick={() => setActiveTab('appointments')} />
        </nav>

        <div className="p-4 border-t border-slate-800">
          <button onClick={onLogout} className="flex items-center gap-3 px-4 py-3 w-full text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg transition-colors">
            <LogOut size={20} />
            <span>Sair / Voltar ao Site</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden">
        <header className="h-16 bg-slate-900 border-b border-slate-800 flex items-center px-8 justify-between">
             <h2 className="text-2xl font-bold">{getTabLabel(activeTab)}</h2>
             <div className="flex items-center gap-2">
                <div className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center">A</div>
                <span className="text-sm text-slate-300">Admin</span>
             </div>
        </header>
        <div className="flex-1 overflow-auto p-8">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

const SidebarItem: React.FC<{ icon: React.ReactNode, label: string, active: boolean, onClick: () => void }> = ({ icon, label, active, onClick }) => {
    const { settings } = useShop();
    return (
        <button 
            onClick={onClick}
            className={`flex items-center gap-3 px-4 py-3 w-full rounded-lg transition-all duration-200 ${active ? 'bg-slate-800 text-white font-medium shadow-md' : 'text-slate-400 hover:bg-slate-900 hover:text-slate-200'}`}
            style={active ? { borderLeft: `4px solid ${settings.primaryColor}` } : {}}
        >
            <span className={active ? `text-[${settings.primaryColor}]` : ''} style={{ color: active ? settings.primaryColor : 'inherit' }}>{icon}</span>
            <span>{label}</span>
        </button>
    );
}

// --- SUB PANELS ---

// 1. Team Panel
const TeamPanel = () => {
    const { professionals, addProfessional, removeProfessional, settings } = useShop();
    const [isFormOpen, setIsFormOpen] = useState(false);
    const [name, setName] = useState('');
    const [role, setRole] = useState('');
    const [photo, setPhoto] = useState<string | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            const imageUrl = URL.createObjectURL(file);
            setPhoto(imageUrl);
        }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        addProfessional({ name, role, photoUrl: photo || 'https://picsum.photos/200' });
        setIsFormOpen(false);
        setName(''); setRole(''); setPhoto(null);
    };

    return (
        <div>
            <div className="flex justify-between mb-8">
                <p className="text-slate-400">Adicione, edite ou remova profissionais da sua equipe.</p>
                <button onClick={() => setIsFormOpen(true)} className="flex items-center gap-2 px-4 py-2 rounded-lg text-white font-medium hover:opacity-90 transition-opacity" style={{ backgroundColor: settings.primaryColor }}>
                    <Plus size={18} /> Adicionar Profissional
                </button>
            </div>

            {isFormOpen && (
                <div className="mb-8 bg-slate-800 p-6 rounded-xl border border-slate-700 animate-fade-in-down">
                     <h3 className="text-lg font-bold mb-4">Novo Profissional</h3>
                     <form onSubmit={handleSubmit} className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm text-slate-400 mb-1">Nome Completo</label>
                                <input required value={name} onChange={e => setName(e.target.value)} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" placeholder="Ex: Carlos Silva" />
                            </div>
                            <div>
                                <label className="block text-sm text-slate-400 mb-1">Especialidade/Cargo</label>
                                <input required value={role} onChange={e => setRole(e.target.value)} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" placeholder="Ex: Master Barber" />
                            </div>
                        </div>
                        <div>
                            <label className="block text-sm text-slate-400 mb-1">Foto do Perfil</label>
                            <div className="flex items-center gap-4">
                                <div onClick={() => fileInputRef.current?.click()} className="w-16 h-16 bg-slate-900 rounded-full border border-dashed border-slate-600 flex items-center justify-center cursor-pointer hover:border-orange-500 overflow-hidden">
                                    {photo ? <img src={photo} alt="Preview" className="w-full h-full object-cover" /> : <Upload size={20} className="text-slate-500" />}
                                </div>
                                <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />
                                <span className="text-sm text-slate-500">Clique para carregar uma foto</span>
                            </div>
                        </div>
                        <div className="flex gap-2 justify-end pt-2">
                             <button type="button" onClick={() => setIsFormOpen(false)} className="px-4 py-2 text-slate-400 hover:text-white">Cancelar</button>
                             <button type="submit" className="px-6 py-2 rounded-lg text-white" style={{ backgroundColor: settings.primaryColor }}>Salvar</button>
                        </div>
                     </form>
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {professionals.map(pro => (
                    <div key={pro.id} className="bg-slate-800 rounded-xl p-6 border border-slate-700 hover:border-slate-600 transition-colors flex flex-col items-center text-center">
                        <img src={pro.photoUrl} alt={pro.name} className="w-24 h-24 rounded-full object-cover mb-4 border-2 border-slate-600" />
                        <h3 className="font-bold text-lg">{pro.name}</h3>
                        <p className="text-slate-400 text-sm mb-6">{pro.role}</p>
                        <div className="flex gap-3 w-full mt-auto">
                            <button className="flex-1 py-2 bg-slate-700 rounded-lg text-slate-300 hover:bg-slate-600 flex items-center justify-center gap-2 text-sm"><Edit2 size={14}/> Editar</button>
                            <button onClick={() => removeProfessional(pro.id)} className="flex-1 py-2 bg-red-500/10 text-red-500 border border-red-500/20 rounded-lg hover:bg-red-500/20 flex items-center justify-center gap-2 text-sm"><Trash2 size={14}/> Remover</button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

// 2. Services Panel
const ServicesPanel = () => {
    const { services, addService, removeService, settings } = useShop();
    const [isFormOpen, setIsFormOpen] = useState(false);
    const [formData, setFormData] = useState({ name: '', description: '', price: '', duration: '' });

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        addService({
            name: formData.name,
            description: formData.description,
            price: Number(formData.price),
            duration: Number(formData.duration)
        });
        setIsFormOpen(false);
        setFormData({ name: '', description: '', price: '', duration: '' });
    };

    return (
        <div>
             <div className="flex justify-between mb-8">
                <p className="text-slate-400">Adicione, edite ou remova serviços oferecidos.</p>
                <button onClick={() => setIsFormOpen(true)} className="flex items-center gap-2 px-4 py-2 rounded-lg text-white font-medium hover:opacity-90" style={{ backgroundColor: settings.primaryColor }}>
                    <Plus size={18} /> Adicionar Serviço
                </button>
            </div>

            {isFormOpen && (
                 <div className="mb-8 bg-slate-800 p-6 rounded-xl border border-slate-700 animate-fade-in-down">
                     <h3 className="text-lg font-bold mb-4">Novo Serviço</h3>
                     <form onSubmit={handleSubmit} className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                             <div>
                                <label className="block text-sm text-slate-400 mb-1">Nome do Serviço</label>
                                <input required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" />
                            </div>
                            <div>
                                <label className="block text-sm text-slate-400 mb-1">Duração (minutos)</label>
                                <input required type="number" value={formData.duration} onChange={e => setFormData({...formData, duration: e.target.value})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" />
                            </div>
                            <div>
                                <label className="block text-sm text-slate-400 mb-1">Preço (R$)</label>
                                <input required type="number" value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" />
                            </div>
                            <div>
                                <label className="block text-sm text-slate-400 mb-1">Descrição Curta</label>
                                <input required value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" />
                            </div>
                        </div>
                        <div className="flex gap-2 justify-end pt-2">
