import React, { useState, useMemo } from 'react';
import { useShop } from '../../store';
import { Scissors, User, Calendar, Check, ArrowRight, ArrowLeft, Clock, AlertCircle } from 'lucide-react';
import { Appointment } from '../../types';

type Step = 'home' | 'services' | 'professional' | 'datetime' | 'summary' | 'success';

export const BookingFlow: React.FC<{ onAdminClick: () => void }> = ({ onAdminClick }) => {
    const [step, setStep] = useState<Step>('home');
    const { services, professionals, settings, coupons, addAppointment } = useShop();

    // Booking State
    const [selectedServiceIds, setSelectedServiceIds] = useState<string[]>([]);
    const [selectedProId, setSelectedProId] = useState<string | null>(null);
    const [selectedDate, setSelectedDate] = useState<string>('');
    const [selectedTime, setSelectedTime] = useState<string>('');
    const [customerInfo, setCustomerInfo] = useState({ name: '', phone: '' });
    const [couponCode, setCouponCode] = useState('');
    const [appliedCoupon, setAppliedCoupon] = useState<string | null>(null);
    const [discountAmount, setDiscountAmount] = useState(0);

    // Helpers
    const selectedServices = services.filter(s => selectedServiceIds.includes(s.id));
    const subtotal = selectedServices.reduce((acc, s) => acc + s.price, 0);
    const totalDuration = selectedServices.reduce((acc, s) => acc + s.duration, 0);
    const total = Math.max(0, subtotal - discountAmount);

    const handleApplyCoupon = () => {
        const coupon = coupons.find(c => c.code === couponCode.toUpperCase() && c.active);
        if (coupon) {
            let discount = 0;
            if (coupon.type === 'percentage') {
                discount = subtotal * (coupon.value / 100);
            } else {
                discount = coupon.value;
            }
            setDiscountAmount(discount);
            setAppliedCoupon(coupon.code);
        } else {
            alert('Cupom inválido ou expirado');
            setDiscountAmount(0);
            setAppliedCoupon(null);
        }
    };

    const handleFinish = () => {
        if (!customerInfo.name || !customerInfo.phone) {
            alert('Por favor, preencha seus dados.');
            return;
        }

        const appointment: Omit<Appointment, 'id' | 'createdAt'> = {
            clientName: customerInfo.name,
            clientPhone: customerInfo.phone,
            serviceIds: selectedServiceIds,
            professionalId: selectedProId,
            date: selectedDate,
            time: selectedTime,
            totalValue: total,
            couponCode: appliedCoupon || undefined
        };

        addAppointment(appointment);
        setStep('success');
    };

    // Components for each step
    const HomeStep = () => (
        <div className="flex flex-col items-center justify-center min-h-[80vh] text-center px-4">
            <div className="w-20 h-20 rounded-2xl flex items-center justify-center mb-6 shadow-lg shadow-orange-500/20" style={{ backgroundColor: settings.primaryColor }}>
                <Scissors size={40} className="text-white" />
            </div>
            <h1 className="text-4xl md:text-5xl font-bold mb-4">{settings.name}</h1>
            <p className="text-slate-400 text-lg mb-12 max-w-lg">Sistema profissional de agendamento. Escolha seus serviços e profissionais favoritos em poucos cliques.</p>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-4xl mb-12">
                 <div className="bg-slate-800/50 border border-slate-700 p-6 rounded-xl">
                    <Scissors className="mx-auto mb-4 text-orange-500" style={{ color: settings.primaryColor }} size={32} />
                    <h3 className="font-bold mb-2">Serviços Variados</h3>
                    <p className="text-sm text-slate-400">Escolha entre diversos serviços profissionais</p>
                 </div>
                 <div className="bg-slate-800/50 border border-slate-700 p-6 rounded-xl">
                    <User className="mx-auto mb-4 text-orange-500" style={{ color: settings.primaryColor }} size={32} />
                    <h3 className="font-bold mb-2">Profissionais Qualificados</h3>
                    <p className="text-sm text-slate-400">Equipe experiente e especializada</p>
                 </div>
                 <div className="bg-slate-800/50 border border-slate-700 p-6 rounded-xl">
                    <Calendar className="mx-auto mb-4 text-orange-500" style={{ color: settings.primaryColor }} size={32} />
                    <h3 className="font-bold mb-2">Agendamento Fácil</h3>
                    <p className="text-sm text-slate-400">Reserve seu horário em poucos cliques</p>
                 </div>
            </div>

            <button onClick={() => setStep('services')} className="px-8 py-4 rounded-full text-white font-bold text-lg shadow-lg hover:brightness-110 transition-all transform hover:-translate-y-1" style={{ backgroundColor: settings.primaryColor }}>
                Agendar Horário
            </button>
            <button onClick={onAdminClick} className="mt-6 text-sm text-slate-500 underline hover:text-slate-300">
                acessar painel administrativo
            </button>
        </div>
    );

    const ServicesStep = () => {
        const toggleService = (id: string) => {
            if (selectedServiceIds.includes(id)) {
                setSelectedServiceIds(prev => prev.filter(i => i !== id));
            } else {
                setSelectedServiceIds(prev => [...prev, id]);
            }
        };

        return (
            <div className="max-w-2xl mx-auto py-8 px-4">
                <h2 className="text-3xl font-bold mb-2">Escolha seus serviços</h2>
                <p className="text-slate-400 mb-8">Selecione um ou mais serviços desejados</p>

                <div className="space-y-4">
                    {services.map(service => {
                        const isSelected = selectedServiceIds.includes(service.id);
                        return (
                            <div 
                                key={service.id} 
                                onClick={() => toggleService(service.id)}
                                className={`p-5 rounded-xl border cursor-pointer transition-all ${isSelected ? 'bg-slate-800 border-orange-500 ring-1 ring-orange-500' : 'bg-slate-800/50 border-slate-700 hover:border-slate-600'}`}
                                style={isSelected ? { borderColor: settings.primaryColor, '--tw-ring-color': settings.primaryColor } as any : {}}
                            >
                                <div className="flex items-start gap-4">
                                    <div className={`w-6 h-6 rounded-full border flex items-center justify-center mt-1 ${isSelected ? 'bg-orange-500 border-orange-500' : 'border-slate-500'}`} style={isSelected ? { backgroundColor: settings.primaryColor, borderColor: settings.primaryColor } : {}}>
                                        {isSelected && <Check size={14} className="text-white" />}
                                    </div>
                                    <div className="flex-1">
                                        <h3 className="font-bold text-lg">{service.name}</h3>
                                        <p className="text-slate-400 text-sm mb-2">{service.description}</p>
                                        <div className="flex gap-4 text-sm font-medium">
                                            <span className="text-slate-300 flex items-center gap-1"><Clock size={14}/> {service.duration} min</span>
                                            <span style={{ color: settings.primaryColor }}>R$ {service.price.toFixed(2)}</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>

                <div className="mt-8 pt-6 border-t border-slate-700 flex items-center justify-between">
                    <div>
                        <p className="text-slate-400 text-sm">Total</p>
                        <p className="text-2xl font-bold">R$ {subtotal.toFixed(2)}</p>
                    </div>
                    <button 
                        disabled={selectedServiceIds.length === 0}
                        onClick={() => setStep('professional')}
                        className={`flex items-center gap-2 px-8 py-3 rounded-full text-white font-bold transition-all ${selectedServiceIds.length === 0 ? 'bg-slate-700 cursor-not-allowed opacity-50' : 'hover:brightness-110'}`}
                        style={selectedServiceIds.length > 0 ? { backgroundColor: settings.primaryColor } : {}}
                    >
                        Continuar <ArrowRight size={20} />
                    </button>
                </div>
            </div>
        );
    };

    const ProfessionalStep = () => (
        <div className="max-w-2xl mx-auto py-8 px-4">
            <button onClick={() => setStep('services')} className="text-slate-400 flex items-center gap-2 mb-6 hover:text-white"><ArrowLeft size={16}/> Voltar</button>
            <h2 className="text-3xl font-bold mb-2">Escolha o profissional</h2>
            <p className="text-slate-400 mb-8">Selecione seu barbeiro ou deixe sem preferência</p>

            <div className="space-y-4">
                <div 
                    onClick={() => setSelectedProId(null)}
                    className={`p-5 rounded-xl border cursor-pointer transition-all flex items-center gap-4 ${selectedProId === null ? 'bg-slate-800 border-orange-500 ring-1 ring-orange-500' : 'bg-slate-800/50 border-slate-700 hover:border-slate-600'}`}
                    style={selectedProId === null ? { borderColor: settings.primaryColor, '--tw-ring-color': settings.primaryColor } as any : {}}
                >
                    <div className="w-16 h-16 rounded-full bg-slate-700 flex items-center justify-center text-slate-300">
                        <User size={24}/>
                    </div>
                    <div>
                        <h3 className="font-bold text-lg">Sem preferência</h3>
                        <p className="text-slate-400 text-sm">Primeiro profissional disponível</p>
                    </div>
                </div>

                {professionals.map(pro => {
                    const isSelected = selectedProId === pro.id;
                    return (
                        <div 
                            key={pro.id}
                            onClick={() => setSelectedProId(pro.id)}
                            className={`p-5 rounded-xl border cursor-pointer transition-all flex items-center gap-4 ${isSelected ? 'bg-slate-800 border-orange-500 ring-1 ring-orange-500' : 'bg-slate-800/50 border-slate-700 hover:border-slate-600'}`}
                            style={isSelected ? { borderColor: settings.primaryColor, '--tw-ring-color': settings.primaryColor } as any : {}}
                        >
                            <img src={pro.photoUrl} alt={pro.name} className="w-16 h-16 rounded-full object-cover" />
                            <div>
                                <h3 className="font-bold text-lg">{pro.name}</h3>
                                <p className="text-slate-400 text-sm">{pro.role}</p>
                            </div>
                        </div>
                    );
                })}
            </div>

            <div className="mt-8 flex justify-end">
                <button 
                    onClick={() => setStep('datetime')}
                    className="flex items-center gap-2 px-8 py-3 rounded-full text-white font-bold hover:brightness-110 transition-all"
                    style={{ backgroundColor: settings.primaryColor }}
                >
                    Continuar <ArrowRight size={20} />
                </button>
            </div>
        </div>
    );

    const DateTimeStep = () => {
        // Mock Calendar generation
        const dates = useMemo(() => {
            const arr = [];
            const today = new Date();
            for(let i=0; i<7; i++) {
                const d = new Date(today);
                d.setDate(today.getDate() + i);
                arr.push({
                    full: d.toISOString().split('T')[0],
                    day: d.getDate(),
                    weekday: d.toLocaleDateString('pt-BR', { weekday: 'short' }),
                    month: d.toLocaleDateString('pt-BR', { month: 'short' })
                });
            }
            return arr;
        }, []);

        const timeSlots = ['09:00', '09:30', '10:00', '10:30', '11:00', '11:30', '14:00', '14:30', '15:00', '15:30', '16:00', '16:30', '17:00', '17:30', '18:00'];

        return (
            <div className="max-w-3xl mx-auto py-8 px-4">
                 <button onClick={() => setStep('professional')} className="text-slate-400 flex items-center gap-2 mb-6 hover:text-white"><ArrowLeft size={16}/> Voltar</button>
