                                    {selectedServices.map(s => <div key={s.id}>{s.name}</div>)}
                                </div>
                            </div>
                            <div className="text-right text-slate-300">R$ {subtotal.toFixed(2)}</div>
                        </div>

                        <div className="pb-4 border-b border-slate-700">
                            <p className="text-slate-400 text-sm">Profissional</p>
                            <div className="text-white font-medium">
                                {selectedProId ? professionals.find(p => p.id === selectedProId)?.name : 'Sem preferência'}
                            </div>
                        </div>

                        <div className="pb-4 border-b border-slate-700">
                            <p className="text-slate-400 text-sm">Data e horário</p>
                            <div className="text-white font-medium">
                                {new Date(selectedDate + 'T12:00:00').toLocaleDateString('pt-BR', { weekday: 'long', day: 'numeric', month: 'long' })}
                                <br/>
                                {selectedTime}
                            </div>
                        </div>
                    </div>

                    <div className="space-y-2 mb-6">
                         <div className="flex justify-between text-slate-400">
                             <span>Subtotal</span>
                             <span>R$ {subtotal.toFixed(2)}</span>
                         </div>
                         {discountAmount > 0 && (
                             <div className="flex justify-between text-green-500">
                                 <span>Desconto</span>
                                 <span>- R$ {discountAmount.toFixed(2)}</span>
                             </div>
                         )}
                         <div className="flex justify-between text-2xl font-bold text-white pt-4 border-t border-slate-700">
                             <span>Total</span>
                             <span>R$ {total.toFixed(2)}</span>
                         </div>
                    </div>

                    <button 
                        onClick={handleFinish}
                        className="w-full py-4 rounded-lg text-white font-bold text-lg hover:brightness-110 transition-all shadow-lg"
                        style={{ backgroundColor: settings.primaryColor }}
                    >
                        Confirmar Agendamento
                    </button>
                 </div>
             </div>
        </div>
    );

    const SuccessStep = () => (
        <div className="flex flex-col items-center justify-center min-h-[70vh] text-center px-4 animate-fade-in-down">
            <div className="w-24 h-24 rounded-full bg-green-500/20 text-green-500 flex items-center justify-center mb-6">
                <Check size={48} strokeWidth={3} />
            </div>
            <h2 className="text-3xl md:text-4xl font-bold mb-4 text-white">Agendamento Confirmado!</h2>
            <p className="text-slate-400 max-w-md mb-8">Obrigado, {customerInfo.name}. Seu horário foi reservado com sucesso. Te esperamos lá!</p>

            <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 w-full max-w-md mb-8 text-left">
                <div className="flex items-center gap-3 mb-4">
                    <Calendar className="text-slate-400" size={20}/>
                    <span>{new Date(selectedDate + 'T12:00:00').toLocaleDateString('pt-BR', { weekday: 'long', day: 'numeric', month: 'long' })} às {selectedTime}</span>
                </div>
                <div className="flex items-center gap-3">
                     <User className="text-slate-400" size={20}/>
                     <span>{selectedProId ? professionals.find(p => p.id === selectedProId)?.name : 'Profissional disponível'}</span>
                </div>
            </div>

            <button 
                onClick={() => window.location.reload()} // Reset app
                className="px-8 py-3 rounded-full border border-slate-600 hover:bg-slate-800 text-white transition-all"
            >
                Voltar ao início
            </button>
        </div>
    );

    switch(step) {
        case 'home': return <HomeStep />;
        case 'services': return <ServicesStep />;
        case 'professional': return <ProfessionalStep />;
        case 'datetime': return <DateTimeStep />;
        case 'summary': return <SummaryStep />;
        case 'success': return <SuccessStep />;
        default: return <HomeStep />;
    }
};

