const DateTimeStep: React.FC<{
    selectedDate: string,
    setSelectedDate: (d: string) => void,
    selectedTime: string,
    setSelectedTime: (t: string) => void,
    setStep: (s: Step) => void,
    settings: any
}> = ({ selectedDate, setSelectedDate, selectedTime, setSelectedTime, setStep, settings }) => {
    // Mock Calendar generation
    const dates = useMemo(() => {
        const arr = [];
        const today = new Date();
        for(let i=0; i<7; i++) {
            const d = new Date(today);
            d.setDate(today.getDate() + i);
            arr.push({
                full: d.toISOString().split('T')[0],
                day: d.getDate(),
                weekday: d.toLocaleDateString('pt-BR', { weekday: 'short' }),
                month: d.toLocaleDateString('pt-BR', { month: 'short' })
            });
        }
        return arr;
    }, []);

    const timeSlots = ['09:00', '09:30', '10:00', '10:30', '11:00', '11:30', '14:00', '14:30', '15:00', '15:30', '16:00', '16:30', '17:00', '17:30', '18:00'];

    return (
        <div className="max-w-3xl mx-auto py-8 px-4">
                <button onClick={() => setStep('professional')} className="text-slate-400 flex items-center gap-2 mb-6 hover:text-white"><ArrowLeft size={16}/> Voltar</button>
                <h2 className="text-3xl font-bold mb-2">Escolha data e horário</h2>
                <p className="text-slate-400 mb-8">Selecione o melhor dia e hora para você</p>

                <div className="mb-6">
                <h3 className="text-slate-300 font-bold mb-4 flex items-center gap-2"><Calendar size={18}/> Data</h3>
                <div className="grid grid-cols-4 md:grid-cols-7 gap-3">
                    {dates.map(date => {
                        const isSelected = selectedDate === date.full;
                        return (
                            <div 
                                key={date.full}
                                onClick={() => setSelectedDate(date.full)}
                                className={`p-3 rounded-lg border text-center cursor-pointer transition-all ${isSelected ? 'bg-slate-800 text-white' : 'bg-slate-800/30 border-slate-700 text-slate-400 hover:bg-slate-800'}`}
                                style={isSelected ? { borderColor: settings.primaryColor, borderWidth: '2px' } : {}}
                            >
                                <div className="text-xs uppercase font-bold opacity-60">{date.weekday}</div>
                                <div className="text-2xl font-bold my-1">{date.day}</div>
                                <div className="text-xs opacity-60">{date.month}</div>
                            </div>
                        );
                    })}
                </div>
                </div>

                {selectedDate && (
                    <div className="mb-8 animate-fade-in-down">
                    <h3 className="text-slate-300 font-bold mb-4 flex items-center gap-2"><Clock size={18}/> Horário</h3>
                    <div className="grid grid-cols-4 md:grid-cols-5 lg:grid-cols-6 gap-3">
                        {timeSlots.map(time => {
                            const isSelected = selectedTime === time;
                            return (
                                <div 
                                    key={time}
                                    onClick={() => setSelectedTime(time)}
                                    className={`p-3 rounded-lg border text-center cursor-pointer transition-all ${isSelected ? 'bg-slate-800 text-white font-bold' : 'bg-slate-800/30 border-slate-700 text-slate-300 hover:bg-slate-800'}`}
                                    style={isSelected ? { borderColor: settings.primaryColor, borderWidth: '2px' } : {}}
                                >
                                    {time}
                                </div>
                            )
                        })}
                    </div>
                    </div>
                )}

                {selectedDate && selectedTime && (
                    <div className="bg-slate-800 p-4 rounded-xl border border-slate-700 mb-8">
                    <span className="text-slate-400 text-sm">Agendamento selecionado</span>
                    <div className="text-white font-bold text-lg">
                        {new Date(selectedDate + 'T12:00:00').toLocaleDateString('pt-BR', { weekday: 'long', day: 'numeric', month: 'long' })} às {selectedTime}
                    </div>
                    </div>
                )}

            <div className="flex justify-end">
                <button 
                    disabled={!selectedDate || !selectedTime}
                    onClick={() => setStep('summary')}
                    className={`flex items-center gap-2 px-8 py-3 rounded-full text-white font-bold transition-all ${(!selectedDate || !selectedTime) ? 'bg-slate-700 cursor-not-allowed opacity-50' : 'hover:brightness-110'}`}
                    style={selectedDate && selectedTime ? { backgroundColor: settings.primaryColor } : {}}
                >
                    Continuar <ArrowRight size={20} />
                </button>
            </div>
        </div>
    );
};

