interface ShopContextType extends ShopState {
  addService: (service: Omit<Service, 'id'>) => void;
  updateService: (id: string, service: Partial<Service>) => void;
  removeService: (id: string) => void;

  addProfessional: (professional: Omit<Professional, 'id'>) => void;
  updateProfessional: (id: string, professional: Partial<Professional>) => void;
  removeProfessional: (id: string) => void;

  addCoupon: (coupon: Omit<Coupon, 'id' | 'usageCount'>) => void;
  updateCoupon: (id: string, coupon: Partial<Coupon>) => void;
  removeCoupon: (id: string) => void;
  incrementCouponUsage: (code: string) => void;

  addAppointment: (appointment: Omit<Appointment, 'id' | 'createdAt'>) => void;

  updateSettings: (settings: Partial<ShopSettings>) => void;
}

const ShopContext = createContext<ShopContextType | undefined>(undefined);

