export const ShopProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<ShopState>(INITIAL_STATE);

  // --- Services ---
  const addService = (service: Omit<Service, 'id'>) => {
    const newService = { ...service, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, services: [...prev.services, newService] }));
  };
  const updateService = (id: string, updated: Partial<Service>) => {
    setState(prev => ({
      ...prev,
      services: prev.services.map(s => s.id === id ? { ...s, ...updated } : s)
    }));
  };
  const removeService = (id: string) => {
    setState(prev => ({ ...prev, services: prev.services.filter(s => s.id !== id) }));
  };

  // --- Professionals ---
  const addProfessional = (pro: Omit<Professional, 'id'>) => {
    const newPro = { ...pro, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, professionals: [...prev.professionals, newPro] }));
  };
  const updateProfessional = (id: string, updated: Partial<Professional>) => {
    setState(prev => ({
      ...prev,
      professionals: prev.professionals.map(p => p.id === id ? { ...p, ...updated } : p)
    }));
  };
  const removeProfessional = (id: string) => {
    setState(prev => ({ ...prev, professionals: prev.professionals.filter(p => p.id !== id) }));
  };

  // --- Coupons ---
  const addCoupon = (coupon: Omit<Coupon, 'id' | 'usageCount'>) => {
    const newCoupon = { ...coupon, id: Math.random().toString(36).substr(2, 9), usageCount: 0 };
    setState(prev => ({ ...prev, coupons: [...prev.coupons, newCoupon] }));
  };
  const updateCoupon = (id: string, updated: Partial<Coupon>) => {
    setState(prev => ({
      ...prev,
      coupons: prev.coupons.map(c => c.id === id ? { ...c, ...updated } : c)
    }));
  };
  const removeCoupon = (id: string) => {
    setState(prev => ({ ...prev, coupons: prev.coupons.filter(c => c.id !== id) }));
  };
  const incrementCouponUsage = (code: string) => {
     setState(prev => ({
      ...prev,
      coupons: prev.coupons.map(c => c.code === code ? { ...c, usageCount: c.usageCount + 1 } : c)
    }));
  }

  // --- Appointments ---
  const addAppointment = (apt: Omit<Appointment, 'id' | 'createdAt'>) => {
    const newApt = { ...apt, id: Math.random().toString(36).substr(2, 9), createdAt: new Date().toISOString() };
    setState(prev => ({ ...prev, appointments: [...prev.appointments, newApt] }));
    if (apt.couponCode) {
        incrementCouponUsage(apt.couponCode);
    }
  };

  // --- Settings ---
  const updateSettings = (updated: Partial<ShopSettings>) => {
    setState(prev => ({ ...prev, settings: { ...prev.settings, ...updated } }));
  };

  return (
    <ShopContext.Provider value={{
      ...state,
      addService, updateService, removeService,
      addProfessional, updateProfessional, removeProfessional,
      addCoupon, updateCoupon, removeCoupon, incrementCouponUsage,
      addAppointment,
      updateSettings
    }}>
      {children}
    </ShopContext.Provider>
  );
};

export const useShop = () => {
  const context = useContext(ShopContext);
  if (!context) throw new Error("useShop must be used within a ShopProvider");
  return context;
};

