const TeamPanel = () => {
    const { professionals, addProfessional, updateProfessional, removeProfessional, settings } = useShop();
    const [isFormOpen, setIsFormOpen] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [name, setName] = useState('');
    const [role, setRole] = useState('');
    const [photo, setPhoto] = useState<string | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            const imageUrl = URL.createObjectURL(file);
            setPhoto(imageUrl);
        }
    };

    const handleEdit = (pro: Professional) => {
        setEditingId(pro.id);
        setName(pro.name);
        setRole(pro.role);
        setPhoto(pro.photoUrl);
        setIsFormOpen(true);
    };

    const handleRemove = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        if (window.confirm("Tem certeza que deseja remover este profissional?")) {
            removeProfessional(id);
        }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const proData = { name, role, photoUrl: photo || 'https://picsum.photos/200' };

        if (editingId) {
            updateProfessional(editingId, proData);
        } else {
            addProfessional(proData);
        }

        setIsFormOpen(false);
        setEditingId(null);
        setName(''); setRole(''); setPhoto(null);
    };

    return (
        <div>
            <div className="flex justify-between mb-8">
                <p className="text-slate-400">Adicione, edite ou remova profissionais da sua equipe.</p>
                <button onClick={() => { setIsFormOpen(true); setEditingId(null); setName(''); setRole(''); setPhoto(null); }} className="flex items-center gap-2 px-4 py-2 rounded-lg text-white font-medium hover:opacity-90 transition-opacity" style={{ backgroundColor: settings.primaryColor }}>
                    <Plus size={18} /> Adicionar Profissional
