// 2. Services Panel
const ServicesPanel = () => {
    const { services, addService, updateService, removeService, settings } = useShop();
    const [isFormOpen, setIsFormOpen] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [formData, setFormData] = useState({ name: '', description: '', price: '', duration: '' });

    const handleEdit = (service: Service) => {
        setEditingId(service.id);
        setFormData({
            name: service.name,
            description: service.description,
            price: service.price.toString(),
            duration: service.duration.toString()
        });
        setIsFormOpen(true);
    };

    const handleRemove = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        if (window.confirm("Tem certeza que deseja remover este serviço?")) {
            removeService(id);
        }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const serviceData = {
            name: formData.name,
            description: formData.description,
            price: Number(formData.price),
            duration: Number(formData.duration)
        };

        if (editingId) {
            updateService(editingId, serviceData);
        } else {
            addService(serviceData);
        }

        setIsFormOpen(false);
        setEditingId(null);
        setFormData({ name: '', description: '', price: '', duration: '' });
    };

    return (
        <div>
             <div className="flex justify-between mb-8">
                <p className="text-slate-400">Adicione, edite ou remova serviços oferecidos.</p>
