import React, { useState, useRef, useEffect } from 'react';
import { useShop } from '../../store';
import { Users, Scissors, Tag, Palette, LayoutDashboard, LogOut, Plus, Trash2, Edit2, Upload, Search, CalendarCheck, X, AlertCircle } from 'lucide-react';
