const ServicesStep: React.FC<{ 
    services: Service[], 
    selectedServiceIds: string[], 
    setSelectedServiceIds: React.Dispatch<React.SetStateAction<string[]>>, 
    setStep: (s: Step) => void,
    settings: any,
    subtotal: number
}> = ({ services, selectedServiceIds, setSelectedServiceIds, setStep, settings, subtotal }) => {

    const toggleService = (id: string) => {
        if (selectedServiceIds.includes(id)) {
            setSelectedServiceIds(prev => prev.filter(i => i !== id));
        } else {
            setSelectedServiceIds(prev => [...prev, id]);
        }
    };

    return (
        <div className="max-w-2xl mx-auto py-8 px-4 pb-32">
            <div className="mb-6">
                <button 
                    onClick={() => setStep('home')} 
