                            <th className="p-4 font-medium">Profissional</th>
                            <th className="p-4 font-medium">Cupom</th>
                            <th className="p-4 font-medium text-right">Valor</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-700">
                        {appointments.map(apt => (
                            <tr key={apt.id} className="hover:bg-slate-700/30 transition-colors">
                                <td className="p-4">
                                    <div className="font-medium text-white">{apt.clientName}</div>
                                    <div className="text-xs text-slate-500">{apt.clientPhone}</div>
                                </td>
                                <td className="p-4 text-slate-300">
