                        ))}
                        {appointments.length === 0 && (
                            <tr>
                                <td colSpan={5} className="p-8 text-center text-slate-500">Nenhum agendamento encontrado.</td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { ShopProvider } from './store';
import { AdminDashboard } from './components/admin/AdminDashboard';
import { BookingFlow } from './components/client/BookingFlow';
import { LandingPage } from './components/landing/LandingPage';
import { Signup } from './components/auth/Signup';

type ViewState = 'landing' | 'signup' | 'admin' | 'client';

function AppContent() {
  const [view, setView] = useState<ViewState>('landing');

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 font-sans selection:bg-orange-500/30">
        {view === 'landing' && (
            <LandingPage 
                onStart={() => setView('signup')} 
                onLogin={() => setView('admin')} 
            />
        )}

        {view === 'signup' && (
            <Signup 
                onComplete={() => setView('admin')} 
                onBack={() => setView('landing')} 
            />
        )}

        {view === 'admin' && (
            <AdminDashboard 
                onLogout={() => setView('landing')} 
                onViewClient={() => setView('client')}
            />
        )}

        {view === 'client' && (
            <div className="w-full">
                <BookingFlow onAdminClick={() => setView('admin')} />
            </div>
        )}
    </div>
  );
}

function App() {
  return (
    <ShopProvider>
      <AppContent />
    </ShopProvider>
  );
}

export default App;

