        date: apt.date,
        time: apt.time,
        total_value: apt.totalValue,
        coupon_code: apt.couponCode
    });

    if (apt.couponCode) {
        await incrementCouponUsage(apt.couponCode);
    }
    // Note: We don't fetch data here because public users usually can't read appointments list
  };

  const updateSettings = async (updated: Partial<ShopSettings>) => {
    const { data } = await supabase.from('settings').select('id').limit(1).single();

    const payload: any = {};
    if (updated.name) payload.name = updated.name;
    if (updated.logoUrl) payload.logo_url = updated.logoUrl;
    if (updated.primaryColor) payload.primary_color = updated.primaryColor;
    if (updated.secondaryColor) payload.secondary_color = updated.secondaryColor;

    if (data && data.id) {
        await supabase.from('settings').update(payload).eq('id', data.id);
    } else {
        await supabase.from('settings').insert(payload);
    }
    fetchData();
  };

  return (
    <ShopContext.Provider value={{
      ...state,
      session,
      loading,
      login, signup, logout,
      addService, updateService, removeService,
      addProfessional, updateProfessional, removeProfessional,
      addCoupon, updateCoupon, removeCoupon, incrementCouponUsage,
      addAppointment,
      updateSettings,
      refresh: fetchData
    }}>
      {children}
    </ShopContext.Provider>
  );
};

export const useShop = () => {
  const context = useContext(ShopContext);
  if (!context) throw new Error("useShop must be used within a ShopProvider");
  return context;
};

