import React, { useState } from 'react';
import { ShopProvider, useShop } from './store';
import { AdminDashboard } from './components/admin/AdminDashboard';
import { BookingFlow } from './components/client/BookingFlow';
import { LandingPage } from './components/landing/LandingPage';
import { Signup } from './components/auth/Signup';
import { Login } from './components/auth/Login';

type ViewState = 'landing' | 'signup' | 'login' | 'admin' | 'client';

function AppContent() {
  const [view, setView] = useState<ViewState>('landing');
  const { session, logout } = useShop();

  // If user is logged in, they should probably be seeing admin (unless explicitly viewing client)
  // This is a simple router replacement
  const handleLogout = () => {
      logout();
      setView('landing');
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 font-sans selection:bg-orange-500/30">
        {view === 'landing' && (
            <LandingPage 
                onStart={() => setView('signup')} 
                onLogin={() => setView('login')} 
            />
        )}

        {view === 'signup' && (
            <Signup 
                onComplete={() => setView('admin')} 
                onBack={() => setView('landing')} 
            />
        )}

        {view === 'login' && (
            <Login 
                onComplete={() => setView('admin')} 
                onBack={() => setView('landing')} 
            />
        )}

        {view === 'admin' && (
            <AdminDashboard 
                onLogout={handleLogout} 
                onViewClient={() => setView('client')}
            />
        )}

        {view === 'client' && (
            <div className="w-full">
                <BookingFlow onAdminClick={() => session ? setView('admin') : setView('login')} />
            </div>
        )}
    </div>
  );
}

function App() {
  return (
    <ShopProvider>
      <AppContent />
    </ShopProvider>
  );
}

export default App;

export interface Service {
  id: string;
  name: string;
  description: string;
  price: number;
  duration: number; // in minutes
}

export interface DaySchedule {
  start: string;    // "09:00"
  end: string;      // "18:00"
  lunchStart: string; // "12:00"
  lunchEnd: string;   // "13:00"
  active: boolean;
}

export interface WorkSchedule {
  monday: DaySchedule;
  tuesday: DaySchedule;
  wednesday: DaySchedule;
  thursday: DaySchedule;
  friday: DaySchedule;
  saturday: DaySchedule;
  sunday: DaySchedule;
}

export interface Professional {
  id: string;
  name: string;
  role: string;
  photoUrl: string;
  workSchedule?: WorkSchedule; // Configuração JSON dos horários
}

export interface Coupon {
  id: string;
  code: string;
  type: 'percentage' | 'fixed';
  value: number;
  usageCount: number;
  active: boolean;
}

export interface Appointment {
  id: string;
  clientName: string;
  clientPhone: string;
  serviceIds: string[];
  professionalId: string | null; // null means "no preference"
  date: string; // YYYY-MM-DD
  time: string; // HH:mm
  totalValue: number;
  couponCode?: string;
  createdAt: string;
}

export interface ShopSettings {
  name: string;
  logoUrl: string | null;
  primaryColor: string;
  secondaryColor: string;
}

export interface ShopState {
  services: Service[];
  professionals: Professional[];
  coupons: Coupon[];
  appointments: Appointment[];
  settings: ShopSettings;
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ShopState, Service, Professional, Coupon, Appointment, ShopSettings, WorkSchedule } from './types';
import { supabase } from './supabaseClient';
import { Session } from '@supabase/supabase-js';

interface ShopContextType extends ShopState {
  session: Session | null;
  loading: boolean;

  // Auth Actions
  login: (email: string, password: string) => Promise<{ error: any }>;
  signup: (email: string, password: string, shopName: string) => Promise<{ error: any }>;
  logout: () => Promise<void>;

  addService: (service: Omit<Service, 'id'>) => Promise<void>;
  updateService: (id: string, service: Partial<Service>) => Promise<void>;
  removeService: (id: string) => Promise<void>;

  addProfessional: (professional: Omit<Professional, 'id'>) => Promise<void>;
  updateProfessional: (id: string, professional: Partial<Professional>) => Promise<void>;
  removeProfessional: (id: string) => Promise<void>;

  addCoupon: (coupon: Omit<Coupon, 'id' | 'usageCount'>) => Promise<void>;
  updateCoupon: (id: string, coupon: Partial<Coupon>) => Promise<void>;
  removeCoupon: (id: string) => Promise<void>;
  incrementCouponUsage: (code: string) => Promise<void>;

  addAppointment: (appointment: Omit<Appointment, 'id' | 'createdAt'>) => Promise<void>;

  updateSettings: (settings: Partial<ShopSettings>) => Promise<void>;
  refresh: () => void;
}

const ShopContext = createContext<ShopContextType | undefined>(undefined);

// Default Schedule helper
const DEFAULT_SCHEDULE: WorkSchedule = {
  monday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  tuesday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  wednesday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  thursday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  friday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  saturday: { start: '09:00', end: '17:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  sunday: { start: '09:00', end: '13:00', lunchStart: '00:00', lunchEnd: '00:00', active: false },
};

const INITIAL_STATE: ShopState = {
  settings: {
    name: "Carregando...",
    logoUrl: null,
    primaryColor: "#f97316",
    secondaryColor: "#1e293b",
  },
  services: [],
  professionals: [],
  coupons: [],
  appointments: []
};

export const ShopProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<ShopState>(INITIAL_STATE);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);

  // --- Helpers for mapping Snake_case (DB) to CamelCase (App) ---
  const mapSettings = (data: any): ShopSettings => ({
      name: data.name || "Minha Barbearia",
      logoUrl: data.logo_url,
      primaryColor: data.primary_color || "#f97316",
      secondaryColor: data.secondary_color || "#1e293b"
  });

  const mapService = (data: any): Service => ({
      id: data.id,
      name: data.name,
      description: data.description,
      price: data.price,
      duration: data.duration
  });

  const mapProfessional = (data: any): Professional => ({
      id: data.id,
      name: data.name,
      role: data.role,
      photoUrl: data.photo_url,
      workSchedule: data.work_schedule || DEFAULT_SCHEDULE
  });

  const mapCoupon = (data: any): Coupon => ({
      id: data.id,
      code: data.code,
      type: data.type,
      value: data.value,
      usageCount: data.usage_count,
      active: data.active
  });

  const mapAppointment = (data: any): Appointment => ({
      id: data.id,
      clientName: data.client_name,
      clientPhone: data.client_phone,
      serviceIds: data.service_ids || [], 
      professionalId: data.professional_id,
      date: data.date,
      time: data.time,
      totalValue: data.total_value,
      couponCode: data.coupon_code,
      createdAt: data.created_at
  });

  // --- Data Fetching ---
  const fetchData = async () => {
    try {
        // Parallel fetching
        const [settingsRes, servicesRes, prosRes, couponsRes] = await Promise.all([
            supabase.from('settings').select('*').limit(1).single(),
            supabase.from('services').select('*'),
            supabase.from('professionals').select('*'),
            supabase.from('coupons').select('*')
        ]);

        let appointmentsData: Appointment[] = [];

        // Fetch ALL appointments to check for conflicts (even if not logged in, we need the times)
        // Note: For RLS security, usually public users can only see dates/times, not client names.
        // For this demo, we assume the 'public' policy allows selecting necessary fields for conflict checking.
        // If RLS blocks this, you need a Postgres Function (RPC) to check availability without exposing data.
        // Here we assume we can fetch basic appointment info.
        const { data: appts } = await supabase.from('appointments').select('*').order('created_at', { ascending: false });
        if (appts) appointmentsData = appts.map(mapAppointment);


        if (settingsRes.data) {
             setState(prev => ({
                 ...prev,
                 settings: mapSettings(settingsRes.data),
                 services: (servicesRes.data || []).map(mapService),
                 professionals: (prosRes.data || []).map(mapProfessional),
                 coupons: (couponsRes.data || []).map(mapCoupon),
                 appointments: appointmentsData
             }));
        } else {
             // Handle initial case
             setState(prev => ({
                 ...prev,
                 services: (servicesRes.data || []).map(mapService),
                 professionals: (prosRes.data || []).map(mapProfessional),
                 coupons: (couponsRes.data || []).map(mapCoupon),
                 appointments: appointmentsData
             }));
        }

    } catch (error) {
        console.error("Error fetching data:", error);
    } finally {
        setLoading(false);
    }
  };

  // --- Auth Session Listener ---
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      fetchData();
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      fetchData(); 
    });

    return () => subscription.unsubscribe();
  }, [session?.user?.id]); 

  // --- Auth Actions ---
  const login = async (email: string, password: string) => {
      const { error } = await supabase.auth.signInWithPassword({ email, password });
      return { error };
  };

  const signup = async (email: string, password: string, shopName: string) => {
      const { data, error } = await supabase.auth.signUp({ email, password });
      if (!error && data.user) {
          await updateSettings({ name: shopName });
      }
      return { error };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      setState(INITIAL_STATE);
      fetchData();
  };


  // --- Database Actions ---

  const addService = async (service: Omit<Service, 'id'>) => {
    await supabase.from('services').insert({
        name: service.name,
        description: service.description,
        price: service.price,
        duration: service.duration
    });
    fetchData();
  };

  const updateService = async (id: string, updated: Partial<Service>) => {
    await supabase.from('services').update({
        name: updated.name,
        description: updated.description,
        price: updated.price,
        duration: updated.duration
    }).eq('id', id);
    fetchData();
  };

  const removeService = async (id: string) => {
    await supabase.from('services').delete().eq('id', id);
    fetchData();
  };

  const addProfessional = async (pro: Omit<Professional, 'id'>) => {
    await supabase.from('professionals').insert({
        name: pro.name,
        role: pro.role,
        photo_url: pro.photoUrl,
        work_schedule: pro.workSchedule || DEFAULT_SCHEDULE
    });
    fetchData();
  };

  const updateProfessional = async (id: string, updated: Partial<Professional>) => {
    const payload: any = {};
    if (updated.name) payload.name = updated.name;
    if (updated.role) payload.role = updated.role;
    if (updated.photoUrl) payload.photo_url = updated.photoUrl;
    if (updated.workSchedule) payload.work_schedule = updated.workSchedule;

    await supabase.from('professionals').update(payload).eq('id', id);
    fetchData();
  };

  const removeProfessional = async (id: string) => {
    await supabase.from('professionals').delete().eq('id', id);
    fetchData();
  };

  const addCoupon = async (coupon: Omit<Coupon, 'id' | 'usageCount'>) => {
    await supabase.from('coupons').insert({
        code: coupon.code,
        type: coupon.type,
        value: coupon.value,
        usage_count: 0,
        active: coupon.active
    });
    fetchData();
  };

  const updateCoupon = async (id: string, updated: Partial<Coupon>) => {
    const payload: any = {};
    if (updated.code) payload.code = updated.code;
    if (updated.type) payload.type = updated.type;
    if (updated.value) payload.value = updated.value;
    if (updated.active !== undefined) payload.active = updated.active;

    await supabase.from('coupons').update(payload).eq('id', id);
    fetchData();
  };

  const removeCoupon = async (id: string) => {
    await supabase.from('coupons').delete().eq('id', id);
    fetchData();
  };

  const incrementCouponUsage = async (code: string) => {
    const { data } = await supabase.from('coupons').select('usage_count').eq('code', code).single();
    if (data) {
        await supabase.from('coupons').update({ usage_count: data.usage_count + 1 }).eq('code', code);
        fetchData();
    }
  };

  const addAppointment = async (apt: Omit<Appointment, 'id' | 'createdAt'>) => {
    await supabase.from('appointments').insert({
        client_name: apt.clientName,
        client_phone: apt.clientPhone,
        service_ids: apt.serviceIds,
        professional_id: apt.professionalId,
        date: apt.date,
        time: apt.time,
        total_value: apt.totalValue,
        coupon_code: apt.couponCode
    });

    if (apt.couponCode) {
        await incrementCouponUsage(apt.couponCode);
    }
    // Refresh to update availability
    fetchData();
  };

  const updateSettings = async (updated: Partial<ShopSettings>) => {
    const { data } = await supabase.from('settings').select('id').limit(1).single();

    const payload: any = {};
    if (updated.name) payload.name = updated.name;
    if (updated.logoUrl) payload.logo_url = updated.logoUrl;
    if (updated.primaryColor) payload.primary_color = updated.primaryColor;
    if (updated.secondaryColor) payload.secondary_color = updated.secondaryColor;

    if (data && data.id) {
        await supabase.from('settings').update(payload).eq('id', data.id);
    } else {
        await supabase.from('settings').insert(payload);
    }
    fetchData();
  };

  return (
    <ShopContext.Provider value={{
      ...state,
      session,
      loading,
      login, signup, logout,
      addService, updateService, removeService,
      addProfessional, updateProfessional, removeProfessional,
      addCoupon, updateCoupon, removeCoupon, incrementCouponUsage,
      addAppointment,
      updateSettings,
      refresh: fetchData
    }}>
      {children}
    </ShopContext.Provider>
  );
};

export const useShop = () => {
  const context = useContext(ShopContext);
  if (!context) throw new Error("useShop must be used within a ShopProvider");
  return context;
};

