import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ShopState, Service, Professional, Coupon, Appointment, ShopSettings, WorkSchedule, Shop } from './types';
import { supabase } from './supabaseClient';
import { Session } from '@supabase/supabase-js';

interface ShopContextType extends ShopState {
  session: Session | null;
  loading: boolean;

  // Auth Actions
  login: (email: string, password: string) => Promise<{ error: any }>;
  signup: (email: string, password: string, shopName: string, slug: string) => Promise<{ error: any }>;
  logout: () => Promise<void>;

  // Data Loading (Client Mode)
  loadShopBySlug: (slug: string) => Promise<boolean>; 

  addService: (service: Omit<Service, 'id' | 'shopId'>) => Promise<void>;
  updateService: (id: string, service: Partial<Service>) => Promise<void>;
  removeService: (id: string) => Promise<void>;

  addProfessional: (professional: Omit<Professional, 'id' | 'shopId'>) => Promise<void>;
  updateProfessional: (id: string, professional: Partial<Professional>) => Promise<void>;
  removeProfessional: (id: string) => Promise<void>;

  addCoupon: (coupon: Omit<Coupon, 'id' | 'usageCount' | 'shopId'>) => Promise<void>;
  updateCoupon: (id: string, coupon: Partial<Coupon>) => Promise<void>;
  removeCoupon: (id: string) => Promise<void>;
  // incrementCouponUsage removido da interface pública pois agora é feito atomicamente no addAppointment

  addAppointment: (appointment: Omit<Appointment, 'id' | 'createdAt' | 'shopId'>) => Promise<{ success: boolean, error?: string }>;

  updateSettings: (settings: Partial<ShopSettings>) => Promise<void>;
  refresh: () => void;
}

const ShopContext = createContext<ShopContextType | undefined>(undefined);

// Default Schedule helper
const DEFAULT_SCHEDULE: WorkSchedule = {
  monday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  tuesday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  wednesday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  thursday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  friday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  saturday: { start: '09:00', end: '17:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  sunday: { start: '09:00', end: '13:00', lunchStart: '00:00', lunchEnd: '00:00', active: false },
};

const INITIAL_STATE: ShopState = {
  shop: null,
  settings: {
    shopId: "",
    name: "Carregando...",
    logoUrl: null,
    primaryColor: "#f97316",
    secondaryColor: "#1e293b",
  },
  services: [],
  professionals: [],
  coupons: [],
  appointments: []
};

export const ShopProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<ShopState>(INITIAL_STATE);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);

  // --- Mappers ---
  const mapShop = (data: any): Shop => ({
      id: data.id,
      ownerId: data.owner_id,
      name: data.name,
      slug: data.slug
  });

  const mapSettings = (data: any): ShopSettings => ({
      id: data.id,
      shopId: data.shop_id,
      name: data.name || "Minha Barbearia",
      logoUrl: data.logo_url,
      primaryColor: data.primary_color || "#f97316",
      secondaryColor: data.secondary_color || "#1e293b"
  });

  const mapService = (data: any): Service => ({
      id: data.id,
      shopId: data.shop_id,
      name: data.name,
      description: data.description,
      price: data.price,
      duration: data.duration
  });

  const mapProfessional = (data: any): Professional => ({
      id: data.id,
      shopId: data.shop_id,
      name: data.name,
      role: data.role,
      photoUrl: data.photo_url,
      workSchedule: data.work_schedule || DEFAULT_SCHEDULE
  });

  const mapCoupon = (data: any): Coupon => ({
      id: data.id,
      shopId: data.shop_id,
      code: data.code,
      type: data.type,
      value: data.value,
      usageCount: data.usage_count,
      active: data.active
  });

  const mapAppointment = (data: any): Appointment => ({
      id: data.id,
      shopId: data.shop_id,
      clientName: data.client_name,
      clientPhone: data.client_phone,
      serviceIds: data.service_ids || [], 
      professionalId: data.professional_id,
      date: data.date,
      time: data.time,
      totalValue: data.total_value,
      couponCode: data.coupon_code,
      createdAt: data.created_at
  });

  // --- Core Fetch Logic ---
  const fetchData = async (targetShopId?: string) => {
    try {
        let shopId = targetShopId;
        let currentShopData: Shop | null = state.shop;

        // If no target provided, check if we have a session (Admin Mode)
        if (!shopId && session?.user) {
            // Find the shop owned by this user
            const { data: shopData } = await supabase.from('shops').select('*').eq('owner_id', session.user.id).single();
            if (shopData) {
                shopId = shopData.id;
                currentShopData = mapShop(shopData);
            }
        } else if (!shopId && state.shop?.id) {
            // Use currently loaded shop
            shopId = state.shop.id;
        }

        if (!shopId) {
            setLoading(false);
            return; // Nothing to load yet
        }

        // Parallel fetching filtered by SHOP_ID
        const [settingsRes, servicesRes, prosRes, couponsRes] = await Promise.all([
            supabase.from('settings').select('*').eq('shop_id', shopId).single(),
            supabase.from('services').select('*').eq('shop_id', shopId),
            supabase.from('professionals').select('*').eq('shop_id', shopId),
            supabase.from('coupons').select('*').eq('shop_id', shopId)
        ]);

        let appointmentsData: Appointment[] = [];
        // Only fetch appointments if we are the owner or authorized (RLS handles this, but good to check)
        const { data: appts } = await supabase.from('appointments').select('*').eq('shop_id', shopId).order('created_at', { ascending: false });
        if (appts) appointmentsData = appts.map(mapAppointment);

        setState(prev => ({
            ...prev,
            shop: currentShopData || prev.shop,
            settings: settingsRes.data ? mapSettings(settingsRes.data) : { ...INITIAL_STATE.settings, shopId: shopId },
            services: (servicesRes.data || []).map(mapService),
            professionals: (prosRes.data || []).map(mapProfessional),
            coupons: (couponsRes.data || []).map(mapCoupon),
            appointments: appointmentsData
        }));

    } catch (error) {
        console.error("Error fetching data:", error);
    } finally {
        setLoading(false);
    }
  };

  // --- Auth Session Listener ---
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) fetchData(); // Automatically load admin's shop on login
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) fetchData();
    });

    return () => subscription.unsubscribe();
  }, []); // Run once on mount

  // --- Actions ---

  const login = async (email: string, password: string) => {
      const { error } = await supabase.auth.signInWithPassword({ email, password });
      return { error };
  };

  const signup = async (email: string, password: string, shopName: string, slug: string) => {
      // 1. Create Auth User
      const { data: authData, error: authError } = await supabase.auth.signUp({ email, password });
      if (authError || !authData.user) return { error: authError };

      // 2. Create Shop Record
      const { data: shopData, error: shopError } = await supabase.from('shops').insert({
          owner_id: authData.user.id,
          name: shopName,
          slug: slug
      }).select().single();

      if (shopError || !shopData) return { error: shopError };

      // 3. Create Default Settings
      await supabase.from('settings').insert({
          shop_id: shopData.id,
          name: shopName,
          primary_color: '#f97316',
          secondary_color: '#1e293b'
      });

      // 4. Force refresh to load new data
      setSession(authData.session);
      fetchData(); 

      return { error: null };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      setState(INITIAL_STATE);
  };

  const loadShopBySlug = async (slug: string) => {
      setLoading(true);
      const { data } = await supabase.from('shops').select('*').eq('slug', slug).single();
      if (data) {
          const shop = mapShop(data);
          setState(prev => ({ ...prev, shop }));
          await fetchData(shop.id);
          return true;
      }
      setLoading(false);
      return false;
  };

  // --- CRUD Wrappers (Always inject Shop ID) ---

  const ensureShopId = () => {
      if (!state.shop?.id) throw new Error("No active shop found");
      return state.shop.id;
  };

  const addService = async (service: Omit<Service, 'id' | 'shopId'>) => {
    const shopId = ensureShopId();
    await supabase.from('services').insert({ ...service, shop_id: shopId });
    fetchData(shopId);
  };

  const updateService = async (id: string, updated: Partial<Service>) => {
    await supabase.from('services').update(updated).eq('id', id);
    fetchData();
  };

  const removeService = async (id: string) => {
    await supabase.from('services').delete().eq('id', id);
    fetchData();
  };

  const addProfessional = async (pro: Omit<Professional, 'id' | 'shopId'>) => {
    const shopId = ensureShopId();
    await supabase.from('professionals').insert({
        shop_id: shopId,
        name: pro.name,
        role: pro.role,
        photo_url: pro.photoUrl,
        work_schedule: pro.workSchedule || DEFAULT_SCHEDULE
    });
    fetchData(shopId);
  };

  const updateProfessional = async (id: string, updated: Partial<Professional>) => {
    const payload: any = {};
    if (updated.name) payload.name = updated.name;
    if (updated.role) payload.role = updated.role;
    if (updated.photoUrl) payload.photo_url = updated.photoUrl;
    if (updated.workSchedule) payload.work_schedule = updated.workSchedule;

    await supabase.from('professionals').update(payload).eq('id', id);
    fetchData();
  };

  const removeProfessional = async (id: string) => {
    await supabase.from('professionals').delete().eq('id', id);
    fetchData();
  };

  const addCoupon = async (coupon: Omit<Coupon, 'id' | 'usageCount' | 'shopId'>) => {
    const shopId = ensureShopId();
    await supabase.from('coupons').insert({
        shop_id: shopId,
        code: coupon.code,
        type: coupon.type,
        value: coupon.value,
        usage_count: 0,
        active: coupon.active
    });
    fetchData(shopId);
  };

  const updateCoupon = async (id: string, updated: Partial<Coupon>) => {
    const payload: any = {};
    if (updated.code) payload.code = updated.code;
    if (updated.type) payload.type = updated.type;
    if (updated.value) payload.value = updated.value;
    if (updated.active !== undefined) payload.active = updated.active;

    await supabase.from('coupons').update(payload).eq('id', id);
    fetchData();
  };

  const removeCoupon = async (id: string) => {
    await supabase.from('coupons').delete().eq('id', id);
    fetchData();
  };

  // SEGURANÇA E CONSISTÊNCIA: Substituição do insert direto por RPC (Remote Procedure Call)
  // Isso garante que o backend verifique disponibilidade e incremente cupons atomicamente.
  const addAppointment = async (apt: Omit<Appointment, 'id' | 'createdAt' | 'shopId'>) => {
    const shopId = ensureShopId();

    // Chamada à função segura no Supabase (verifique se criou a função SQL)
    const { data, error } = await supabase.rpc('book_appointment', {
        p_shop_id: shopId,
        p_client_name: apt.clientName,
        p_client_phone: apt.clientPhone,
        p_service_ids: apt.serviceIds,
        p_professional_id: apt.professionalId,
        p_date: apt.date,
        p_time: apt.time,
        p_total_value: apt.totalValue,
        p_coupon_code: apt.couponCode
    });

    if (error) {
        console.error("Erro no agendamento:", error);
        return { success: false, error: error.message };
    }

    fetchData(shopId);
    return { success: true };
  };

  const updateSettings = async (updated: Partial<ShopSettings>) => {
    const shopId = ensureShopId();
    const { data } = await supabase.from('settings').select('id').eq('shop_id', shopId).single();

    const payload: any = {};
    if (updated.name) payload.name = updated.name;
    if (updated.logoUrl) payload.logo_url = updated.logoUrl;
    if (updated.primaryColor) payload.primary_color = updated.primaryColor;
    if (updated.secondaryColor) payload.secondary_color = updated.secondaryColor;

    if (data && data.id) {
        await supabase.from('settings').update(payload).eq('id', data.id);
    } else {
        await supabase.from('settings').insert({ ...payload, shop_id: shopId });
    }
    fetchData(shopId);
  };

  return (
    <ShopContext.Provider value={{
      ...state,
      session,
      loading,
      login, signup, logout,
      loadShopBySlug,
      addService, updateService, removeService,
      addProfessional, updateProfessional, removeProfessional,
      addCoupon, updateCoupon, removeCoupon,
      addAppointment,
      updateSettings,
      refresh: () => fetchData()
    }}>
      {children}
    </ShopContext.Provider>
  );
};

export const useShop = () => {
  const context = useContext(ShopContext);
  if (!context) throw new Error("useShop must be used within a ShopProvider");
  return context;
};

