export const Signup: React.FC<{ onComplete: () => void, onBack: () => void }> = ({ onComplete, onBack }) => {
    const { signup } = useShop();
    const [shopName, setShopName] = useState('');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [slug, setSlug] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [errorMsg, setErrorMsg] = useState('');

    const reservedSlugs = ['admin', 'login', 'signup', 'dashboard', 'api', 'auth'];

    const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const name = e.target.value;
        setShopName(name);
        // Auto-generate slug
        setSlug(name.toLowerCase()
            .replace(/[^\w\s-]/g, '')
            .replace(/\s+/g, '-')
        );
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        setErrorMsg('');

        if (reservedSlugs.includes(slug)) {
            setErrorMsg('Este link não é permitido. Por favor, escolha outro.');
            setIsLoading(false);
            return;
        }

        try {
            // Updated to pass slug
            const { error } = await signup(email, password, shopName, slug);
            if (error) {
                if (error.code === '23505') { // Unique violation
                    setErrorMsg('Este link de barbearia já está em uso.');
                } else {
                    setErrorMsg(error.message || 'Erro ao criar conta');
                }
            } else {
                onComplete();
            }
        } catch (err) {
            setErrorMsg('Erro inesperado.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
