import React, { useEffect } from 'react';
import { BrowserRouter, Routes, Route, useNavigate, useParams, Navigate } from 'react-router-dom';
import { ShopProvider, useShop } from './store';
import { AdminDashboard } from './components/admin/AdminDashboard';
import { BookingFlow } from './components/client/BookingFlow';
import { LandingPage } from './components/landing/LandingPage';
import { Signup } from './components/auth/Signup';
import { Login } from './components/auth/Login';
import { Loader2 } from 'lucide-react';

// Wrapper para carregar dados da barbearia baseado na URL
const BookingRoute = () => {
    const { slug } = useParams();
    const { loadShopBySlug, shop, loading } = useShop();

    useEffect(() => {
        if (slug) {
            loadShopBySlug(slug);
        }
    }, [slug]);

    if (loading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-slate-900 text-orange-500">
                <Loader2 className="animate-spin" size={40} />
            </div>
        );
    }

    if (!shop && !loading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-slate-900 text-slate-400">
                <p>Barbearia não encontrada.</p>
            </div>
        );
    }

    return <BookingFlow onAdminClick={() => window.location.href = '/login'} />;
};

// Wrapper para proteger rotas de Admin
const AdminRoute = () => {
    const { session, loading, shop } = useShop();
    const navigate = useNavigate();

    useEffect(() => {
        if (!loading && !session) {
            navigate('/login');
        }
    }, [session, loading, navigate]);

    if (loading) return null; // Or a spinner

    return session ? (
        <AdminDashboard 
            onLogout={() => { /* Logout handled in dashboard or global */ }} 
            onViewClient={() => window.open(`/agendar/${shop?.slug}`, '_blank')}
        />
    ) : null;
};

const AppRoutes = () => {
    const navigate = useNavigate();
    const { logout } = useShop();

    return (
        <Routes>
            <Route path="/" element={<LandingPage onStart={() => navigate('/signup')} onLogin={() => navigate('/login')} />} />
            <Route path="/signup" element={<Signup onComplete={() => navigate('/admin')} onBack={() => navigate('/')} />} />
            <Route path="/login" element={<Login onComplete={() => navigate('/admin')} onBack={() => navigate('/')} />} />
            <Route path="/admin" element={<AdminRoute />} />
            <Route path="/agendar/:slug" element={<BookingRoute />} />
            {/* Catch all redirect */}
            <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
    );
}

function App() {
  return (
    <ShopProvider>
        <BrowserRouter>
            <AppRoutes />
        </BrowserRouter>
    </ShopProvider>
  );
}

export default App;

import { createClient } from '@supabase/supabase-js';

// Alteração Crítica: Uso de variáveis de ambiente.
// Crie um arquivo .env na raiz do projeto com estas chaves.
// Casting import.meta to any to avoid TypeScript error if vite/client types are missing in tsconfig
const supabaseUrl = (import.meta as any).env.VITE_SUPABASE_URL;
const supabaseKey = (import.meta as any).env.VITE_SUPABASE_ANON_KEY;

if (!supabaseUrl || !supabaseKey) {
  console.error("ERRO CRÍTICO: Variáveis de ambiente do Supabase não encontradas.");
}

export const supabase = createClient(supabaseUrl, supabaseKey);

