      logoUrl: data.logo_url,
      primaryColor: data.primary_color || "#f97316",
      secondaryColor: data.secondary_color || "#1e293b"
  });

  const mapService = (data: any): Service => ({
      id: data.id,
      shopId: data.shop_id,
      name: data.name,
      description: data.description,
      price: data.price,
      duration: data.duration
  });

  const mapProfessional = (data: any): Professional => ({
      id: data.id,
      shopId: data.shop_id,
      name: data.name,
      role: data.role,
      photoUrl: data.photo_url,
      workSchedule: data.work_schedule || DEFAULT_SCHEDULE
  });

  const mapCoupon = (data: any): Coupon => ({
      id: data.id,
      shopId: data.shop_id,
      code: data.code,
      type: data.type,
      value: data.value,
      usageCount: data.usage_count,
      active: data.active
  });

  const mapAppointment = (data: any): Appointment => ({
      id: data.id,
      shopId: data.shop_id,
      clientName: data.client_name,
      clientPhone: data.client_phone,
      serviceIds: data.service_ids || [], 
      professionalId: data.professional_id,
      date: data.date,
      time: data.time,
      totalValue: data.total_value,
      couponCode: data.coupon_code,
      createdAt: data.created_at
  });

  // --- Core Fetch Logic ---
  const fetchData = async (targetShopId?: string) => {
    try {
        let shopId = targetShopId;
        let currentShopData: Shop | null = state.shop;

        if (!shopId && session?.user) {
            const { data: shopData } = await supabase.from('shops').select('*').eq('owner_id', session.user.id).single();
            if (shopData) {
                shopId = shopData.id;
                currentShopData = mapShop(shopData);
            }
        } else if (!shopId && state.shop?.id) {
            shopId = state.shop.id;
        }

        if (!shopId) {
            setLoading(false);
            return; 
        }

        const [settingsRes, servicesRes, prosRes, couponsRes] = await Promise.all([
            supabase.from('settings').select('*').eq('shop_id', shopId).single(),
            supabase.from('services').select('*').eq('shop_id', shopId),
            supabase.from('professionals').select('*').eq('shop_id', shopId),
            supabase.from('coupons').select('*').eq('shop_id', shopId)
        ]);

        let appointmentsData: Appointment[] = [];
        const { data: appts } = await supabase.from('appointments').select('*').eq('shop_id', shopId).order('created_at', { ascending: false });
        if (appts) appointmentsData = appts.map(mapAppointment);

        setState(prev => ({
            ...prev,
            shop: currentShopData || prev.shop,
            settings: settingsRes.data ? mapSettings(settingsRes.data) : { ...INITIAL_STATE.settings, shopId: shopId },
            services: (servicesRes.data || []).map(mapService),
            professionals: (prosRes.data || []).map(mapProfessional),
            coupons: (couponsRes.data || []).map(mapCoupon),
            appointments: appointmentsData
        }));

    } catch (error) {
        console.error("Error fetching data:", error);
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) fetchData();
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) fetchData();
    });

    return () => subscription.unsubscribe();
  }, []);

  // --- Actions with Sanitization ---

  const login = async (email: string, password: string) => {
      const { error } = await supabase.auth.signInWithPassword({ email, password });
      return { error };
  };

  const signup = async (email: string, password: string, shopName: string, slug: string) => {
      // Sanitize Inputs
      const cleanShopName = sanitize(shopName);
      const cleanSlug = sanitize(slug).toLowerCase().replace(/[^\w-]/g, '');

      const { data: authData, error: authError } = await supabase.auth.signUp({ email, password });
      if (authError || !authData.user) return { error: authError };

      const { data: shopData, error: shopError } = await supabase.from('shops').insert({
          owner_id: authData.user.id,
          name: cleanShopName,
          slug: cleanSlug
      }).select().single();

      if (shopError || !shopData) return { error: shopError };

      await supabase.from('settings').insert({
          shop_id: shopData.id,
          name: cleanShopName,
          primary_color: '#f97316',
          secondary_color: '#1e293b'
      });

      setSession(authData.session);
      fetchData(); 

      return { error: null };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      setState(INITIAL_STATE);
  };

  const loadShopBySlug = async (slug: string) => {
      setLoading(true);
      const cleanSlug = sanitize(slug); // Sanitize query param
      const { data } = await supabase.from('shops').select('*').eq('slug', cleanSlug).single();
      if (data) {
          const shop = mapShop(data);
          setState(prev => ({ ...prev, shop }));
          await fetchData(shop.id);
          return true;
      }
      setLoading(false);
      return false;
  };

  const ensureShopId = () => {
      if (!state.shop?.id) throw new Error("No active shop found");
      return state.shop.id;
  };

  const addService = async (service: Omit<Service, 'id' | 'shopId'>) => {
    const shopId = ensureShopId();
    await supabase.from('services').insert({ 
      ...service, 
      name: sanitize(service.name),
      description: sanitize(service.description),
      shop_id: shopId 
    });
    fetchData(shopId);
  };

  const updateService = async (id: string, updated: Partial<Service>) => {
    const payload: any = {};
    if (updated.name) payload.name = sanitize(updated.name);
    if (updated.description) payload.description = sanitize(updated.description);
    if (updated.price !== undefined) payload.price = updated.price;
    if (updated.duration !== undefined) payload.duration = updated.duration;

    await supabase.from('services').update(payload).eq('id', id);
    fetchData();
  };

  const removeService = async (id: string) => {
    await supabase.from('services').delete().eq('id', id);
    fetchData();
  };

  const addProfessional = async (pro: Omit<Professional, 'id' | 'shopId'>) => {
    const shopId = ensureShopId();
    await supabase.from('professionals').insert({
        shop_id: shopId,
        name: sanitize(pro.name),
        role: sanitize(pro.role),
        photo_url: pro.photoUrl, // URLs should be validated, but usually safe if from trusted bucket
        work_schedule: pro.workSchedule || DEFAULT_SCHEDULE
    });
    fetchData(shopId);
  };

  const updateProfessional = async (id: string, updated: Partial<Professional>) => {
    const payload: any = {};
    if (updated.name) payload.name = sanitize(updated.name);
    if (updated.role) payload.role = sanitize(updated.role);
    if (updated.photoUrl) payload.photo_url = updated.photoUrl;
    if (updated.workSchedule) payload.work_schedule = updated.workSchedule;

    await supabase.from('professionals').update(payload).eq('id', id);
    fetchData();
  };

  const removeProfessional = async (id: string) => {
    await supabase.from('professionals').delete().eq('id', id);
    fetchData();
  };

  const addCoupon = async (coupon: Omit<Coupon, 'id' | 'usageCount' | 'shopId'>) => {
    const shopId = ensureShopId();
    await supabase.from('coupons').insert({
        shop_id: shopId,
        code: sanitize(coupon.code).toUpperCase(),
        type: coupon.type,
        value: coupon.value,
        usage_count: 0,
        active: coupon.active
    });
    fetchData(shopId);
  };

  const updateCoupon = async (id: string, updated: Partial<Coupon>) => {
    const payload: any = {};
    if (updated.code) payload.code = sanitize(updated.code).toUpperCase();
    if (updated.type) payload.type = updated.type;
    if (updated.value) payload.value = updated.value;
    if (updated.active !== undefined) payload.active = updated.active;

    await supabase.from('coupons').update(payload).eq('id', id);
    fetchData();
  };

  const removeCoupon = async (id: string) => {
    await supabase.from('coupons').delete().eq('id', id);
    fetchData();
  };

  const addAppointment = async (apt: Omit<Appointment, 'id' | 'createdAt' | 'shopId'>) => {
    const shopId = ensureShopId();

    // Sanitização de dados do cliente (crítico para prevenir XSS no painel admin)
    const cleanClientName = sanitize(apt.clientName);
    const cleanClientPhone = sanitize(apt.clientPhone);

    const { data, error } = await supabase.rpc('book_appointment', {
        p_shop_id: shopId,
        p_client_name: cleanClientName,
        p_client_phone: cleanClientPhone,
        p_service_ids: apt.serviceIds,
        p_professional_id: apt.professionalId,
        p_date: apt.date,
        p_time: apt.time,
        p_total_value: apt.totalValue,
        p_coupon_code: apt.couponCode ? sanitize(apt.couponCode) : null
    });

    if (error) {
        console.error("Erro no agendamento:", error);
        return { success: false, error: error.message };
    }

    fetchData(shopId);
    return { success: true };
  };

  const updateSettings = async (updated: Partial<ShopSettings>) => {
    const shopId = ensureShopId();
    const { data } = await supabase.from('settings').select('id').eq('shop_id', shopId).single();

    const payload: any = {};
    if (updated.name) payload.name = sanitize(updated.name);
    if (updated.logoUrl) payload.logo_url = updated.logoUrl;
    if (updated.primaryColor) payload.primary_color = sanitize(updated.primaryColor);
    if (updated.secondaryColor) payload.secondary_color = sanitize(updated.secondaryColor);

    if (data && data.id) {
        await supabase.from('settings').update(payload).eq('id', data.id);
    } else {
        await supabase.from('settings').insert({ ...payload, shop_id: shopId });
    }
    fetchData(shopId);
  };

  return (
    <ShopContext.Provider value={{
      ...state,
      session,
      loading,
      login, signup, logout,
      loadShopBySlug,
      addService, updateService, removeService,
      addProfessional, updateProfessional, removeProfessional,
      addCoupon, updateCoupon, removeCoupon,
      addAppointment,
      updateSettings,
      refresh: () => fetchData()
    }}>
      {children}
    </ShopContext.Provider>
  );
};

export const useShop = () => {
  const context = useContext(ShopContext);
  if (!context) throw new Error("useShop must be used within a ShopProvider");
  return context;
};

import React, { useEffect } from 'react';
import { BrowserRouter, Routes, Route, useNavigate, useParams, Navigate } from 'react-router-dom';
import { ShopProvider, useShop } from './store';
import { AdminDashboard } from './components/admin/AdminDashboard';
import { BookingFlow } from './components/client/BookingFlow';
import { LandingPage } from './components/landing/LandingPage';
import { Signup } from './components/auth/Signup';
import { Login } from './components/auth/Login';
import { Loader2 } from 'lucide-react';

// Wrapper para carregar dados da barbearia baseado na URL
const BookingRoute = () => {
    const { slug } = useParams();
    const { loadShopBySlug, shop, loading } = useShop();

    useEffect(() => {
        if (slug) {
            loadShopBySlug(slug);
        }
    }, [slug]);

    if (loading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-slate-900 text-orange-500">
                <Loader2 className="animate-spin" size={40} />
            </div>
        );
    }

    if (!shop && !loading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-slate-900 text-slate-400">
                <p>Barbearia não encontrada.</p>
            </div>
        );
    }

    return <BookingFlow onAdminClick={() => window.location.href = '/login'} />;
};

// Wrapper para proteger rotas de Admin
const AdminRoute = () => {
    const { session, loading, shop } = useShop();
    const navigate = useNavigate();

    useEffect(() => {
        if (!loading && !session) {
            navigate('/login');
        }
    }, [session, loading, navigate]);

    if (loading) return null; // Or a spinner

    return session ? (
        <AdminDashboard 
            onLogout={() => { /* Logout handled in dashboard or global */ }} 
            onViewClient={() => window.open(`/agendar/${shop?.slug}`, '_blank')}
        />
    ) : null;
};

const AppRoutes = () => {
    const navigate = useNavigate();
    const { logout } = useShop();

    return (
        <Routes>
            <Route path="/" element={<LandingPage onStart={() => navigate('/signup')} onLogin={() => navigate('/login')} />} />
            <Route path="/signup" element={<Signup onComplete={() => navigate('/admin')} onBack={() => navigate('/')} />} />
            <Route path="/login" element={<Login onComplete={() => navigate('/admin')} onBack={() => navigate('/')} />} />
            <Route path="/admin" element={<AdminRoute />} />
            <Route path="/agendar/:slug" element={<BookingRoute />} />
            {/* Catch all redirect */}
            <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
    );
}

function App() {
  // SEGURANÇA: Force HTTPS
  // Redireciona HTTP para HTTPS se não estiver rodando no localhost
  useEffect(() => {
    if (
        window.location.protocol !== 'https:' && 
        window.location.hostname !== 'localhost' && 
        window.location.hostname !== '127.0.0.1'
    ) {
        console.log('Forcing HTTPS connection...');
        window.location.href = 'https://' + window.location.hostname + window.location.pathname + window.location.search;
    }
  }, []);

  return (
    <ShopProvider>
        <BrowserRouter>
            <AppRoutes />
        </BrowserRouter>
    </ShopProvider>
  );
}

export default App;

