// Helper function to safely access environment variables
// Supports both Vite (import.meta.env) and standard (process.env)
const getEnvVar = (key: string): string => {
  // Check import.meta.env (Vite)
  try {
    // @ts-ignore
    if (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env[key]) {
      // @ts-ignore
      return import.meta.env[key];
    }
  } catch (e) {
    // Ignore errors if import.meta is not available
  }

  // Check process.env (Common in many build environments)
  try {
    if (typeof process !== 'undefined' && process.env && process.env[key]) {
      return process.env[key];
    }
  } catch (e) {
    // Ignore
  }

  return '';
};

// Tenta pegar do ambiente. Não há mais fallbacks hardcoded inseguros.
const supabaseUrl = getEnvVar('VITE_SUPABASE_URL');
const supabaseKey = getEnvVar('VITE_SUPABASE_ANON_KEY');

// SEGURANÇA: Validação estrita.
// Se as chaves não existirem no ambiente, a aplicação deve falhar imediatamente
// para evitar exposição de dados ou conexão com ambientes errados.
if (!supabaseUrl || !supabaseKey) {
  const errorMsg = "ERRO DE CONFIGURAÇÃO: As credenciais do Supabase não foram encontradas. Certifique-se de que VITE_SUPABASE_URL e VITE_SUPABASE_ANON_KEY estão definidas no arquivo .env ou nas variáveis de ambiente do servidor.";
  console.error(errorMsg);
  throw new Error(errorMsg);
}

export const supabase = createClient(supabaseUrl, supabaseKey);

