    setStep: (s: any) => void;
    settings: any;
    subtotal: number;
}

export const ServicesStep: React.FC<ServicesStepProps> = ({ services, selectedServiceIds, setSelectedServiceIds, setStep, settings, subtotal }) => {

    const toggleService = (id: string) => {
        if (selectedServiceIds.includes(id)) {
            setSelectedServiceIds(prev => prev.filter(i => i !== id));
        } else {
            setSelectedServiceIds(prev => [...prev, id]);
        }
    };

    const groupedServices = useMemo(() => {
        return services.reduce((acc, service) => {
            const cat = service.category || 'Geral';
            if (!acc[cat]) acc[cat] = [];
            acc[cat].push(service);
            return acc;
        }, {} as Record<string, typeof services>);
    }, [services]);

    const sortedCategories = Object.keys(groupedServices).sort();

    return (
        <div className="max-w-2xl mx-auto py-8 px-4 pb-32">
            <div className="mb-6">
