interface ShopContextType extends ShopState {
  session: Session | null;
  loading: boolean;
  userRole: 'owner' | 'barber' | null;

  // Auth Actions
  login: (email: string, password: string) => Promise<{ error: any }>;
  signup: (email: string, password: string, shopName: string, slug: string, intent: 'create_shop' | 'join_team') => Promise<{ error: any }>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{ success: boolean, error?: string }>;

  // Data Loading
  loadShopBySlug: (slug: string) => Promise<boolean>; 
  refresh: () => void;

  // Actions - Now returning MutationResult
  addService: (service: Omit<Service, 'id' | 'shopId'>) => MutationResult;
  updateService: (id: string, service: Partial<Service>) => MutationResult;
  removeService: (id: string) => MutationResult;

  addProfessional: (professional: Omit<Professional, 'id' | 'shopId'>) => MutationResult;
  updateProfessional: (id: string, professional: Partial<Professional>) => MutationResult;
  removeProfessional: (id: string) => MutationResult;

  addCoupon: (coupon: Omit<Coupon, 'id' | 'usageCount' | 'shopId'>) => MutationResult;
  updateCoupon: (id: string, coupon: Partial<Coupon>) => MutationResult;
  removeCoupon: (id: string) => MutationResult;

  addAppointment: (appointment: Omit<Appointment, 'id' | 'createdAt' | 'shopId'>) => MutationResult;
  updateAppointmentStatus: (id: string, status: string) => MutationResult;

  addBlockedSlot: (block: Omit<BlockedSlot, 'id' | 'shopId'>) => MutationResult;
  removeBlockedSlot: (id: string) => MutationResult;

  updateSettings: (settings: Partial<ShopSettings>) => MutationResult;
}

const ShopContext = createContext<ShopContextType | undefined>(undefined);

// Default Schedule helper
const DEFAULT_SCHEDULE: WorkSchedule = {
  monday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  tuesday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  wednesday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  thursday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  friday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  saturday: { start: '09:00', end: '17:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  sunday: { start: '09:00', end: '13:00', lunchStart: '00:00', lunchEnd: '00:00', active: false },
};

const INITIAL_STATE: ShopState = {
  shop: null,
  settings: {
    shopId: "",
    name: "Carregando...",
    logoUrl: null,
    primaryColor: "#f97316",
    secondaryColor: "#1e293b",
  },
  services: [],
  professionals: [],
  coupons: [],
  appointments: [],
  blockedSlots: []
};

const sanitize = (text: string): string => {
  if (!text) return '';
  return DOMPurify.sanitize(text, {
    ALLOWED_TAGS: [],
    ALLOWED_ATTR: []
  });
};

export const ShopProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<ShopState>(INITIAL_STATE);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  const [userRole, setUserRole] = useState<'owner' | 'barber' | null>(null);

  // --- Mappers (Mantidos iguais) ---
  const mapShop = (data: any): Shop => ({
      id: data.id,
      ownerId: data.owner_id,
      name: data.name,
      slug: data.slug
  });

  const mapSettings = (data: any): ShopSettings => ({
      id: data.id,
      shopId: data.shop_id,
      name: data.name || "Minha Barbearia",
      logoUrl: data.logo_url,
      primaryColor: data.primary_color || "#f97316",
      secondaryColor: data.secondary_color || "#1e293b"
  });

  const mapService = (data: any): Service => ({
      id: data.id,
      shopId: data.shop_id,
      name: data.name,
      description: data.description,
      price: data.price,
      duration: data.duration,
      category: data.category || 'Geral'
  });

  const mapProfessional = (data: any): Professional => ({
      id: data.id,
      shopId: data.shop_id,
      name: data.name,
      role: data.role,
      photoUrl: data.photo_url,
      workSchedule: data.work_schedule || DEFAULT_SCHEDULE,
      email: data.email,
      userId: data.user_id
  });

  const mapCoupon = (data: any): Coupon => ({
      id: data.id,
      shopId: data.shop_id,
      code: data.code,
      type: data.type,
      value: data.value,
      usageCount: data.usage_count,
      active: data.active
  });

  const mapAppointment = (data: any): Appointment => ({
      id: data.id,
      shopId: data.shop_id,
      clientName: data.client_name,
      clientPhone: data.client_phone,
      serviceIds: data.service_ids || [], 
      professionalId: data.professional_id,
      date: data.date,
      time: data.time,
      totalValue: data.total_value,
      couponCode: data.coupon_code,
      createdAt: data.created_at,
      status: data.status || 'scheduled'
  });

  const mapBlockedSlot = (data: any): BlockedSlot => ({
      id: data.id,
      shopId: data.shop_id,
      professionalId: data.professional_id,
      date: data.date,
      startTime: data.start_time,
      endTime: data.end_time,
      reason: data.reason
  });

  // --- Core Fetch Logic ---
  const fetchData = async (targetShopId?: string) => {
    setLoading(true);
    try {
        let shopId = targetShopId;
        let currentShopData: Shop | null = state.shop;

        const { data: { session: currentSession } } = await supabase.auth.getSession();
        const userId = currentSession?.user?.id;
        const userEmail = currentSession?.user?.email;

        // 1. Tenta encontrar a loja onde o usuário é DONO
        if (!shopId && userId) {
            const { data: shopData } = await supabase.from('shops').select('*').eq('owner_id', userId).single();
            if (shopData) {
                shopId = shopData.id;
                currentShopData = mapShop(shopData);
            }
        } 

        // 2. Se não achou como dono, verifica se é BARBEIRO em alguma loja
        if (!shopId && userEmail) {
             const { data: proData } = await supabase.from('professionals').select('shop_id').eq('email', userEmail).single();
             if (proData) {
                 const { data: shopData } = await supabase.from('shops').select('*').eq('id', proData.shop_id).single();
                 if (shopData) {
                    shopId = shopData.id;
                    currentShopData = mapShop(shopData);
                 }
             }
        }

        // 3. Fallback: Se já temos um shop carregado no state (view de cliente)
        if (!shopId && state.shop?.id) {
            shopId = state.shop.id;
        }

        if (!shopId) {
            setLoading(false);
            return; 
        }

        const [settingsRes, servicesRes, prosRes, couponsRes, blocksRes] = await Promise.all([
            supabase.from('settings').select('*').eq('shop_id', shopId).single(),
            supabase.from('services').select('*').eq('shop_id', shopId),
            supabase.from('professionals').select('*').eq('shop_id', shopId),
            supabase.from('coupons').select('*').eq('shop_id', shopId),
            supabase.from('blocked_slots').select('*').eq('shop_id', shopId)
        ]);

        let appointmentsData: Appointment[] = [];
        const { data: appts } = await supabase.from('appointments').select('*').eq('shop_id', shopId).order('created_at', { ascending: false });
        if (appts) appointmentsData = appts.map(mapAppointment);

        const mappedProfessionals = (prosRes.data || []).map(mapProfessional);

        // --- LÓGICA DE ROLES ---
        if (currentSession?.user) {
            if (currentShopData?.ownerId === currentSession.user.id) {
                setUserRole('owner');
            } else {
                const isBarber = mappedProfessionals.find(p => p.email === currentSession.user.email);
                if (isBarber) {
                    setUserRole('barber');
                    if (!isBarber.userId) {
                        await supabase.from('professionals').update({ user_id: currentSession.user.id }).eq('id', isBarber.id);
                        isBarber.userId = currentSession.user.id;
                    }
                } else {
                    setUserRole(null);
                }
            }
        } else {
            setUserRole(null);
        }

        setState(prev => ({
            ...prev,
            shop: currentShopData || prev.shop,
            settings: settingsRes.data ? mapSettings(settingsRes.data) : { ...INITIAL_STATE.settings, shopId: shopId },
            services: (servicesRes.data || []).map(mapService),
            professionals: mappedProfessionals,
            coupons: (couponsRes.data || []).map(mapCoupon),
            appointments: appointmentsData,
            blockedSlots: (blocksRes.data || []).map(mapBlockedSlot)
        }));

    } catch (error) {
        console.error("Error fetching data:", error);
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session: activeSession } }) => {
      setSession(activeSession);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, activeSession) => {
      setSession(activeSession);
    });

    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (session?.user) {
      fetchData();
    } else if (!loading && !session) {
      setState(INITIAL_STATE);
      setUserRole(null);
    }
  }, [session]);

  const login = async (email: string, password: string) => {
      const { error } = await supabase.auth.signInWithPassword({ email, password });
      return { error };
  };

  const resetPassword = async (email: string) => {
      const { error } = await supabase.auth.resetPasswordForEmail(email, {
          redirectTo: window.location.origin + '/update-password', 
      });
      if (error) return { success: false, error: error.message };
      return { success: true };
  };

  const signup = async (email: string, password: string, shopName: string, slug: string, intent: 'create_shop' | 'join_team') => {
      const cleanShopName = sanitize(shopName);
      const cleanSlug = sanitize(slug).toLowerCase().replace(/[^\w-]/g, '');

      const { data: authData, error: authError } = await supabase.auth.signUp({ email, password });
      if (authError || !authData.user) return { error: authError };

      if (intent === 'join_team') {
          const { data: proData } = await supabase.from('professionals').select('id, shop_id').eq('email', email).single();

          if (proData) {
              await supabase.from('professionals').update({ user_id: authData.user.id }).eq('id', proData.id);
              setSession(authData.session);
              return { error: null };
          } else {
              return { error: { message: 'Este email não consta na lista de profissionais de nenhuma barbearia.' } };
          }
      }

      const { data: shopData, error: shopError } = await supabase.from('shops').insert({
          owner_id: authData.user.id,
          name: cleanShopName,
          slug: cleanSlug
      }).select().single();

      if (shopError || !shopData) return { error: shopError };

      await supabase.from('settings').insert({
          shop_id: shopData.id,
          name: cleanShopName,
          primary_color: '#f97316',
          secondary_color: '#1e293b'
      });

      // Default services
      const defaultServices = [
        { name: 'Corte Masculino', price: 30, duration: 30, category: 'Cortes' },
        { name: 'Barba', price: 20, duration: 20, category: 'Barba' },
        { name: 'Corte + Barba', price: 45, duration: 50, category: 'Combos' }
      ];
      const servicesToInsert = defaultServices.map(s => ({
          shop_id: shopData.id,
          name: s.name,
          description: s.name,
          price: s.price,
          duration: s.duration,
          category: s.category
      }));
      await supabase.from('services').insert(servicesToInsert);

      setSession(authData.session);
      return { error: null };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      setState(INITIAL_STATE);
      setSession(null);
      setUserRole(null);
  };

  const loadShopBySlug = async (slug: string) => {
      setLoading(true);
      const cleanSlug = sanitize(slug);
      const { data } = await supabase.from('shops').select('*').eq('slug', cleanSlug).single();
      if (data) {
          const shop = mapShop(data);
          setState(prev => ({ ...prev, shop }));
          await fetchData(shop.id);
          return true;
      }
      setLoading(false);
      return false;
  };

  const ensureShopId = () => {
      if (!state.shop?.id) {
          throw new Error("Loja não identificada. Recarregue a página.");
      }
      return state.shop.id;
  };

  // --- ACTIONS WITH ERROR HANDLING ---

  const addService = async (service: Omit<Service, 'id' | 'shopId'>): MutationResult => {
    try {
        const shopId = ensureShopId();
        const { error } = await supabase.from('services').insert({ 
          ...service, 
          name: sanitize(service.name),
          description: sanitize(service.description),
          category: sanitize(service.category),
          shop_id: shopId 
        });
        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const updateService = async (id: string, updated: Partial<Service>): MutationResult => {
    try {
        const payload: any = {};
        if (updated.name) payload.name = sanitize(updated.name);
        if (updated.description) payload.description = sanitize(updated.description);
        if (updated.price !== undefined) payload.price = updated.price;
        if (updated.duration !== undefined) payload.duration = updated.duration;
        if (updated.category) payload.category = sanitize(updated.category);

        const { error } = await supabase.from('services').update(payload).eq('id', id);
        if (error) throw error;
        await fetchData();
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const removeService = async (id: string): MutationResult => {
    try {
        const { error } = await supabase.from('services').delete().eq('id', id);
        if (error) throw error;
        await fetchData();
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const addProfessional = async (pro: Omit<Professional, 'id' | 'shopId'>): MutationResult => {
    try {
        const shopId = ensureShopId();
        const { error } = await supabase.from('professionals').insert({
            shop_id: shopId,
            name: sanitize(pro.name),
            role: sanitize(pro.role),
            photo_url: pro.photoUrl,
            work_schedule: pro.workSchedule || DEFAULT_SCHEDULE,
            email: pro.email ? sanitize(pro.email) : null
        });
        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const updateProfessional = async (id: string, updated: Partial<Professional>): MutationResult => {
    try {
        const payload: any = {};
        if (updated.name) payload.name = sanitize(updated.name);
        if (updated.role) payload.role = sanitize(updated.role);
        if (updated.photoUrl) payload.photo_url = updated.photoUrl;
        if (updated.workSchedule) payload.work_schedule = updated.workSchedule;
        if (updated.email !== undefined) payload.email = updated.email ? sanitize(updated.email) : null;

        const { error } = await supabase.from('professionals').update(payload).eq('id', id);
        if (error) throw error;
        await fetchData();
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const removeProfessional = async (id: string): MutationResult => {
    try {
        const { error } = await supabase.from('professionals').delete().eq('id', id);
        if (error) throw error;
        await fetchData();
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const addCoupon = async (coupon: Omit<Coupon, 'id' | 'usageCount' | 'shopId'>): MutationResult => {
    try {
        const shopId = ensureShopId();
        const { error } = await supabase.from('coupons').insert({
            shop_id: shopId,
            code: sanitize(coupon.code).toUpperCase(),
            type: coupon.type,
            value: coupon.value,
            usage_count: 0,
            active: coupon.active
        });
        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const updateCoupon = async (id: string, updated: Partial<Coupon>): MutationResult => {
    try {
        const payload: any = {};
        if (updated.code) payload.code = sanitize(updated.code).toUpperCase();
        if (updated.type) payload.type = updated.type;
        if (updated.value) payload.value = updated.value;
        if (updated.active !== undefined) payload.active = updated.active;

        const { error } = await supabase.from('coupons').update(payload).eq('id', id);
        if (error) throw error;
        await fetchData();
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const removeCoupon = async (id: string): MutationResult => {
    try {
        const { error } = await supabase.from('coupons').delete().eq('id', id);
        if (error) throw error;
        await fetchData();
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const addAppointment = async (apt: Omit<Appointment, 'id' | 'createdAt' | 'shopId'>): MutationResult => {
    try {
        const shopId = ensureShopId();
        const cleanClientName = sanitize(apt.clientName);
        const cleanClientPhone = sanitize(apt.clientPhone);

        const { error } = await supabase.rpc('book_appointment', {
            p_shop_id: shopId,
            p_client_name: cleanClientName,
            p_client_phone: cleanClientPhone,
            p_service_ids: apt.serviceIds,
            p_professional_id: apt.professionalId,
            p_date: apt.date,
            p_time: apt.time,
            p_total_value: apt.totalValue,
            p_coupon_code: apt.couponCode ? sanitize(apt.couponCode) : null
        });

        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const updateAppointmentStatus = async (id: string, status: string): MutationResult => {
    try {
        const { error } = await supabase.from('appointments').update({ status }).eq('id', id);
        if (error) throw error;
        await fetchData();
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const addBlockedSlot = async (block: Omit<BlockedSlot, 'id' | 'shopId'>): MutationResult => {
    try {
        const shopId = ensureShopId();
        const { error } = await supabase.from('blocked_slots').insert({
            shop_id: shopId,
            professional_id: block.professionalId,
            date: block.date,
            start_time: block.startTime,
            end_time: block.endTime,
            reason: sanitize(block.reason || '')
        });
        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const removeBlockedSlot = async (id: string): MutationResult => {
    try {
        const { error } = await supabase.from('blocked_slots').delete().eq('id', id);
        if (error) throw error;
        await fetchData();
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const updateSettings = async (updated: Partial<ShopSettings>): MutationResult => {
    try {
        const shopId = ensureShopId();
        const { data } = await supabase.from('settings').select('id').eq('shop_id', shopId).single();

        const payload: any = {};
        if (updated.name) payload.name = sanitize(updated.name);
        if (updated.logoUrl) payload.logo_url = updated.logoUrl;
        if (updated.primaryColor) payload.primary_color = sanitize(updated.primaryColor);
        if (updated.secondaryColor) payload.secondary_color = sanitize(updated.secondaryColor);

        let error;
        if (data && data.id) {
            ({ error } = await supabase.from('settings').update(payload).eq('id', data.id));
        } else {
            ({ error } = await supabase.from('settings').insert({ ...payload, shop_id: shopId }));
        }

        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  return (
    <ShopContext.Provider value={{
      ...state,
      session,
      loading,
      userRole,
      login, signup, logout,
      loadShopBySlug,
      resetPassword,
      addService, updateService, removeService,
      addProfessional, updateProfessional, removeProfessional,
      addCoupon, updateCoupon, removeCoupon,
      addAppointment,
      updateAppointmentStatus,
      addBlockedSlot, removeBlockedSlot,
      updateSettings,
      refresh: () => fetchData()
    }}>
      {children}
    </ShopContext.Provider>
  );
};

export const useShop = () => {
  const context = useContext(ShopContext);
  if (!context) throw new Error("useShop must be used within a ShopProvider");
  return context;
};

import React, { useState, useRef } from 'react';
import { useShop } from '../../../store';
import { supabase } from '../../../supabaseClient';
import { Professional, WorkSchedule, DaySchedule } from '../../../types';
import { ConfirmationModal } from '../../ui/ConfirmationModal';
import { Plus, Trash2, Edit2, Upload, Loader2, Clock, X } from 'lucide-react';
import { useToast } from '../../ui/ToastContext';

const DEFAULT_DAY: DaySchedule = { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true };

export const TeamPanel: React.FC = () => {
    const { professionals, addProfessional, updateProfessional, removeProfessional, blockedSlots, addBlockedSlot, removeBlockedSlot, settings } = useShop();
    const { showToast } = useToast();

    const [isFormOpen, setIsFormOpen] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [deleteId, setDeleteId] = useState<string | null>(null);

    // Modal de Bloqueios
    const [isBlockModalOpen, setIsBlockModalOpen] = useState(false);
    const [selectedProForBlock, setSelectedProForBlock] = useState<Professional | null>(null);
    const [blockDate, setBlockDate] = useState('');
    const [blockStart, setBlockStart] = useState('08:00');
    const [blockEnd, setBlockEnd] = useState('18:00');
    const [blockReason, setBlockReason] = useState('Folga / Médico');

    // Form States
    const [name, setName] = useState('');
    const [role, setRole] = useState('');
    const [email, setEmail] = useState('');
    const [photo, setPhoto] = useState<string | null>(null);
    const [isUploading, setIsUploading] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    const [schedule, setSchedule] = useState<WorkSchedule>({
        monday: {...DEFAULT_DAY}, tuesday: {...DEFAULT_DAY}, wednesday: {...DEFAULT_DAY},
        thursday: {...DEFAULT_DAY}, friday: {...DEFAULT_DAY}, saturday: {...DEFAULT_DAY},
        sunday: {...DEFAULT_DAY, active: false}
    });

    const [isScheduleOpen, setIsScheduleOpen] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            setIsUploading(true);
            try {
                const fileExt = file.name.split('.').pop();
                const fileName = `${Date.now()}_${Math.random().toString(36).substring(2)}.${fileExt}`;
                const filePath = `professionals/${fileName}`;
                const { error: uploadError } = await supabase.storage.from('images').upload(filePath, file);
                if (uploadError) throw uploadError;
                const { data } = supabase.storage.from('images').getPublicUrl(filePath);
                setPhoto(data.publicUrl);
                showToast('Foto enviada com sucesso!');
            } catch (error) {
                console.error("Erro no upload:", error);
                showToast('Erro ao fazer upload da imagem.', 'error');
            } finally {
                setIsUploading(false);
            }
        }
    };

    const handleEdit = (pro: Professional) => {
        setEditingId(pro.id);
        setName(pro.name);
        setRole(pro.role);
        setEmail(pro.email || '');
        setPhoto(pro.photoUrl);
        if (pro.workSchedule) setSchedule(pro.workSchedule);
        setIsFormOpen(true);
        setIsScheduleOpen(false);
    };

    const confirmDelete = async () => {
        if (deleteId) {
            const { success, error } = await removeProfessional(deleteId);
            if (success) {
                showToast('Profissional removido com sucesso!');
                setDeleteId(null);
            } else {
                showToast(error || 'Erro ao remover.', 'error');
            }
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        const proData = { 
            name, 
            role, 
            email: email.toLowerCase().trim(),
            photoUrl: photo || 'https://picsum.photos/200', 
            workSchedule: schedule 
        };

        let result;
        if (editingId) {
            result = await updateProfessional(editingId, proData);
        } else {
            result = await addProfessional(proData);
        }

        setIsSaving(false);

        if (result.success) {
            showToast(editingId ? 'Profissional atualizado!' : 'Profissional adicionado!');
            setIsFormOpen(false);
            setEditingId(null);
            setName(''); setRole(''); setEmail(''); setPhoto(null);
        } else {
            showToast(result.error || 'Ocorreu um erro.', 'error');
        }
    };

    const handleAddBlock = async (e: React.FormEvent) => {
        e.preventDefault();
        if (selectedProForBlock) {
            const { success, error } = await addBlockedSlot({
                professionalId: selectedProForBlock.id,
                date: blockDate,
                startTime: blockStart,
                endTime: blockEnd,
                reason: blockReason
            });

            if (success) {
                showToast('Bloqueio adicionado!');
                setBlockReason('Folga / Médico');
            } else {
                showToast(error || 'Erro ao bloquear.', 'error');
            }
        }
    };

    const handleRemoveBlock = async (id: string) => {
        const { success, error } = await removeBlockedSlot(id);
        if (success) {
            showToast('Bloqueio removido.');
        } else {
            showToast(error || 'Erro ao remover.', 'error');
        }
    }

    const toggleDay = (day: keyof WorkSchedule) => {
        setSchedule(prev => ({ ...prev, [day]: { ...prev[day], active: !prev[day].active } }));
    };

    const updateDayTime = (day: keyof WorkSchedule, field: keyof DaySchedule, value: string) => {
        setSchedule(prev => ({ ...prev, [day]: { ...prev[day], [field]: value } }));
    };

    const daysMap: {[key: string]: string} = {
        monday: 'Segunda', tuesday: 'Terça', wednesday: 'Quarta', thursday: 'Quinta',
        friday: 'Sexta', saturday: 'Sábado', sunday: 'Domingo'
    };

    return (
        <div>
            <ConfirmationModal 
                isOpen={!!deleteId}
                onClose={() => setDeleteId(null)}
                onConfirm={confirmDelete}
                title="Remover Profissional"
                message="Tem certeza que deseja remover este profissional? Esta ação não pode ser desfeita."
                confirmText="Remover"
                isDestructive
            />

            {/* Modal de Bloqueios */}
            {isBlockModalOpen && selectedProForBlock && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-fade-in">
                    <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 w-full max-w-md shadow-2xl relative animate-scale-up">
                        <button onClick={() => setIsBlockModalOpen(false)} className="absolute top-4 right-4 text-slate-500 hover:text-white"><X size={20} /></button>
                        <h3 className="text-lg font-bold text-white mb-4">Gerenciar Bloqueios: {selectedProForBlock.name.split(' ')[0]}</h3>

                        <div className="mb-6 bg-slate-900/50 rounded-lg p-3 max-h-40 overflow-y-auto border border-slate-700">
                            <h4 className="text-xs font-bold text-slate-400 uppercase mb-2">Bloqueios Ativos</h4>
                            {blockedSlots.filter(b => b.professionalId === selectedProForBlock.id).length === 0 ? (
                                <p className="text-sm text-slate-500 italic">Nenhum bloqueio cadastrado.</p>
                            ) : (
                                <div className="space-y-2">
                                    {blockedSlots.filter(b => b.professionalId === selectedProForBlock.id).map(b => (
                                        <div key={b.id} className="flex justify-between items-center bg-slate-800 p-2 rounded border border-slate-700">
                                            <div>
                                                <div className="text-sm text-white font-medium">{new Date(b.date + 'T12:00:00').toLocaleDateString('pt-BR')}</div>
                                                <div className="text-xs text-slate-400">{b.startTime} - {b.endTime} • {b.reason}</div>
                                            </div>
                                            <button onClick={() => handleRemoveBlock(b.id)} className="text-red-500 hover:text-red-400 p-1"><Trash2 size={16}/></button>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>

                        <form onSubmit={handleAddBlock} className="space-y-3">
                            <h4 className="text-xs font-bold text-slate-400 uppercase">Adicionar Novo</h4>
                            <input required type="date" value={blockDate} onChange={e => setBlockDate(e.target.value)} className="w-full bg-slate-900 border border-slate-700 rounded p-2 text-white text-sm" />
                            <div className="flex gap-2">
                                <input required type="time" value={blockStart} onChange={e => setBlockStart(e.target.value)} className="flex-1 bg-slate-900 border border-slate-700 rounded p-2 text-white text-sm" />
                                <span className="text-slate-400 self-center">-</span>
                                <input required type="time" value={blockEnd} onChange={e => setBlockEnd(e.target.value)} className="flex-1 bg-slate-900 border border-slate-700 rounded p-2 text-white text-sm" />
                            </div>
                            <input required type="text" value={blockReason} onChange={e => setBlockReason(e.target.value)} placeholder="Motivo (ex: Médico)" className="w-full bg-slate-900 border border-slate-700 rounded p-2 text-white text-sm" />
                            <button type="submit" className="w-full bg-orange-500 hover:bg-orange-600 text-white font-bold py-2 rounded-lg text-sm">Adicionar Bloqueio</button>
                        </form>
                    </div>
                </div>
            )}

            <div className="flex justify-between mb-8">
                <p className="text-slate-400">Adicione, edite ou remova profissionais da sua equipe.</p>
                <button onClick={() => { setIsFormOpen(true); setEditingId(null); setName(''); setRole(''); setEmail(''); setPhoto(null); }} className="flex items-center gap-2 px-4 py-2 rounded-lg text-white font-medium hover:opacity-90 transition-opacity" style={{ backgroundColor: settings.primaryColor }}>
                    <Plus size={18} /> Adicionar Profissional
                </button>
            </div>

            {isFormOpen && (
                <div className="mb-8 bg-slate-800 p-6 rounded-xl border border-slate-700 animate-fade-in-down">
                     <h3 className="text-lg font-bold mb-4">{editingId ? 'Editar Profissional' : 'Novo Profissional'}</h3>
                     <form onSubmit={handleSubmit} className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm text-slate-400 mb-1">Nome Completo</label>
                                <input required value={name} onChange={e => setName(e.target.value)} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" placeholder="Ex: Carlos Silva" />
                            </div>
                            <div>
                                <label className="block text-sm text-slate-400 mb-1">Especialidade/Cargo</label>
                                <input required value={role} onChange={e => setRole(e.target.value)} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" placeholder="Ex: Master Barber" />
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm text-slate-400 mb-1">Email de Acesso (Opcional)</label>
                            <input 
                                type="email"
                                value={email} 
                                onChange={e => setEmail(e.target.value)} 
                                className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" 
                                placeholder="barbeiro@exemplo.com" 
                            />
                            <p className="text-xs text-slate-500 mt-1">Se preenchido, o barbeiro poderá fazer login usando este email.</p>
                        </div>

                        <div>
                            <label className="block text-sm text-slate-400 mb-1">Foto do Perfil</label>
                            <div className="flex items-center gap-4">
                                <div onClick={() => !isUploading && fileInputRef.current?.click()} className={`w-16 h-16 bg-slate-900 rounded-full border border-dashed border-slate-600 flex items-center justify-center cursor-pointer hover:border-orange-500 overflow-hidden relative ${isUploading ? 'opacity-50 cursor-not-allowed' : ''}`}>
                                    {isUploading ? <Loader2 size={24} className="text-orange-500 animate-spin" /> : (photo ? <img src={photo} alt="Preview" className="w-full h-full object-cover" /> : <Upload size={20} className="text-slate-500" />)}
                                </div>
                                <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" disabled={isUploading} />
                                <span className="text-sm text-slate-500">{isUploading ? 'Enviando...' : 'Clique para carregar uma foto'}</span>
                            </div>
                        </div>

                        <div className="border border-slate-700 rounded-lg overflow-hidden">
                             <button type="button" onClick={() => setIsScheduleOpen(!isScheduleOpen)} className="w-full bg-slate-800/50 p-3 flex justify-between items-center text-left hover:bg-slate-700 transition-colors">
                                 <span className="font-medium flex items-center gap-2"><Clock size={16} /> Horários de Atendimento</span>
                                 <span className="text-xs text-slate-400">{isScheduleOpen ? 'Recolher' : 'Configurar'}</span>
                             </button>
                             {isScheduleOpen && (
                                 <div className="p-4 bg-slate-900/50 space-y-3">
                                     {Object.entries(schedule).map(([key, val]) => {
                                         const day = val as DaySchedule;
                                         return (
                                             <div key={key} className="flex flex-col md:flex-row md:items-center gap-3 pb-3 border-b border-slate-800 last:border-0">
                                                 <div className="w-24">
                                                     <label className="flex items-center gap-2 cursor-pointer">
                                                         <input type="checkbox" checked={day.active} onChange={() => toggleDay(key as keyof WorkSchedule)} className="rounded border-slate-600 text-orange-500 focus:ring-orange-500 bg-slate-800" />
                                                         <span className={day.active ? 'text-white' : 'text-slate-500'}>{daysMap[key]}</span>
                                                     </label>
                                                 </div>
                                                 {day.active && (
                                                    <div className="flex flex-wrap items-center gap-2 text-sm">
                                                        <input type="time" value={day.start} onChange={e => updateDayTime(key as keyof WorkSchedule, 'start', e.target.value)} className="bg-slate-800 border border-slate-700 rounded px-2 py-1 text-white" />
                                                        <span className="text-slate-500">até</span>
                                                        <input type="time" value={day.end} onChange={e => updateDayTime(key as keyof WorkSchedule, 'end', e.target.value)} className="bg-slate-800 border border-slate-700 rounded px-2 py-1 text-white" />
                                                        <span className="text-slate-500 ml-2">Almoço:</span>
                                                        <input type="time" value={day.lunchStart} onChange={e => updateDayTime(key as keyof WorkSchedule, 'lunchStart', e.target.value)} className="bg-slate-800 border border-slate-700 rounded px-2 py-1 text-white" />
                                                        <span className="text-slate-500">-</span>
                                                        <input type="time" value={day.lunchEnd} onChange={e => updateDayTime(key as keyof WorkSchedule, 'lunchEnd', e.target.value)} className="bg-slate-800 border border-slate-700 rounded px-2 py-1 text-white" />
                                                    </div>
                                                 )}
                                             </div>
                                         );
                                     })}
                                 </div>
                             )}
                        </div>

                        <div className="flex gap-2 justify-end pt-2">
                             <button type="button" onClick={() => setIsFormOpen(false)} className="px-4 py-2 text-slate-400 hover:text-white" disabled={isUploading || isSaving}>Cancelar</button>
                             <button type="submit" className="px-6 py-2 rounded-lg text-white flex items-center gap-2" style={{ backgroundColor: settings.primaryColor }} disabled={isUploading || isSaving}>
                                {(isUploading || isSaving) && <Loader2 size={16} className="animate-spin"/>} Salvar
                             </button>
                        </div>
                     </form>
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {professionals.map(pro => (
                    <div key={pro.id} className="bg-slate-800 rounded-xl p-6 border border-slate-700 hover:border-slate-600 transition-colors flex flex-col items-center text-center">
                        <img src={pro.photoUrl} alt={pro.name} className="w-24 h-24 rounded-full object-cover mb-4 border-2 border-slate-600" />
                        <h3 className="font-bold text-lg">{pro.name}</h3>
                        <p className="text-slate-400 text-sm">{pro.role}</p>
                        {pro.email && <p className="text-xs text-blue-400 mt-1 mb-2">{pro.email}</p>}

                        <div className="w-full mt-4 space-y-2">
                            <button type="button" onClick={() => { setSelectedProForBlock(pro); setIsBlockModalOpen(true); }} className="w-full py-2 bg-slate-700 rounded-lg text-slate-300 hover:bg-slate-600 flex items-center justify-center gap-2 text-sm">
                                <Clock size={14}/> Bloqueios
                            </button>
                            <div className="flex gap-2">
                                <button type="button" onClick={() => handleEdit(pro)} className="flex-1 py-2 bg-slate-700 rounded-lg text-slate-300 hover:bg-slate-600 flex items-center justify-center gap-2 text-sm"><Edit2 size={14}/> Editar</button>
                                <button type="button" onClick={() => setDeleteId(pro.id)} className="flex-1 py-2 bg-red-500/10 text-red-500 border border-red-500/20 rounded-lg hover:bg-red-500/20 flex items-center justify-center gap-2 text-sm"><Trash2 size={14}/> Excluir</button>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { useShop } from '../../../store';
import { Service } from '../../../types';
import { ConfirmationModal } from '../../ui/ConfirmationModal';
import { Plus, Edit2, Trash2, CalendarCheck, Loader2 } from 'lucide-react';
import { useToast } from '../../ui/ToastContext';

export const ServicesPanel: React.FC = () => {
    const { services, addService, updateService, removeService, settings } = useShop();
    const { showToast } = useToast();

    const [isFormOpen, setIsFormOpen] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [deleteId, setDeleteId] = useState<string | null>(null);
    const [formData, setFormData] = useState({ name: '', description: '', price: '', duration: '', category: 'Cortes' });
    const [isSaving, setIsSaving] = useState(false);

    // Categorias disponíveis
    const CATEGORIES = ['Cortes', 'Barba', 'Combos', 'Química', 'Estética', 'Outros'];

    // CATALOGO PRE-DEFINIDO
    const CATALOG = [
        { name: 'Acabamento ("pézinho")', category: 'Cortes' },
        { name: 'Barba Completa', category: 'Barba' },
        { name: 'Coloração/Descoloração', category: 'Química' },
        { name: 'Combo Corte e Barba', category: 'Combos' },
        { name: 'Corte Infantil', category: 'Cortes' },
        { name: 'Corte Masculino', category: 'Cortes' },
        { name: 'Design de Sobrancelha', category: 'Estética' },
        { name: 'Hidratação e Reconstrução', category: 'Química' },
        { name: 'Limpeza de Pele', category: 'Estética' },
        { name: 'Luzes', category: 'Química' },
        { name: 'Nano Botox Capilar', category: 'Química' },
        { name: 'Nano Progressiva', category: 'Química' },
        { name: 'Penteado', category: 'Outros' },
        { name: 'Pigmentação/Camuflagem', category: 'Barba' },
        { name: 'Platinado', category: 'Química' },
        { name: 'Relaxamento/Progressiva', category: 'Química' }
    ];

    // Lógica de Agrupamento
    const groupedServices = services.reduce((acc, service) => {
        const cat = service.category || 'Outros';
        if (!acc[cat]) acc[cat] = [];
        acc[cat].push(service);
        return acc;
    }, {} as Record<string, typeof services>);

    const handleEdit = (service: Service) => {
        setEditingId(service.id);
        setFormData({
            name: service.name,
            description: service.description,
            price: service.price.toString(),
            duration: service.duration.toString(),
            category: service.category || 'Cortes'
        });
        setIsFormOpen(true);
    };

    const handleTemplateSelect = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const selectedName = e.target.value;
        if (!selectedName) return;

        const template = CATALOG.find(item => item.name === selectedName);
        if (template) {
            setFormData(prev => ({
                ...prev,
                name: template.name,
                category: template.category,
                description: prev.description || template.name 
            }));
        }
    };

    const confirmDelete = async () => {
        if (deleteId) {
            const { success, error } = await removeService(deleteId);
            if (success) {
                showToast('Serviço removido com sucesso!');
                setDeleteId(null);
            } else {
                showToast(error || 'Erro ao remover serviço.', 'error');
            }
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        const serviceData = {
            name: formData.name,
            description: formData.description,
            price: Number(formData.price),
            duration: Number(formData.duration),
            category: formData.category
        };

        let result;
        if (editingId) {
            result = await updateService(editingId, serviceData);
        } else {
            result = await addService(serviceData);
        }

        setIsSaving(false);

        if (result.success) {
            showToast(editingId ? 'Serviço atualizado!' : 'Serviço criado!');
            setIsFormOpen(false);
            setEditingId(null);
            setFormData({ name: '', description: '', price: '', duration: '', category: 'Cortes' });
        } else {
            showToast(result.error || 'Erro ao salvar.', 'error');
        }
    };

    return (
        <div>
            <ConfirmationModal 
                isOpen={!!deleteId}
                onClose={() => setDeleteId(null)}
                onConfirm={confirmDelete}
                title="Remover Serviço"
                message="Tem certeza que deseja remover este serviço? Ele não aparecerá mais para agendamentos."
                confirmText="Remover"
                isDestructive
            />

             <div className="flex justify-between mb-8">
                <p className="text-slate-400">Adicione, edite ou remova serviços oferecidos.</p>
                <button onClick={() => { setIsFormOpen(true); setEditingId(null); setFormData({ name: '', description: '', price: '', duration: '', category: 'Cortes' }); }} className="flex items-center gap-2 px-4 py-2 rounded-lg text-white font-medium hover:opacity-90" style={{ backgroundColor: settings.primaryColor }}>
                    <Plus size={18} /> Adicionar Serviço
                </button>
            </div>

            {isFormOpen && (
                 <div className="mb-8 bg-slate-800 p-6 rounded-xl border border-slate-700 animate-fade-in-down">
                     <div className="flex justify-between items-start mb-4">
                        <h3 className="text-lg font-bold">{editingId ? 'Editar Serviço' : 'Novo Serviço'}</h3>

                        {!editingId && (
                            <div className="flex items-center gap-2">
                                <span className="text-xs text-slate-400 uppercase font-bold">Catálogo Rápido:</span>
                                <select 
                                    onChange={handleTemplateSelect}
                                    className="bg-slate-900 border border-slate-600 text-slate-300 text-sm rounded-lg p-2 focus:outline-none focus:border-orange-500"
                                >
                                    <option value="">-- Selecione --</option>
                                    {CATALOG.map((item, idx) => (
                                        <option key={idx} value={item.name}>{item.name}</option>
                                    ))}
                                </select>
                            </div>
                        )}
                     </div>

                     <form onSubmit={handleSubmit} className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                             <div>
                                <label className="block text-sm text-slate-400 mb-1">Nome do Serviço</label>
                                <input required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" placeholder="Ex: Corte Masculino"/>
                            </div>
                            <div>
                                <label className="block text-sm text-slate-400 mb-1">Duração (minutos)</label>
                                <input required type="number" value={formData.duration} onChange={e => setFormData({...formData, duration: e.target.value})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" placeholder="30" />
                            </div>
                            <div>
                                <label className="block text-sm text-slate-400 mb-1">Preço (R$)</label>
                                <input required type="number" value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" placeholder="0.00" />
                            </div>
                            <div>
                                <label className="block text-sm text-slate-400 mb-1">Descrição Curta</label>
                                <input required value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" placeholder="Breve detalhe do serviço" />
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm text-slate-400 mb-1">Categoria</label>
                            <div className="flex gap-2 flex-wrap mb-2">
                                {CATEGORIES.map(cat => (
                                    <button
                                        key={cat}
                                        type="button"
                                        onClick={() => setFormData({...formData, category: cat})}
                                        className={`px-3 py-1 rounded-full text-sm border transition-colors ${formData.category === cat ? 'bg-orange-500 border-orange-500 text-white' : 'border-slate-600 text-slate-400 hover:border-slate-400'}`}
                                    >
                                        {cat}
                                    </button>
                                ))}
                            </div>
                             <input 
                                value={formData.category} 
                                onChange={e => setFormData({...formData, category: e.target.value})} 
                                className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none" 
                                placeholder="Ou digite uma nova categoria..."
                            />
                        </div>

                        <div className="flex gap-2 justify-end pt-2">
                             <button type="button" onClick={() => setIsFormOpen(false)} className="px-4 py-2 text-slate-400 hover:text-white" disabled={isSaving}>Cancelar</button>
                             <button type="submit" className="px-6 py-2 rounded-lg text-white flex items-center gap-2" style={{ backgroundColor: settings.primaryColor }} disabled={isSaving}>
                                {isSaving && <Loader2 size={16} className="animate-spin"/>} Salvar
                             </button>
                        </div>
                     </form>
                 </div>
            )}

            <div className="space-y-8">
                {Object.entries(groupedServices).map(([category, items]) => (
                    <div key={category}>
                        <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
                            <span className="w-2 h-8 rounded bg-orange-500 block"></span>
                            {category}
                        </h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {items.map(service => (
                                <div key={service.id} className="bg-slate-800 rounded-xl p-6 border border-slate-700 flex flex-col md:flex-row md:items-center justify-between gap-4">
                                    <div>
                                        <h3 className="font-bold text-lg">{service.name}</h3>
                                        <p className="text-slate-400 text-sm">{service.description}</p>
                                        <div className="flex items-center gap-4 mt-2">
                                            <span className="text-orange-500 font-bold" style={{ color: settings.primaryColor }}>R$ {service.price.toFixed(2)}</span>
                                            <span className="text-slate-500 text-sm flex items-center gap-1"><CalendarCheck size={12}/> {service.duration} min</span>
                                        </div>
                                    </div>
                                    <div className="flex gap-3">
                                         <button type="button" onClick={() => handleEdit(service)} className="px-4 py-2 bg-slate-700 rounded-lg text-slate-300 hover:bg-slate-600 flex items-center gap-2 text-sm"><Edit2 size={14}/> Editar</button>
                                         <button type="button" onClick={() => setDeleteId(service.id)} className="px-4 py-2 bg-red-500/10 text-red-500 border border-red-500/20 rounded-lg hover:bg-red-500/20 flex items-center gap-2 text-sm"><Trash2 size={14}/> Remover</button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { useShop } from '../../../store';
import { Coupon } from '../../../types';
import { ConfirmationModal } from '../../ui/ConfirmationModal';
import { Plus, Tag, X, Loader2 } from 'lucide-react';
import { useToast } from '../../ui/ToastContext';

export const CouponsPanel: React.FC = () => {
    const { coupons, addCoupon, updateCoupon, removeCoupon, settings } = useShop();
    const { showToast } = useToast();

    const [isFormOpen, setIsFormOpen] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [deleteId, setDeleteId] = useState<string | null>(null);
    const [isSaving, setIsSaving] = useState(false);
    const [formData, setFormData] = useState<{
        code: string;
        value: string;
        type: 'percentage' | 'fixed'
    }>({ code: '', value: '', type: 'percentage' });

    const handleEdit = (coupon: Coupon) => {
        setEditingId(coupon.id);
        setFormData({
            code: coupon.code,
            value: coupon.value.toString(),
            type: coupon.type
        });
        setIsFormOpen(true);
    };

    const confirmDelete = async () => {
        if (deleteId) {
            const { success, error } = await removeCoupon(deleteId);
            if (success) {
                showToast('Cupom removido com sucesso!');
                setDeleteId(null);
            } else {
                showToast(error || 'Erro ao remover cupom.', 'error');
            }
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        const couponData = {
            code: formData.code.toUpperCase(),
            value: Number(formData.value),
            type: formData.type,
            active: true
        };

        let result;
        if (editingId) {
            result = await updateCoupon(editingId, couponData);
        } else {
            result = await addCoupon(couponData);
        }

        setIsSaving(false);

        if (result.success) {
            showToast(editingId ? 'Cupom atualizado!' : 'Cupom criado!');
            setIsFormOpen(false);
            setEditingId(null);
            setFormData({ code: '', value: '', type: 'percentage' });
        } else {
            showToast(result.error || 'Erro ao salvar.', 'error');
        }
    };

    return (
        <div>
            <ConfirmationModal 
                isOpen={!!deleteId}
                onClose={() => setDeleteId(null)}
                onConfirm={confirmDelete}
                title="Remover Cupom"
                message="Tem certeza que deseja remover este cupom? Ele não poderá mais ser utilizado."
                confirmText="Remover"
                isDestructive
            />

            <div className="flex justify-between mb-8">
                <p className="text-slate-400">Gerencie cupons de desconto.</p>
                <button onClick={() => { setIsFormOpen(true); setEditingId(null); setFormData({ code: '', value: '', type: 'percentage' }); }} className="flex items-center gap-2 px-4 py-2 rounded-lg text-white font-medium hover:opacity-90" style={{ backgroundColor: settings.primaryColor }}>
                    <Plus size={18} /> Criar Cupom
                </button>
            </div>

            {isFormOpen && (
                 <div className="mb-8 bg-slate-800 p-6 rounded-xl border border-slate-700 animate-fade-in-down relative">
                     <button onClick={() => setIsFormOpen(false)} className="absolute top-4 right-4 text-slate-500 hover:text-white"><X size={20}/></button>
                     <h3 className="text-lg font-bold mb-4">{editingId ? 'Editar Cupom' : 'Novo Cupom'}</h3>
                     <form onSubmit={handleSubmit} className="flex flex-col md:flex-row gap-4 items-end">
                        <div className="flex-1 w-full">
                            <label className="block text-sm text-slate-400 mb-1">Código</label>
                            <input required value={formData.code} onChange={e => setFormData({...formData, code: e.target.value})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none uppercase" placeholder="Ex: VERAO10" />
                        </div>
                        <div className="w-full md:w-40">
                             <label className="block text-sm text-slate-400 mb-1">Tipo</label>
                             <select value={formData.type} onChange={e => setFormData({...formData, type: e.target.value as any})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none">
                                <option value="percentage">Porcentagem (%)</option>
                                <option value="fixed">Fixo (R$)</option>
                             </select>
                        </div>
                        <div className="w-full md:w-32">
                            <label className="block text-sm text-slate-400 mb-1">Valor</label>
                            <input required type="number" value={formData.value} onChange={e => setFormData({...formData, value: e.target.value})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none" />
                        </div>
                        <button type="submit" className="w-full md:w-auto px-6 py-3 rounded-lg text-white font-medium flex items-center justify-center gap-2" style={{ backgroundColor: settings.primaryColor }} disabled={isSaving}>
                            {isSaving && <Loader2 size={16} className="animate-spin" />}
                            {editingId ? 'Salvar' : 'Criar'}
                        </button>
                     </form>
                 </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {coupons.map(coupon => (
                    <div key={coupon.id} className="bg-slate-800 rounded-xl p-6 border border-slate-700 relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-2 opacity-10 group-hover:opacity-20 transition-opacity">
                            <Tag size={64} />
                        </div>
                        <div className="flex items-center gap-2 mb-2">
                             <Tag size={16} className="text-slate-400" />
                             <span className="font-bold text-lg tracking-wider">{coupon.code}</span>
                        </div>
                        <div className="text-3xl font-bold mb-4" style={{ color: settings.primaryColor }}>
                            {coupon.type === 'percentage' ? `${coupon.value}%` : `R$ ${coupon.value.toFixed(2)}`}
                            <span className="text-sm text-slate-400 font-normal ml-2">de desconto</span>
                        </div>
                        <div className="flex items-center justify-between text-sm text-slate-400 mb-6">
                            <span>Usado {coupon.usageCount}x</span>
                            <span className={`px-2 py-0.5 rounded-full text-xs border ${coupon.active ? 'border-green-500/30 text-green-500 bg-green-500/10' : 'border-red-500/30 text-red-500'}`}>
                                {coupon.active ? 'Ativo' : 'Inativo'}
                            </span>
                        </div>
                        <div className="flex gap-2">
                             <button type="button" onClick={() => handleEdit(coupon)} className="flex-1 py-2 bg-slate-700 rounded-lg text-slate-300 hover:bg-slate-600">Editar</button>
                             <button type="button" onClick={() => setDeleteId(coupon.id)} className="flex-1 py-2 bg-red-500/10 text-red-500 border border-red-500/20 rounded-lg hover:bg-red-500/20">Remover</button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

import React, { useState, useRef } from 'react';
import { useShop } from '../../../store';
import { supabase } from '../../../supabaseClient';
import { Upload, Edit2, Loader2 } from 'lucide-react';
import { useToast } from '../../ui/ToastContext';

export const DesignPanel: React.FC = () => {
    const { settings, updateSettings } = useShop();
    const { showToast } = useToast();

    const [name, setName] = useState(settings.name);
    const [primary, setPrimary] = useState(settings.primaryColor);
    const [secondary, setSecondary] = useState(settings.secondaryColor);
    const [logo, setLogo] = useState<string | null>(settings.logoUrl);
    const [isUploading, setIsUploading] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            setIsUploading(true);
            try {
                const fileExt = file.name.split('.').pop();
                const fileName = `${Date.now()}_${Math.random().toString(36).substring(2)}.${fileExt}`;
                const filePath = `logos/${fileName}`;
                const { error: uploadError } = await supabase.storage.from('images').upload(filePath, file);
                if (uploadError) throw uploadError;
                const { data } = supabase.storage.from('images').getPublicUrl(filePath);
                setLogo(data.publicUrl);
                showToast('Logo enviada com sucesso!');
            } catch (error) {
                console.error("Erro no upload:", error);
                showToast('Erro ao fazer upload do logotipo.', 'error');
            } finally {
                setIsUploading(false);
            }
        }
    };

    const handleSave = async () => {
        setIsSaving(true);
        const { success, error } = await updateSettings({ name, primaryColor: primary, secondaryColor: secondary, logoUrl: logo });
        setIsSaving(false);

        if (success) {
            showToast('Design atualizado com sucesso!');
        } else {
            showToast(error || 'Erro ao salvar configurações.', 'error');
        }
    };

    return (
        <div className="max-w-2xl">
            <div className="mb-8">
                <p className="text-slate-400">Personalize a identidade visual da sua barbearia.</p>
            </div>

            <div className="bg-slate-800 rounded-xl p-8 border border-slate-700 space-y-6">
                 {/* Logo Upload */}
                 <div>
                    <label className="block text-sm text-slate-400 mb-2">Logotipo</label>
                    <div className="flex items-center gap-4">
                        <div onClick={() => !isUploading && fileInputRef.current?.click()} className={`w-20 h-20 bg-slate-900 rounded-xl border border-dashed border-slate-600 flex items-center justify-center cursor-pointer hover:border-orange-500 overflow-hidden relative group ${isUploading ? 'cursor-not-allowed opacity-50' : ''}`}>
                             {isUploading ? (
                                <Loader2 size={24} className="text-orange-500 animate-spin" />
                             ) : (
                                logo ? <img src={logo} alt="Logo" className="w-full h-full object-cover" /> : <Upload size={24} className="text-slate-500" />
                             )}
                            {!isUploading && logo && (
                                <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                                    <Edit2 size={16} className="text-white"/>
                                </div>
                            )}
                        </div>
                        <input type="file" ref={fileInputRef} onChange={handleLogoUpload} className="hidden" accept="image/*" disabled={isUploading} />
                        <div>
                             <button type="button" onClick={() => !isUploading && fileInputRef.current?.click()} className="text-sm text-slate-300 hover:text-white underline mb-1" disabled={isUploading}>
                                 {isUploading ? 'Enviando...' : 'Alterar logotipo'}
                             </button>
                             <p className="text-xs text-slate-500">Recomendado: 512x512px</p>
                        </div>
                    </div>
                </div>

                <div>
                    <label className="block text-sm text-slate-400 mb-2">Nome da Barbearia</label>
                    <input value={name} onChange={e => setName(e.target.value)} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                         <label className="block text-sm text-slate-400 mb-2">Cor Primária (Destaques)</label>
                         <div className="flex items-center gap-3">
                             <input type="color" value={primary} onChange={e => setPrimary(e.target.value)} className="w-12 h-12 rounded bg-transparent cursor-pointer" />
                             <input value={primary} onChange={e => setPrimary(e.target.value)} className="flex-1 bg-slate-900 border border-slate-700 rounded-lg p-3 text-white uppercase" />
                         </div>
                    </div>
                    <div>
                         <label className="block text-sm text-slate-400 mb-2">Cor Secundária (Fundo)</label>
                         <div className="flex items-center gap-3">
                             <input type="color" value={secondary} onChange={e => setSecondary(e.target.value)} className="w-12 h-12 rounded bg-transparent cursor-pointer" />
                             <input value={secondary} onChange={e => setSecondary(e.target.value)} className="flex-1 bg-slate-900 border border-slate-700 rounded-lg p-3 text-white uppercase" />
                         </div>
                    </div>
                </div>

                <div className="pt-4 border-t border-slate-700">
                    <button onClick={handleSave} className="px-8 py-3 rounded-lg text-white font-bold transition-transform active:scale-95 flex items-center gap-2" style={{ backgroundColor: primary }} disabled={isUploading || isSaving}>
                        {(isUploading || isSaving) && <Loader2 size={16} className="animate-spin" />}
                        Salvar Alterações
                    </button>
                </div>
            </div>

            <div className="mt-8 p-6 bg-slate-800/50 rounded-xl border border-dashed border-slate-700 text-center">
                 <h4 className="text-slate-400 mb-2">Pré-visualização do Botão</h4>
                 <button className="px-6 py-2 rounded-lg text-white font-medium" style={{ backgroundColor: primary }}>
                     Agendar Horário
                 </button>
            </div>
        </div>
    );
};

