                        <button onClick={onLogout} className="p-2 bg-slate-800 rounded-full text-slate-400 hover:text-white border border-slate-700" title="Sair">
                            <LogOut size={18}/>
                        </button>
                    </div>
                </div>
            </header>

            <div className="max-w-4xl mx-auto p-4 space-y-6">

                {/* Cards de Resumo */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-slate-800 p-4 rounded-xl border border-slate-700">
                        <p className="text-slate-400 text-xs mb-1">Cortes Hoje</p>
                        <p className="text-2xl font-bold text-white">{todaysCuts.length}</p>
                    </div>
                    <div className="bg-slate-800 p-4 rounded-xl border border-slate-700">
                        <div className="flex justify-between items-start">
                             <div>
                                <p className="text-slate-400 text-xs mb-1">Minha Comissão ({commissionRate}%)</p>
                                <p className="text-2xl font-bold text-green-400">R$ {todaysEarnings.toFixed(2)}</p>
                             </div>
                             {todaysCuts.length > 0 && (
                                <div className="text-right">
                                    <p className="text-slate-500 text-[10px] mb-1">Total Bruto</p>
                                    <p className="text-sm font-medium text-slate-300">R$ {todaysGross.toFixed(2)}</p>
                                </div>
                             )}
                        </div>
                    </div>
                </div>

                {/* Lista de Agenda */}
                <div>
                    <h2 className="font-bold text-lg mb-4 flex items-center gap-2">
                        <Calendar size={18} className="text-orange-500"/> Minha Agenda
                    </h2>

                    {myAppointments.length === 0 ? (
                        <div className="text-center py-10 text-slate-500 bg-slate-800/50 rounded-xl border border-slate-800">
                            Nenhum agendamento encontrado.
                        </div>
                    ) : (
                        <div className="space-y-3">
                            {myAppointments.map(apt => {
                                const isToday = apt.date === todayStr;
                                const isProcessing = updatingAptId === apt.id;

                                return (
                                    <div key={apt.id} className={`bg-slate-800 p-4 rounded-xl border-l-4 ${STATUS_COLORS[apt.status] || 'border-slate-500'} shadow-sm relative overflow-hidden transition-all`}>

                                        {isProcessing && (
                                            <div className="absolute inset-0 bg-slate-900/50 backdrop-blur-[1px] flex items-center justify-center z-10">
                                                <Loader2 size={24} className="text-orange-500 animate-spin" />
                                            </div>
                                        )}

                                        <div className="flex justify-between items-start mb-3">
                                            <div>
                                                <h3 className="font-bold text-white text-lg">{apt.clientName}</h3>
                                                <p className="text-slate-400 text-sm">{apt.clientPhone}</p>
                                            </div>
                                            <div className="text-right">
                                                <div className="text-xl font-bold text-white">{apt.time}</div>
                                                <div className={`text-xs uppercase font-bold ${isToday ? 'text-green-400' : 'text-slate-500'}`}>
                                                    {isToday ? 'HOJE' : new Date(apt.date).toLocaleDateString('pt-BR', {day: '2-digit', month: 'short'})}
                                                </div>
                                            </div>
                                        </div>

                                        <div className="border-t border-slate-700/50 pt-3 flex justify-between items-center">
                                            <span className="text-sm font-medium" style={{ color: settings.primaryColor }}>
                                                R$ {apt.totalValue.toFixed(2)}
                                            </span>

                                            {/* Controles de Status Rápidos */}
                                            {apt.status !== 'completed' && apt.status !== 'cancelled' && (
                                                <div className="flex gap-2">
                                                    <button 
                                                        disabled={isProcessing}
                                                        onClick={() => handleStatusChange(apt.id, 'completed')}
                                                        className="px-3 py-1 bg-green-500/10 text-green-500 border border-green-500/20 rounded-lg text-xs font-bold flex items-center gap-1 hover:bg-green-500/20 active:scale-95 transition-all"
                                                    >
                                                        <CheckCircle size={12}/> Finalizar
                                                    </button>
                                                    <button 
                                                        disabled={isProcessing}
                                                        onClick={() => handleStatusChange(apt.id, 'noshow')}
                                                        className="px-3 py-1 bg-red-500/10 text-red-500 border border-red-500/20 rounded-lg text-xs font-bold hover:bg-red-500/20 active:scale-95 transition-all"
                                                    >
                                                        Faltou
                                                    </button>
                                                </div>
                                            )}
                                            {(apt.status === 'completed' || apt.status === 'cancelled' || apt.status === 'noshow') && (
                                                <span className="text-xs text-slate-500 uppercase font-bold flex items-center gap-1">
                                                    {apt.status === 'completed' && <CheckCircle size={12} />}
                                                    {STATUS_TRANSLATE[apt.status]}
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ShopState, Service, Professional, Coupon, Appointment, ShopSettings, WorkSchedule, Shop, BlockedSlot } from './types';
import { supabase } from './supabaseClient';
import { Session } from '@supabase/supabase-js';
import DOMPurify from 'dompurify';

// Standard response type for mutations
type MutationResult = Promise<{ success: boolean; error?: string }>;

interface ShopContextType extends ShopState {
  session: Session | null;
  loading: boolean;
  userRole: 'owner' | 'barber' | null;

  // Auth Actions
  login: (email: string, password: string) => Promise<{ error: any }>;
  signup: (email: string, password: string, shopName: string, slug: string, intent: 'create_shop' | 'join_team') => Promise<{ error: any }>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{ success: boolean, error?: string }>;

  // Data Loading
  loadShopBySlug: (slug: string) => Promise<boolean>; 
  refresh: () => void;

  // Actions - Now returning MutationResult
  addService: (service: Omit<Service, 'id' | 'shopId'>) => MutationResult;
  updateService: (id: string, service: Partial<Service>) => MutationResult;
  removeService: (id: string) => MutationResult;

  addProfessional: (professional: Omit<Professional, 'id' | 'shopId'>) => MutationResult;
  updateProfessional: (id: string, professional: Partial<Professional>) => MutationResult;
  removeProfessional: (id: string) => MutationResult;

  addCoupon: (coupon: Omit<Coupon, 'id' | 'usageCount' | 'shopId'>) => MutationResult;
  updateCoupon: (id: string, coupon: Partial<Coupon>) => MutationResult;
  removeCoupon: (id: string) => MutationResult;

  addAppointment: (appointment: Omit<Appointment, 'id' | 'createdAt' | 'shopId'>) => MutationResult;
  createManualAppointment: (appointment: Omit<Appointment, 'id' | 'createdAt' | 'shopId'>) => MutationResult;
  updateAppointmentStatus: (id: string, status: string) => MutationResult;

  addBlockedSlot: (block: Omit<BlockedSlot, 'id' | 'shopId'>) => MutationResult;
  removeBlockedSlot: (id: string) => MutationResult;

  updateSettings: (settings: Partial<ShopSettings>) => MutationResult;
}

const ShopContext = createContext<ShopContextType | undefined>(undefined);

// Default Schedule helper
const DEFAULT_SCHEDULE: WorkSchedule = {
  monday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  tuesday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  wednesday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  thursday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  friday: { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  saturday: { start: '09:00', end: '17:00', lunchStart: '12:00', lunchEnd: '13:00', active: true },
  sunday: { start: '09:00', end: '13:00', lunchStart: '00:00', lunchEnd: '00:00', active: false },
};

const INITIAL_STATE: ShopState = {
  shop: null,
  settings: {
    shopId: "",
    name: "Carregando...",
    logoUrl: null,
    primaryColor: "#f97316",
    secondaryColor: "#1e293b",
  },
  services: [],
  professionals: [],
  coupons: [],
  appointments: [],
  blockedSlots: [],
  trialStatus: 'active',
  daysRemaining: 14
};

const sanitize = (text: string): string => {
  if (!text) return '';
  return DOMPurify.sanitize(text, {
    ALLOWED_TAGS: [],
    ALLOWED_ATTR: []
  });
};

export const ShopProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<ShopState>(INITIAL_STATE);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  const [userRole, setUserRole] = useState<'owner' | 'barber' | null>(null);

  // --- Mappers ---
  const mapShop = (data: any): Shop => ({
      id: data.id,
      ownerId: data.owner_id,
      name: data.name,
      slug: data.slug,
      trialStartedAt: data.trial_started_at,
      trialEndsAt: data.trial_ends_at,
      plan: data.plan,
      paymentConfirmedAt: data.payment_confirmed_at
  });

  const mapSettings = (data: any): ShopSettings => ({
      id: data.id,
      shopId: data.shop_id,
      name: data.name || "Minha Barbearia",
      logoUrl: data.logo_url,
      primaryColor: data.primary_color || "#f97316",
      secondaryColor: data.secondary_color || "#1e293b"
  });

  const mapService = (data: any): Service => ({
      id: data.id,
      shopId: data.shop_id,
      name: data.name,
      description: data.description,
      price: data.price,
      duration: data.duration,
      category: data.category || 'Geral'
  });

  const mapProfessional = (data: any): Professional => ({
      id: data.id,
      shopId: data.shop_id,
      name: data.name,
      role: data.role,
      photoUrl: data.photo_url,
      workSchedule: data.work_schedule || DEFAULT_SCHEDULE,
      email: data.email,
      userId: data.user_id,
      commissionPercentage: data.commission_percentage || 50 // Default 50%
  });

  const mapCoupon = (data: any): Coupon => ({
      id: data.id,
      shopId: data.shop_id,
      code: data.code,
      type: data.type,
      value: data.value,
      usageCount: data.usage_count,
      active: data.active
  });

  const mapAppointment = (data: any): Appointment => ({
      id: data.id,
      shopId: data.shop_id,
      clientName: data.client_name,
      clientPhone: data.client_phone,
      serviceIds: data.service_ids || [], 
      professionalId: data.professional_id,
      date: data.date,
      time: data.time,
      totalValue: data.total_value,
      couponCode: data.coupon_code,
      createdAt: data.created_at,
      status: data.status || 'scheduled'
  });

  const mapBlockedSlot = (data: any): BlockedSlot => ({
      id: data.id,
      shopId: data.shop_id,
      professionalId: data.professional_id,
      date: data.date,
      startTime: data.start_time,
      endTime: data.end_time,
      reason: data.reason
  });

  // --- Logic for Trial Calculation ---
  const calculateTrialStatus = (shop: Shop): { status: 'active' | 'expired' | 'paid', days: number } => {
      if (shop.plan === 'active') {
          return { status: 'paid', days: 0 };
      }

      if (shop.plan === 'suspended') {
          return { status: 'expired', days: 0 };
      }

      // Default: Trial
      if (!shop.trialEndsAt) return { status: 'active', days: 14 }; // Fallback

      const now = new Date();
      const end = new Date(shop.trialEndsAt);
      const diffTime = end.getTime() - now.getTime();
      const days = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

      if (days <= 0) {
          return { status: 'expired', days: 0 };
      }

      return { status: 'active', days };
  };

  // --- Core Fetch Logic ---
  const fetchData = async (targetShopId?: string) => {
    // Only set loading on initial fetch or full refresh, not background updates
    if (!state.shop) setLoading(true);

    try {
        let shopId = targetShopId;
        let currentShopData: Shop | null = state.shop;

        const { data: { session: currentSession } } = await supabase.auth.getSession();

        // Só tenta descobrir o shopId se ele NÃO foi passado
        if (!shopId) {
            const userId = currentSession?.user?.id;
            const userEmail = currentSession?.user?.email;

            // 1. Tenta encontrar a loja onde o usuário é DONO
            if (userId) {
                const { data: shopData } = await supabase.from('shops').select('*').eq('owner_id', userId).single();
                if (shopData) {
                    shopId = shopData.id;
                    currentShopData = mapShop(shopData);
                }
            } 

            // 2. Se não achou como dono, verifica se é BARBEIRO em alguma loja
            if (!shopId && userEmail) {
                 const { data: proData } = await supabase.from('professionals').select('shop_id').eq('email', userEmail).single();
                 if (proData) {
                     const { data: shopData } = await supabase.from('shops').select('*').eq('id', proData.shop_id).single();
                     if (shopData) {
                        shopId = shopData.id;
                        currentShopData = mapShop(shopData);
                     }
                 }
            }

            // 3. Fallback: Se já temos um shop carregado no state (view de cliente)
            if (!shopId && state.shop?.id) {
                shopId = state.shop.id;
            }
        }

        if (!shopId) {
            setLoading(false);
            return; 
        }

        // Executa queries de configurações e dados estáticos em paralelo
        const [settingsRes, servicesRes, prosRes, couponsRes, blocksRes] = await Promise.all([
            supabase.from('settings').select('*').eq('shop_id', shopId).single(),
            supabase.from('services').select('*').eq('shop_id', shopId),
            supabase.from('professionals').select('*').eq('shop_id', shopId),
            supabase.from('coupons').select('*').eq('shop_id', shopId),
            supabase.from('blocked_slots').select('*').eq('shop_id', shopId)
        ]);

        // OTIMIZAÇÃO: Carregar apenas agendamentos recentes e futuros
        const pastDate = new Date();
        pastDate.setDate(pastDate.getDate() - 30); // 30 dias atrás
        const dateLimitStr = pastDate.toISOString().split('T')[0];

        let appointmentsData: Appointment[] = [];

        const { data: appts } = await supabase
            .from('appointments')
            .select('*')
            .eq('shop_id', shopId)
            .gte('date', dateLimitStr) // Apenas >= 30 dias atrás
            .order('date', { ascending: false }) // Ordem decrescente de data
            .order('time', { ascending: false });

        if (appts) appointmentsData = appts.map(mapAppointment);

        const mappedProfessionals = (prosRes.data || []).map(mapProfessional);

        // --- LÓGICA DE ROLES ---
        if (currentSession?.user) {
            const effectiveShopData = currentShopData || state.shop;

            if (effectiveShopData?.ownerId === currentSession.user.id) {
                setUserRole('owner');
            } else {
                const isBarber = mappedProfessionals.find(p => p.email === currentSession.user.email);
                if (isBarber) {
                    setUserRole('barber');
                    // Ensure User ID is linked if it wasn't already (Self-healing)
                    if (!isBarber.userId) {
                        await supabase.from('professionals').update({ user_id: currentSession.user.id }).eq('id', isBarber.id);
                        isBarber.userId = currentSession.user.id;
                    }
                } else {
                    setUserRole(null);
                }
            }
        } else {
            setUserRole(null);
        }

        // Calculate Trial
        let trialInfo: { status: 'active' | 'expired' | 'paid', days: number } = { status: 'active', days: 14 };
        if (currentShopData) {
            trialInfo = calculateTrialStatus(currentShopData);
        }

        setState(prev => ({
            ...prev,
            shop: currentShopData || prev.shop,
            settings: settingsRes.data ? mapSettings(settingsRes.data) : { ...INITIAL_STATE.settings, shopId: shopId },
            services: (servicesRes.data || []).map(mapService),
            professionals: mappedProfessionals,
            coupons: (couponsRes.data || []).map(mapCoupon),
            appointments: appointmentsData,
            blockedSlots: (blocksRes.data || []).map(mapBlockedSlot),
            trialStatus: trialInfo.status,
            daysRemaining: trialInfo.days
        }));

    } catch (error) {
        console.error("Error fetching data:", error);
    } finally {
        setLoading(false);
    }
  };

  // --- Realtime Subscriptions ---
  useEffect(() => {
      if (!state.shop?.id) return;

      // 1. Listen for Shop Plan Changes
      const shopChannel = supabase.channel('shop_updates')
        .on(
            'postgres_changes',
            {
                event: 'UPDATE',
                schema: 'public',
                table: 'shops',
                filter: `id=eq.${state.shop.id}`
            },
            (payload) => {
                const updatedShop = payload.new;
                setState(prev => {
                    if (!prev.shop) return prev;
                    const newShopData = { ...prev.shop, ...mapShop(updatedShop) };
                    const newTrialInfo = calculateTrialStatus(newShopData);
                    return {
                        ...prev,
                        shop: newShopData,
                        trialStatus: newTrialInfo.status,
                        daysRemaining: newTrialInfo.days
                    };
                });
            }
        )
        .subscribe();

      // 2. Listen for Appointment Changes (Sync Barber/Admin)
      const appointmentsChannel = supabase.channel('appointments_sync')
        .on(
            'postgres_changes',
            {
                event: '*', // Insert, Update, Delete
                schema: 'public',
                table: 'appointments',
                filter: `shop_id=eq.${state.shop.id}`
            },
            () => {
                // Re-fetch data on any appointment change
                fetchData(state.shop?.id);
            }
        )
        .subscribe();

      return () => {
          supabase.removeChannel(shopChannel);
          supabase.removeChannel(appointmentsChannel);
      }
  }, [state.shop?.id]);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session: activeSession } }) => {
      setSession(activeSession);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, activeSession) => {
      setSession(activeSession);
    });

    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (session?.user) {
      fetchData();
    } else if (!loading && !session) {
      setState(INITIAL_STATE);
      setUserRole(null);
    }
  }, [session]);

  const login = async (email: string, password: string) => {
      const { error } = await supabase.auth.signInWithPassword({ email, password });
      return { error };
  };

  const resetPassword = async (email: string) => {
      const { error } = await supabase.auth.resetPasswordForEmail(email, {
          redirectTo: window.location.origin + '/update-password', 
      });
      if (error) return { success: false, error: error.message };
      return { success: true };
  };

  const signup = async (email: string, password: string, shopName: string, slug: string, intent: 'create_shop' | 'join_team') => {
      const cleanShopName = sanitize(shopName);
      const cleanSlug = sanitize(slug).toLowerCase().replace(/[^\w-]/g, '');

      const { data: authData, error: authError } = await supabase.auth.signUp({ email, password });
      if (authError || !authData.user) return { error: authError };

      if (intent === 'join_team') {
          // Check if email is in professionals table
          const { data: proData } = await supabase.from('professionals').select('id, shop_id').eq('email', email).single();

          if (proData) {
              // Link the Auth User ID to the Professional Profile
              await supabase.from('professionals').update({ user_id: authData.user.id }).eq('id', proData.id);
              setSession(authData.session);
              return { error: null };
          } else {
              // Rollback (Not easy in client-side, but effectively the user is created but has no access)
              return { error: { message: 'Este email não consta na lista de profissionais de nenhuma barbearia.' } };
          }
      }

      // [UPDATE] Create Shop with Trial Fields
      const { data: shopData, error: shopError } = await supabase.from('shops').insert({
          owner_id: authData.user.id,
          name: cleanShopName,
          slug: cleanSlug,
          plan: 'trial',
          trial_started_at: new Date().toISOString(),
          // 14 days from now
          trial_ends_at: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString()
      }).select().single();

      if (shopError || !shopData) return { error: shopError };

      await supabase.from('settings').insert({
          shop_id: shopData.id,
          name: cleanShopName,
          primary_color: '#f97316',
          secondary_color: '#1e293b'
      });

      // Default services
      const defaultServices = [
        { name: 'Corte Masculino', price: 30, duration: 30, category: 'Cortes' },
        { name: 'Barba', price: 20, duration: 20, category: 'Barba' },
        { name: 'Corte + Barba', price: 45, duration: 50, category: 'Combos' }
      ];
      const servicesToInsert = defaultServices.map(s => ({
          shop_id: shopData.id,
          name: s.name,
          description: s.name,
          price: s.price,
          duration: s.duration,
          category: s.category
      }));
      await supabase.from('services').insert(servicesToInsert);

      setSession(authData.session);
      return { error: null };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      setState(INITIAL_STATE);
      setSession(null);
      setUserRole(null);
  };

  const loadShopBySlug = async (slug: string) => {
      setLoading(true);
      const cleanSlug = sanitize(slug);
      const { data } = await supabase.from('shops').select('*').eq('slug', cleanSlug).single();
      if (data) {
          const shop = mapShop(data);
          setState(prev => ({ ...prev, shop }));
          await fetchData(shop.id);
          return true;
      }
      setLoading(false);
      return false;
  };

  const ensureShopId = () => {
      if (!state.shop?.id) {
          throw new Error("Loja não identificada. Recarregue a página.");
      }
      return state.shop.id;
  };

  // --- ACTIONS WITH OPTIMIZED FETCH ---

  const addService = async (service: Omit<Service, 'id' | 'shopId'>): MutationResult => {
    try {
        const shopId = ensureShopId();
        const { error } = await supabase.from('services').insert({ 
          ...service, 
          name: sanitize(service.name),
          description: sanitize(service.description),
          category: sanitize(service.category),
          shop_id: shopId 
        });
        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const updateService = async (id: string, updated: Partial<Service>): MutationResult => {
    try {
        const shopId = ensureShopId(); // Capture ID
        const payload: any = {};
        if (updated.name) payload.name = sanitize(updated.name);
        if (updated.description) payload.description = sanitize(updated.description);
        if (updated.price !== undefined) payload.price = updated.price;
        if (updated.duration !== undefined) payload.duration = updated.duration;
        if (updated.category) payload.category = sanitize(updated.category);

        const { error } = await supabase.from('services').update(payload).eq('id', id);
        if (error) throw error;
        await fetchData(shopId); // Pass explicit ID
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const removeService = async (id: string): MutationResult => {
    try {
        const shopId = ensureShopId();
        const { error } = await supabase.from('services').delete().eq('id', id);
        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const addProfessional = async (pro: Omit<Professional, 'id' | 'shopId'>): MutationResult => {
    try {
        const shopId = ensureShopId();
        const { error } = await supabase.from('professionals').insert({
            shop_id: shopId,
            name: sanitize(pro.name),
            role: sanitize(pro.role),
            photo_url: pro.photoUrl,
            work_schedule: pro.workSchedule || DEFAULT_SCHEDULE,
            email: pro.email ? sanitize(pro.email) : null,
            commission_percentage: pro.commissionPercentage ?? 50
        });
        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const updateProfessional = async (id: string, updated: Partial<Professional>): MutationResult => {
    try {
        const shopId = ensureShopId();
        const payload: any = {};
        if (updated.name) payload.name = sanitize(updated.name);
        if (updated.role) payload.role = sanitize(updated.role);
        if (updated.photoUrl) payload.photo_url = updated.photoUrl;
        if (updated.workSchedule) payload.work_schedule = updated.workSchedule;
        if (updated.email !== undefined) payload.email = updated.email ? sanitize(updated.email) : null;
        if (updated.commissionPercentage !== undefined) payload.commission_percentage = updated.commissionPercentage;

        const { error } = await supabase.from('professionals').update(payload).eq('id', id);
        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const removeProfessional = async (id: string): MutationResult => {
    try {
        const shopId = ensureShopId();
        const { error } = await supabase.from('professionals').delete().eq('id', id);
        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const addCoupon = async (coupon: Omit<Coupon, 'id' | 'usageCount' | 'shopId'>): MutationResult => {
    try {
        const shopId = ensureShopId();
        const { error } = await supabase.from('coupons').insert({
            shop_id: shopId,
            code: sanitize(coupon.code).toUpperCase(),
            type: coupon.type,
            value: coupon.value,
            usage_count: 0,
            active: coupon.active
        });
        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const updateCoupon = async (id: string, updated: Partial<Coupon>): MutationResult => {
    try {
        const shopId = ensureShopId();
        const payload: any = {};
        if (updated.code) payload.code = sanitize(updated.code).toUpperCase();
        if (updated.type) payload.type = updated.type;
        if (updated.value) payload.value = updated.value;
        if (updated.active !== undefined) payload.active = updated.active;

        const { error } = await supabase.from('coupons').update(payload).eq('id', id);
        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const removeCoupon = async (id: string): MutationResult => {
    try {
        const shopId = ensureShopId();
        const { error } = await supabase.from('coupons').delete().eq('id', id);
        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const addAppointment = async (apt: Omit<Appointment, 'id' | 'createdAt' | 'shopId'>): MutationResult => {
    try {
        const shopId = ensureShopId();
        const cleanClientName = sanitize(apt.clientName);
        const cleanClientPhone = sanitize(apt.clientPhone);

        const { error } = await supabase.rpc('book_appointment', {
            p_shop_id: shopId,
            p_client_name: cleanClientName,
            p_client_phone: cleanClientPhone,
            p_service_ids: apt.serviceIds,
            p_professional_id: apt.professionalId,
            p_date: apt.date,
            p_time: apt.time,
            p_total_value: apt.totalValue,
            p_coupon_code: apt.couponCode ? sanitize(apt.couponCode) : null
        });

        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const createManualAppointment = async (apt: Omit<Appointment, 'id' | 'createdAt' | 'shopId'>): MutationResult => {
      try {
          const shopId = ensureShopId();
          const cleanClientName = sanitize(apt.clientName);
          const cleanClientPhone = sanitize(apt.clientPhone);

          const { error } = await supabase.from('appointments').insert({
              shop_id: shopId,
              client_name: cleanClientName,
              client_phone: cleanClientPhone,
              service_ids: apt.serviceIds,
              professional_id: apt.professionalId,
              date: apt.date,
              time: apt.time,
              total_value: apt.totalValue,
              coupon_code: null,
              status: apt.status || 'confirmed'
          });

          if (error) throw error;
          await fetchData(shopId);
          return { success: true };
      } catch (e: any) {
          return { success: false, error: e.message };
      }
  };

  const updateAppointmentStatus = async (id: string, status: string): MutationResult => {
    try {
        const shopId = ensureShopId();
        const { error } = await supabase.from('appointments').update({ status }).eq('id', id);
        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const addBlockedSlot = async (block: Omit<BlockedSlot, 'id' | 'shopId'>): MutationResult => {
    try {
        const shopId = ensureShopId();
        const { error } = await supabase.from('blocked_slots').insert({
            shop_id: shopId,
            professional_id: block.professionalId,
            date: block.date,
            start_time: block.startTime,
            end_time: block.endTime,
            reason: sanitize(block.reason || '')
        });
        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const removeBlockedSlot = async (id: string): MutationResult => {
    try {
        const shopId = ensureShopId();
        const { error } = await supabase.from('blocked_slots').delete().eq('id', id);
        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  const updateSettings = async (updated: Partial<ShopSettings>): MutationResult => {
    try {
        const shopId = ensureShopId();
        const { data } = await supabase.from('settings').select('id').eq('shop_id', shopId).single();

        const payload: any = {};
        if (updated.name) payload.name = sanitize(updated.name);
        if (updated.logoUrl) payload.logo_url = updated.logoUrl;
        if (updated.primaryColor) payload.primary_color = sanitize(updated.primaryColor);
        if (updated.secondaryColor) payload.secondary_color = sanitize(updated.secondaryColor);

        let error;
        if (data && data.id) {
            ({ error } = await supabase.from('settings').update(payload).eq('id', data.id));
        } else {
            ({ error } = await supabase.from('settings').insert({ ...payload, shop_id: shopId }));
        }

        if (error) throw error;
        await fetchData(shopId);
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
  };

  return (
    <ShopContext.Provider value={{
      ...state,
      session,
      loading,
      userRole,
      login, signup, logout,
      loadShopBySlug,
      resetPassword,
      addService, updateService, removeService,
      addProfessional, updateProfessional, removeProfessional,
      addCoupon, updateCoupon, removeCoupon,
      addAppointment,
      createManualAppointment,
      updateAppointmentStatus,
      addBlockedSlot, removeBlockedSlot,
      updateSettings,
      refresh: () => fetchData(state.shop?.id)
    }}>
      {children}
    </ShopContext.Provider>
  );
};

export const useShop = () => {
  const context = useContext(ShopContext);
  if (!context) throw new Error("useShop must be used within a ShopProvider");
  return context;
};

import React, { useMemo, useState, useEffect } from 'react';
import { useShop } from '../../store';
import { Calendar, Clock, LogOut, CheckCircle, XCircle, AlertCircle, Settings, X, Loader2, Trash2, Plus, RefreshCw } from 'lucide-react';
import { useToast } from '../ui/ToastContext';
import { WorkSchedule, DaySchedule, Professional } from '../../types';

export const BarberDashboard: React.FC<{ onLogout: () => void }> = ({ onLogout }) => {
    const { appointments, professionals, session, updateAppointmentStatus, settings, updateProfessional, blockedSlots, addBlockedSlot, removeBlockedSlot, refresh } = useShop();
    const { showToast } = useToast();

    // 1. Identificar qual profissional é o usuário logado
    const currentPro = professionals.find(p => p.email === session?.user.email || p.userId === session?.user.id);

    // States para Modal de Configuração
    const [isConfigOpen, setIsConfigOpen] = useState(false);
    const [schedule, setSchedule] = useState<WorkSchedule | null>(null);
    const [isSaving, setIsSaving] = useState(false);
    const [isRefreshing, setIsRefreshing] = useState(false);

    // State para ações em agendamentos
    const [updatingAptId, setUpdatingAptId] = useState<string | null>(null);

    // States para Bloqueios
    const [blockDate, setBlockDate] = useState('');
    const [blockStart, setBlockStart] = useState('08:00');
    const [blockEnd, setBlockEnd] = useState('18:00');
    const [blockReason, setBlockReason] = useState('Folga / Médico');

    // Inicializar schedule quando abrir o modal
    const openConfig = () => {
        if (currentPro?.workSchedule) {
            setSchedule(JSON.parse(JSON.stringify(currentPro.workSchedule)));
        }
        setIsConfigOpen(true);
    };

    const handleRefresh = async () => {
        setIsRefreshing(true);
        await refresh();
        setTimeout(() => setIsRefreshing(false), 500);
    };

    const handleSaveSchedule = async () => {
        if (!currentPro || !schedule) return;
        setIsSaving(true);
        const { success, error } = await updateProfessional(currentPro.id, { workSchedule: schedule });
        setIsSaving(false);
        if (success) {
            showToast('Horários atualizados com sucesso!');
            setIsConfigOpen(false);
        } else {
            showToast(error || 'Erro ao salvar.', 'error');
        }
    };

    const handleAddBlock = async (e: React.FormEvent) => {
        e.preventDefault();
        if (currentPro) {
            const { success, error } = await addBlockedSlot({
                professionalId: currentPro.id,
                date: blockDate,
                startTime: blockStart,
                endTime: blockEnd,
                reason: blockReason
            });

            if (success) {
                showToast('Bloqueio adicionado!');
                setBlockReason('Folga / Médico');
            } else {
                showToast(error || 'Erro ao bloquear.', 'error');
            }
        }
    };

    const handleRemoveBlock = async (id: string) => {
        const { success, error } = await removeBlockedSlot(id);
        if (success) {
            showToast('Bloqueio removido.');
        } else {
            showToast(error || 'Erro ao remover.', 'error');
        }
    }

    const handleStatusChange = async (id: string, newStatus: string) => {
        setUpdatingAptId(id);
        try {
            const { success, error } = await updateAppointmentStatus(id, newStatus);
            if (success) {
                const mapLabels: Record<string, string> = {
                    'confirmed': 'Atendimento confirmado!',
                    'completed': 'Atendimento finalizado com sucesso!',
                    'noshow': 'Agendamento marcado como falta.',
                    'cancelled': 'Agendamento cancelado.',
                    'scheduled': 'Status revertido para agendado.'
                }
                showToast(mapLabels[newStatus] || 'Status atualizado.');
            } else {
                showToast(error || 'Erro ao atualizar status.', 'error');
            }
        } catch (err) {
            showToast('Erro de conexão.', 'error');
        } finally {
            setUpdatingAptId(null);
        }
    };

    const toggleDay = (day: keyof WorkSchedule) => {
        if (schedule) {
            setSchedule(prev => prev ? ({ ...prev, [day]: { ...prev[day], active: !prev[day].active } }) : null);
        }
    };

    const updateDayTime = (day: keyof WorkSchedule, field: keyof DaySchedule, value: string) => {
        if (schedule) {
            setSchedule(prev => prev ? ({ ...prev, [day]: { ...prev[day], [field]: value } }) : null);
        }
    };

    // 2. Filtrar agendamentos DESTE barbeiro
    const myAppointments = useMemo(() => {
        if (!currentPro) return [];
        // Ordenar: Hoje primeiro, depois data futura
        return appointments
            .filter(a => a.professionalId === currentPro.id)
            .sort((a, b) => {
                const dateA = new Date(`${a.date}T${a.time}`);
                const dateB = new Date(`${b.date}T${b.time}`);
                return dateA.getTime() - dateB.getTime();
            });
    }, [appointments, currentPro]);

    // 3. Calcular ganhos (Baseado na Comissão)
    // FIX: Usar data local para evitar problemas de fuso horário
    const today = new Date();
    // Ajusta o timezone offset para garantir que a string YYYY-MM-DD seja do dia local
    const offset = today.getTimezoneOffset();
    const todayLocal = new Date(today.getTime() - (offset * 60 * 1000));
    const todayStr = todayLocal.toISOString().split('T')[0];

    const todaysCuts = myAppointments.filter(a => a.date === todayStr && a.status === 'completed');

    // Total Bruto
    const todaysGross = todaysCuts.reduce((acc, curr) => acc + curr.totalValue, 0);
    // Comissão
    const commissionRate = currentPro?.commissionPercentage ?? 50;
    const todaysEarnings = todaysGross * (commissionRate / 100);

    const STATUS_COLORS: Record<string, string> = {
        scheduled: 'border-blue-500 text-blue-400',
        confirmed: 'border-orange-500 text-orange-400',
        completed: 'border-green-500 text-green-400',
        cancelled: 'border-red-500 text-red-400',
        noshow: 'border-slate-500 text-slate-400',
    };

    const daysMap: {[key: string]: string} = {
        monday: 'Segunda', tuesday: 'Terça', wednesday: 'Quarta', thursday: 'Quinta',
        friday: 'Sexta', saturday: 'Sábado', sunday: 'Domingo'
    };

    if (!currentPro) {
        return (
            <div className="min-h-screen bg-slate-900 flex items-center justify-center text-white p-4 text-center">
                <div>
                    <AlertCircle size={48} className="mx-auto mb-4 text-orange-500"/>
                    <h2 className="text-xl font-bold">Perfil não vinculado</h2>
                    <p className="text-slate-400 mb-6">Seu usuário não está associado a nenhum barbeiro desta loja.<br/>Peça ao dono para cadastrar seu email: {session?.user.email}</p>
                    <button onClick={onLogout} className="px-6 py-2 bg-slate-800 rounded-lg">Sair</button>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-slate-900 text-slate-100 pb-20">
            {/* Modal de Configuração */}
            {isConfigOpen && schedule && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-fade-in">
                    <div className="bg-slate-800 w-full max-w-2xl rounded-2xl border border-slate-700 shadow-2xl relative animate-scale-up max-h-[90vh] overflow-y-auto">
                        <div className="sticky top-0 bg-slate-800 p-6 border-b border-slate-700 flex justify-between items-center z-10">
                            <h2 className="text-xl font-bold">Minha Agenda</h2>
                            <button onClick={() => setIsConfigOpen(false)}><X size={24} className="text-slate-400 hover:text-white"/></button>
                        </div>

                        <div className="p-6 space-y-8">
                            {/* Horários de Trabalho */}
                            <div className="space-y-4">
                                <h3 className="text-lg font-bold text-orange-500 flex items-center gap-2"><Clock size={18}/> Horários de Trabalho</h3>
                                <div className="space-y-3 bg-slate-900/50 p-4 rounded-xl border border-slate-700">
                                     {Object.entries(schedule).map(([key, val]) => {
                                         const day = val as DaySchedule;
                                         return (
                                             <div key={key} className="flex flex-col md:flex-row md:items-center gap-3 pb-3 border-b border-slate-700/50 last:border-0">
                                                 <div className="w-24">
                                                     <label className="flex items-center gap-2 cursor-pointer">
                                                         <input type="checkbox" checked={day.active} onChange={() => toggleDay(key as keyof WorkSchedule)} className="rounded border-slate-600 text-orange-500 focus:ring-orange-500 bg-slate-800" />
                                                         <span className={day.active ? 'text-white' : 'text-slate-500'}>{daysMap[key]}</span>
                                                     </label>
                                                 </div>
                                                 {day.active && (
                                                    <div className="flex flex-wrap items-center gap-2 text-sm">
                                                        <input type="time" value={day.start} onChange={e => updateDayTime(key as keyof WorkSchedule, 'start', e.target.value)} className="bg-slate-800 border border-slate-600 rounded px-2 py-1 text-white" />
                                                        <span className="text-slate-500">até</span>
                                                        <input type="time" value={day.end} onChange={e => updateDayTime(key as keyof WorkSchedule, 'end', e.target.value)} className="bg-slate-800 border border-slate-600 rounded px-2 py-1 text-white" />
                                                        <span className="text-slate-500 ml-2 hidden sm:inline">Almoço:</span>
                                                        <input type="time" value={day.lunchStart} onChange={e => updateDayTime(key as keyof WorkSchedule, 'lunchStart', e.target.value)} className="bg-slate-800 border border-slate-600 rounded px-2 py-1 text-white" />
                                                        <span className="text-slate-500">-</span>
                                                        <input type="time" value={day.lunchEnd} onChange={e => updateDayTime(key as keyof WorkSchedule, 'lunchEnd', e.target.value)} className="bg-slate-800 border border-slate-600 rounded px-2 py-1 text-white" />
                                                    </div>
                                                 )}
                                             </div>
                                         );
                                     })}
                                </div>
                            </div>

                            {/* Gerenciar Bloqueios */}
                            <div className="space-y-4">
                                <h3 className="text-lg font-bold text-orange-500 flex items-center gap-2"><Calendar size={18}/> Bloqueios e Folgas</h3>

                                <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-700">
                                    <h4 className="text-sm font-bold text-slate-400 uppercase mb-3">Novo Bloqueio</h4>
                                    <form onSubmit={handleAddBlock} className="space-y-3">
                                        <div className="flex flex-col sm:flex-row gap-3">
                                            <input required type="date" value={blockDate} onChange={e => setBlockDate(e.target.value)} className="flex-1 bg-slate-800 border border-slate-600 rounded p-2 text-white text-sm" />
                                            <div className="flex gap-2 flex-1">
                                                <input required type="time" value={blockStart} onChange={e => setBlockStart(e.target.value)} className="flex-1 bg-slate-800 border border-slate-600 rounded p-2 text-white text-sm" />
                                                <span className="self-center text-slate-500">-</span>
                                                <input required type="time" value={blockEnd} onChange={e => setBlockEnd(e.target.value)} className="flex-1 bg-slate-800 border border-slate-600 rounded p-2 text-white text-sm" />
                                            </div>
                                        </div>
                                        <div className="flex gap-3">
                                            <input required type="text" value={blockReason} onChange={e => setBlockReason(e.target.value)} placeholder="Motivo" className="flex-1 bg-slate-800 border border-slate-600 rounded p-2 text-white text-sm" />
                                            <button type="submit" className="bg-orange-500 hover:bg-orange-600 text-white px-4 py-2 rounded text-sm font-bold flex items-center gap-2">
                                                <Plus size={16}/> Adicionar
                                            </button>
                                        </div>
                                    </form>

                                    <div className="mt-6">
                                        <h4 className="text-sm font-bold text-slate-400 uppercase mb-3">Bloqueios Futuros</h4>
                                        <div className="space-y-2 max-h-40 overflow-y-auto pr-2 custom-scrollbar">
                                            {blockedSlots.filter(b => b.professionalId === currentPro.id).length === 0 ? (
                                                <p className="text-sm text-slate-500 italic">Nenhum bloqueio cadastrado.</p>
                                            ) : (
                                                blockedSlots
                                                    .filter(b => b.professionalId === currentPro.id)
                                                    .sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime())
                                                    .map(b => (
                                                    <div key={b.id} className="flex justify-between items-center bg-slate-800 p-3 rounded border border-slate-600">
                                                        <div>
                                                            <div className="text-sm text-white font-medium">{new Date(b.date + 'T12:00:00').toLocaleDateString('pt-BR')}</div>
                                                            <div className="text-xs text-slate-400">{b.startTime} - {b.endTime} • {b.reason}</div>
                                                        </div>
                                                        <button onClick={() => handleRemoveBlock(b.id)} className="text-red-500 hover:text-red-400 p-1"><Trash2 size={16}/></button>
                                                    </div>
                                                ))
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="p-6 border-t border-slate-700 bg-slate-800 sticky bottom-0 z-10">
                            <button 
                                onClick={handleSaveSchedule}
                                disabled={isSaving}
                                className="w-full py-3 bg-green-500 hover:bg-green-600 text-white font-bold rounded-lg flex items-center justify-center gap-2"
                            >
                                {isSaving ? <Loader2 className="animate-spin"/> : 'Salvar Alterações'}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Header */}
            <header className="bg-slate-950 border-b border-slate-800 p-4 sticky top-0 z-10">
                <div className="flex justify-between items-center max-w-4xl mx-auto">
                    <div className="flex items-center gap-3">
                        <img src={currentPro.photoUrl} alt={currentPro.name} className="w-10 h-10 rounded-full border border-slate-700 object-cover" />
                        <div>
                            <h1 className="font-bold leading-tight">Olá, {currentPro.name.split(' ')[0]}</h1>
                            <p className="text-xs text-slate-400">Painel do Barbeiro</p>
                        </div>
                    </div>
                    <div className="flex gap-2">
                        <button onClick={handleRefresh} className={`p-2 bg-slate-800 rounded-full text-slate-400 hover:text-white border border-slate-700 ${isRefreshing ? 'animate-spin text-orange-500' : ''}`} title="Atualizar dados">
                            <RefreshCw size={18}/>
                        </button>
                         <button onClick={openConfig} className="p-2 bg-slate-800 rounded-full text-slate-400 hover:text-white border border-slate-700" title="Configurações">
                            <Settings size={18}/>
                        </button>
                        <button onClick={onLogout} className="p-2 bg-slate-800 rounded-full text-slate-400 hover:text-white border border-slate-700" title="Sair">
                            <LogOut size={18}/>
                        </button>
                    </div>
                </div>
            </header>

            <div className="max-w-4xl mx-auto p-4 space-y-6">

                {/* Cards de Resumo */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-slate-800 p-4 rounded-xl border border-slate-700">
                        <p className="text-slate-400 text-xs mb-1">Cortes Hoje</p>
                        <p className="text-2xl font-bold text-white">{todaysCuts.length}</p>
                    </div>
                    <div className="bg-slate-800 p-4 rounded-xl border border-slate-700">
                        <div className="flex justify-between items-start">
                             <div>
                                <p className="text-slate-400 text-xs mb-1">Minha Comissão ({commissionRate}%)</p>
                                <p className="text-2xl font-bold text-green-400">R$ {todaysEarnings.toFixed(2)}</p>
                             </div>
                             {todaysCuts.length > 0 && (
                                <div className="text-right">
                                    <p className="text-slate-500 text-[10px] mb-1">Total Bruto</p>
                                    <p className="text-sm font-medium text-slate-300">R$ {todaysGross.toFixed(2)}</p>
                                </div>
                             )}
                        </div>
                    </div>
                </div>

                {/* Lista de Agenda */}
                <div>
                    <h2 className="font-bold text-lg mb-4 flex items-center gap-2">
                        <Calendar size={18} className="text-orange-500"/> Minha Agenda
                    </h2>

                    {myAppointments.length === 0 ? (
                        <div className="text-center py-10 text-slate-500 bg-slate-800/50 rounded-xl border border-slate-800">
                            Nenhum agendamento encontrado.
                        </div>
                    ) : (
                        <div className="space-y-3">
                            {myAppointments.map(apt => {
                                const isToday = apt.date === todayStr;
                                const isProcessing = updatingAptId === apt.id;

                                return (
                                    <div key={apt.id} className={`bg-slate-800 p-4 rounded-xl border-l-4 ${STATUS_COLORS[apt.status] || 'border-slate-500'} shadow-sm relative overflow-hidden transition-all`}>

                                        {isProcessing && (
                                            <div className="absolute inset-0 bg-slate-900/50 backdrop-blur-[1px] flex items-center justify-center z-10">
                                                <Loader2 size={24} className="text-orange-500 animate-spin" />
                                            </div>
                                        )}

                                        <div className="flex justify-between items-start mb-3">
                                            <div>
                                                <h3 className="font-bold text-white text-lg">{apt.clientName}</h3>
                                                <p className="text-slate-400 text-sm">{apt.clientPhone}</p>
                                            </div>
                                            <div className="text-right">
                                                <div className="text-xl font-bold text-white">{apt.time}</div>
                                                <div className={`text-xs uppercase font-bold ${isToday ? 'text-green-400' : 'text-slate-500'}`}>
                                                    {isToday ? 'HOJE' : new Date(apt.date).toLocaleDateString('pt-BR', {day: '2-digit', month: 'short'})}
                                                </div>
                                            </div>
                                        </div>

                                        <div className="border-t border-slate-700/50 pt-3 flex flex-col sm:flex-row gap-3 justify-between items-center">
                                            <span className="text-sm font-medium" style={{ color: settings.primaryColor }}>
                                                R$ {apt.totalValue.toFixed(2)}
                                            </span>

                                            {/* Controles de Status Completo (Dropdown) */}
                                            <div className="w-full sm:w-auto">
                                                <select 
                                                    value={apt.status}
                                                    onChange={(e) => handleStatusChange(apt.id, e.target.value)}
                                                    disabled={isProcessing}
                                                    className={`w-full sm:w-auto bg-slate-900 border border-slate-600 text-xs font-bold uppercase rounded-lg p-2 focus:outline-none focus:border-orange-500 cursor-pointer hover:bg-slate-700 transition-colors ${STATUS_COLORS[apt.status].replace('border-', 'text-')}`}
                                                >
                                                    <option value="scheduled">Agendado</option>
                                                    <option value="confirmed">Confirmado</option>
                                                    <option value="completed">Finalizado</option>
                                                    <option value="noshow">Não veio (Falta)</option>
                                                    <option value="cancelled">Cancelado</option>
                                                </select>
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React from 'react';
import { X, AlertCircle } from 'lucide-react';

interface ConfirmationModalProps {
    isOpen: boolean;
    onClose: () => void;
    onConfirm: () => void;
    title: string;
    message: string;
    confirmText?: string;
    isDestructive?: boolean;
}

export const ConfirmationModal: React.FC<ConfirmationModalProps> = ({ 
    isOpen, onClose, onConfirm, title, message, confirmText = "Confirmar", isDestructive = false 
}) => {
    if (!isOpen) return null;

    return (
        <div 
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-fade-in"
            onClick={(e) => e.target === e.currentTarget && onClose()}
        >
            <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 w-full max-w-md shadow-2xl relative animate-scale-up">
                <button onClick={onClose} className="absolute top-4 right-4 text-slate-500 hover:text-white">
                    <X size={20} />
                </button>
                <div className="flex items-start gap-4">
                    <div className={`p-3 rounded-full ${isDestructive ? 'bg-red-500/10 text-red-500' : 'bg-slate-700 text-slate-300'}`}>
                        <AlertCircle size={24} />
                    </div>
                    <div>
                        <h3 className="text-lg font-bold text-white mb-2">{title}</h3>
                        <p className="text-slate-400 mb-6 leading-relaxed">{message}</p>
                    </div>
                </div>
                <div className="flex gap-3 justify-end">
                    <button 
                        onClick={onClose} 
                        className="px-4 py-2 text-slate-300 hover:text-white font-medium transition-colors"
                    >
                        Cancelar
                    </button>
                    <button 
                        onClick={onConfirm} 
                        className={`px-4 py-2 rounded-lg text-white font-bold transition-transform active:scale-95 ${isDestructive ? 'bg-red-500 hover:bg-red-600' : 'bg-primary hover:brightness-110'}`}
                    >
                        {confirmText}
                    </button>
                </div>
            </div>
        </div>
    );
};

import React, { useMemo, useState, useEffect } from 'react';
import { useShop } from '../../store';
import { Calendar, Clock, LogOut, CheckCircle, XCircle, AlertCircle, Settings, X, Loader2, Trash2, Plus, RefreshCw } from 'lucide-react';
import { useToast } from '../ui/ToastContext';
import { WorkSchedule, DaySchedule, Professional } from '../../types';

export const BarberDashboard: React.FC<{ onLogout: () => void }> = ({ onLogout }) => {
    const { appointments, professionals, session, updateAppointmentStatus, settings, updateProfessional, blockedSlots, addBlockedSlot, removeBlockedSlot, refresh } = useShop();
    const { showToast } = useToast();

    // 1. Identificar qual profissional é o usuário logado
    const currentPro = professionals.find(p => p.email === session?.user.email || p.userId === session?.user.id);

    // States para Modal de Configuração
    const [isConfigOpen, setIsConfigOpen] = useState(false);
    const [schedule, setSchedule] = useState<WorkSchedule | null>(null);
    const [isSaving, setIsSaving] = useState(false);
    const [isRefreshing, setIsRefreshing] = useState(false);

    // State para ações em agendamentos
    const [updatingAptId, setUpdatingAptId] = useState<string | null>(null);

    // States para Bloqueios
    const [blockDate, setBlockDate] = useState('');
    const [blockStart, setBlockStart] = useState('08:00');
    const [blockEnd, setBlockEnd] = useState('18:00');
    const [blockReason, setBlockReason] = useState('Folga / Médico');

    // Inicializar schedule quando abrir o modal
    const openConfig = () => {
        if (currentPro?.workSchedule) {
            setSchedule(JSON.parse(JSON.stringify(currentPro.workSchedule)));
        }
        setIsConfigOpen(true);
    };

    const handleRefresh = async () => {
        setIsRefreshing(true);
        await refresh();
        setTimeout(() => setIsRefreshing(false), 500);
    };

    const handleSaveSchedule = async () => {
        if (!currentPro || !schedule) return;
        setIsSaving(true);
        const { success, error } = await updateProfessional(currentPro.id, { workSchedule: schedule });
        setIsSaving(false);
        if (success) {
            showToast('Horários atualizados com sucesso!');
            setIsConfigOpen(false);
        } else {
            showToast(error || 'Erro ao salvar.', 'error');
        }
    };

    const handleAddBlock = async (e: React.FormEvent) => {
        e.preventDefault();
        if (currentPro) {
            const { success, error } = await addBlockedSlot({
                professionalId: currentPro.id,
                date: blockDate,
                startTime: blockStart,
                endTime: blockEnd,
                reason: blockReason
            });

            if (success) {
                showToast('Bloqueio adicionado!');
                setBlockReason('Folga / Médico');
            } else {
                showToast(error || 'Erro ao bloquear.', 'error');
            }
        }
    };

    const handleRemoveBlock = async (id: string) => {
        const { success, error } = await removeBlockedSlot(id);
        if (success) {
            showToast('Bloqueio removido.');
        } else {
            showToast(error || 'Erro ao remover.', 'error');
        }
    }

    const handleStatusChange = async (id: string, newStatus: string) => {
        setUpdatingAptId(id);
        try {
            const { success, error } = await updateAppointmentStatus(id, newStatus);
            if (success) {
                const mapLabels: Record<string, string> = {
                    'confirmed': 'Atendimento confirmado!',
                    'completed': 'Atendimento finalizado com sucesso!',
                    'noshow': 'Agendamento marcado como falta.',
                    'cancelled': 'Agendamento cancelado.',
                    'scheduled': 'Status revertido para agendado.'
                }
                showToast(mapLabels[newStatus] || 'Status atualizado.');
            } else {
                showToast(error || 'Erro ao atualizar status.', 'error');
            }
        } catch (err) {
            showToast('Erro de conexão.', 'error');
        } finally {
            setUpdatingAptId(null);
        }
    };

    const toggleDay = (day: keyof WorkSchedule) => {
        if (schedule) {
            setSchedule(prev => prev ? ({ ...prev, [day]: { ...prev[day], active: !prev[day].active } }) : null);
        }
    };

    const updateDayTime = (day: keyof WorkSchedule, field: keyof DaySchedule, value: string) => {
        if (schedule) {
            setSchedule(prev => prev ? ({ ...prev, [day]: { ...prev[day], [field]: value } }) : null);
        }
    };

    // 2. Filtrar agendamentos DESTE barbeiro
    const myAppointments = useMemo(() => {
        if (!currentPro) return [];
        // Ordenar: Hoje primeiro, depois data futura
        return appointments
            .filter(a => a.professionalId === currentPro.id)
            .sort((a, b) => {
                const dateA = new Date(`${a.date}T${a.time}`);
                const dateB = new Date(`${b.date}T${b.time}`);
                return dateA.getTime() - dateB.getTime();
            });
    }, [appointments, currentPro]);

    // 3. Calcular ganhos (Baseado na Comissão)
    // FIX: Usar data local para evitar problemas de fuso horário
    const today = new Date();
    // Ajusta o timezone offset para garantir que a string YYYY-MM-DD seja do dia local
    const offset = today.getTimezoneOffset();
    const todayLocal = new Date(today.getTime() - (offset * 60 * 1000));
    const todayStr = todayLocal.toISOString().split('T')[0];

    const todaysCuts = myAppointments.filter(a => a.date === todayStr && a.status === 'completed');

    // Total Bruto
    const todaysGross = todaysCuts.reduce((acc, curr) => acc + curr.totalValue, 0);
    // Comissão
    const commissionRate = currentPro?.commissionPercentage ?? 50;
    const todaysEarnings = todaysGross * (commissionRate / 100);

    const STATUS_COLORS: Record<string, string> = {
        scheduled: 'border-blue-500 text-blue-400',
        confirmed: 'border-orange-500 text-orange-400',
        completed: 'border-green-500 text-green-400',
        cancelled: 'border-red-500 text-red-400',
        noshow: 'border-slate-500 text-slate-400',
    };

    const daysMap: {[key: string]: string} = {
        monday: 'Segunda', tuesday: 'Terça', wednesday: 'Quarta', thursday: 'Quinta',
        friday: 'Sexta', saturday: 'Sábado', sunday: 'Domingo'
    };

    if (!currentPro) {
        return (
            <div className="min-h-screen bg-slate-900 flex items-center justify-center text-white p-4 text-center">
                <div>
                    <AlertCircle size={48} className="mx-auto mb-4 text-orange-500"/>
                    <h2 className="text-xl font-bold">Perfil não vinculado</h2>
                    <p className="text-slate-400 mb-6">Seu usuário não está associado a nenhum barbeiro desta loja.<br/>Peça ao dono para cadastrar seu email: {session?.user.email}</p>
                    <button onClick={onLogout} className="px-6 py-2 bg-slate-800 rounded-lg">Sair</button>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-slate-900 text-slate-100 pb-20">
            {/* Modal de Configuração */}
            {isConfigOpen && schedule && (
                <div 
                    className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-fade-in"
                    onClick={(e) => e.target === e.currentTarget && setIsConfigOpen(false)}
                >
                    <div className="bg-slate-800 w-full max-w-2xl rounded-2xl border border-slate-700 shadow-2xl relative animate-scale-up max-h-[90vh] overflow-y-auto">
                        <div className="sticky top-0 bg-slate-800 p-6 border-b border-slate-700 flex justify-between items-center z-10">
                            <h2 className="text-xl font-bold">Minha Agenda</h2>
                            <button onClick={() => setIsConfigOpen(false)}><X size={24} className="text-slate-400 hover:text-white"/></button>
                        </div>

                        <div className="p-6 space-y-8">
                            {/* Horários de Trabalho */}
                            <div className="space-y-4">
                                <h3 className="text-lg font-bold text-orange-500 flex items-center gap-2"><Clock size={18}/> Horários de Trabalho</h3>
                                <div className="space-y-3 bg-slate-900/50 p-4 rounded-xl border border-slate-700">
                                     {Object.entries(schedule).map(([key, val]) => {
                                         const day = val as DaySchedule;
                                         return (
                                             <div key={key} className="flex flex-col md:flex-row md:items-center gap-3 pb-3 border-b border-slate-700/50 last:border-0">
                                                 <div className="w-24">
                                                     <label className="flex items-center gap-2 cursor-pointer">
                                                         <input type="checkbox" checked={day.active} onChange={() => toggleDay(key as keyof WorkSchedule)} className="rounded border-slate-600 text-orange-500 focus:ring-orange-500 bg-slate-800" />
                                                         <span className={day.active ? 'text-white' : 'text-slate-500'}>{daysMap[key]}</span>
                                                     </label>
                                                 </div>
                                                 {day.active && (
                                                    <div className="flex flex-wrap items-center gap-2 text-sm">
                                                        <input type="time" value={day.start} onChange={e => updateDayTime(key as keyof WorkSchedule, 'start', e.target.value)} className="bg-slate-800 border border-slate-600 rounded px-2 py-1 text-white" />
                                                        <span className="text-slate-500">até</span>
                                                        <input type="time" value={day.end} onChange={e => updateDayTime(key as keyof WorkSchedule, 'end', e.target.value)} className="bg-slate-800 border border-slate-600 rounded px-2 py-1 text-white" />
                                                        <span className="text-slate-500 ml-2 hidden sm:inline">Almoço:</span>
                                                        <input type="time" value={day.lunchStart} onChange={e => updateDayTime(key as keyof WorkSchedule, 'lunchStart', e.target.value)} className="bg-slate-800 border border-slate-600 rounded px-2 py-1 text-white" />
                                                        <span className="text-slate-500">-</span>
                                                        <input type="time" value={day.lunchEnd} onChange={e => updateDayTime(key as keyof WorkSchedule, 'lunchEnd', e.target.value)} className="bg-slate-800 border border-slate-600 rounded px-2 py-1 text-white" />
                                                    </div>
                                                 )}
                                             </div>
                                         );
                                     })}
                                </div>
                            </div>

                            {/* Gerenciar Bloqueios */}
                            <div className="space-y-4">
                                <h3 className="text-lg font-bold text-orange-500 flex items-center gap-2"><Calendar size={18}/> Bloqueios e Folgas</h3>

                                <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-700">
                                    <h4 className="text-sm font-bold text-slate-400 uppercase mb-3">Novo Bloqueio</h4>
                                    <form onSubmit={handleAddBlock} className="space-y-3">
                                        <div className="flex flex-col sm:flex-row gap-3">
                                            <input required type="date" value={blockDate} onChange={e => setBlockDate(e.target.value)} className="flex-1 bg-slate-800 border border-slate-600 rounded p-2 text-white text-sm" />
                                            <div className="flex gap-2 flex-1">
                                                <input required type="time" value={blockStart} onChange={e => setBlockStart(e.target.value)} className="flex-1 bg-slate-800 border border-slate-600 rounded p-2 text-white text-sm" />
                                                <span className="self-center text-slate-500">-</span>
                                                <input required type="time" value={blockEnd} onChange={e => setBlockEnd(e.target.value)} className="flex-1 bg-slate-800 border border-slate-600 rounded p-2 text-white text-sm" />
                                            </div>
                                        </div>
                                        <div className="flex gap-3">
                                            <input required type="text" value={blockReason} onChange={e => setBlockReason(e.target.value)} placeholder="Motivo" className="flex-1 bg-slate-800 border border-slate-600 rounded p-2 text-white text-sm" />
                                            <button type="submit" className="bg-orange-500 hover:bg-orange-600 text-white px-4 py-2 rounded text-sm font-bold flex items-center gap-2">
                                                <Plus size={16}/> Adicionar
                                            </button>
                                        </div>
                                    </form>

                                    <div className="mt-6">
                                        <h4 className="text-sm font-bold text-slate-400 uppercase mb-3">Bloqueios Futuros</h4>
                                        <div className="space-y-2 max-h-40 overflow-y-auto pr-2 custom-scrollbar">
                                            {blockedSlots.filter(b => b.professionalId === currentPro.id).length === 0 ? (
                                                <p className="text-sm text-slate-500 italic">Nenhum bloqueio cadastrado.</p>
                                            ) : (
                                                blockedSlots
                                                    .filter(b => b.professionalId === currentPro.id)
                                                    .sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime())
                                                    .map(b => (
                                                    <div key={b.id} className="flex justify-between items-center bg-slate-800 p-3 rounded border border-slate-600">
                                                        <div>
                                                            <div className="text-sm text-white font-medium">{new Date(b.date + 'T12:00:00').toLocaleDateString('pt-BR')}</div>
                                                            <div className="text-xs text-slate-400">{b.startTime} - {b.endTime} • {b.reason}</div>
                                                        </div>
                                                        <button onClick={() => handleRemoveBlock(b.id)} className="text-red-500 hover:text-red-400 p-1"><Trash2 size={16}/></button>
                                                    </div>
                                                ))
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="p-6 border-t border-slate-700 bg-slate-800 sticky bottom-0 z-10">
                            <button 
                                onClick={handleSaveSchedule}
                                disabled={isSaving}
                                className="w-full py-3 bg-green-500 hover:bg-green-600 text-white font-bold rounded-lg flex items-center justify-center gap-2"
                            >
                                {isSaving ? <Loader2 className="animate-spin"/> : 'Salvar Alterações'}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Header */}
            <header className="bg-slate-950 border-b border-slate-800 p-4 sticky top-0 z-10">
                <div className="flex justify-between items-center max-w-4xl mx-auto">
                    <div className="flex items-center gap-3">
                        <img src={currentPro.photoUrl} alt={currentPro.name} className="w-10 h-10 rounded-full border border-slate-700 object-cover" />
                        <div>
                            <h1 className="font-bold leading-tight">Olá, {currentPro.name.split(' ')[0]}</h1>
                            <p className="text-xs text-slate-400">Painel do Barbeiro</p>
                        </div>
                    </div>
                    <div className="flex gap-2">
                        <button onClick={handleRefresh} className={`p-2 bg-slate-800 rounded-full text-slate-400 hover:text-white border border-slate-700 ${isRefreshing ? 'animate-spin text-orange-500' : ''}`} title="Atualizar dados">
                            <RefreshCw size={18}/>
                        </button>
                         <button onClick={openConfig} className="p-2 bg-slate-800 rounded-full text-slate-400 hover:text-white border border-slate-700" title="Configurações">
                            <Settings size={18}/>
                        </button>
                        <button onClick={onLogout} className="p-2 bg-slate-800 rounded-full text-slate-400 hover:text-white border border-slate-700" title="Sair">
                            <LogOut size={18}/>
                        </button>
                    </div>
                </div>
            </header>

            <div className="max-w-4xl mx-auto p-4 space-y-6">

                {/* Cards de Resumo */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-slate-800 p-4 rounded-xl border border-slate-700">
                        <p className="text-slate-400 text-xs mb-1">Cortes Hoje</p>
                        <p className="text-2xl font-bold text-white">{todaysCuts.length}</p>
                    </div>
                    <div className="bg-slate-800 p-4 rounded-xl border border-slate-700">
                        <div className="flex justify-between items-start">
                             <div>
                                <p className="text-slate-400 text-xs mb-1">Minha Comissão ({commissionRate}%)</p>
                                <p className="text-2xl font-bold text-green-400">R$ {todaysEarnings.toFixed(2)}</p>
                             </div>
                             {todaysCuts.length > 0 && (
                                <div className="text-right">
                                    <p className="text-slate-500 text-[10px] mb-1">Total Bruto</p>
                                    <p className="text-sm font-medium text-slate-300">R$ {todaysGross.toFixed(2)}</p>
                                </div>
                             )}
                        </div>
                    </div>
                </div>

                {/* Lista de Agenda */}
                <div>
                    <h2 className="font-bold text-lg mb-4 flex items-center gap-2">
                        <Calendar size={18} className="text-orange-500"/> Minha Agenda
                    </h2>

                    {myAppointments.length === 0 ? (
                        <div className="text-center py-10 text-slate-500 bg-slate-800/50 rounded-xl border border-slate-800">
                            Nenhum agendamento encontrado.
                        </div>
                    ) : (
                        <div className="space-y-3">
                            {myAppointments.map(apt => {
                                const isToday = apt.date === todayStr;
                                const isProcessing = updatingAptId === apt.id;

                                return (
                                    <div key={apt.id} className={`bg-slate-800 p-4 rounded-xl border-l-4 ${STATUS_COLORS[apt.status] || 'border-slate-500'} shadow-sm relative overflow-hidden transition-all`}>

                                        {isProcessing && (
                                            <div className="absolute inset-0 bg-slate-900/50 backdrop-blur-[1px] flex items-center justify-center z-10">
                                                <Loader2 size={24} className="text-orange-500 animate-spin" />
                                            </div>
                                        )}

                                        <div className="flex justify-between items-start mb-3">
                                            <div>
                                                <h3 className="font-bold text-white text-lg">{apt.clientName}</h3>
                                                <p className="text-slate-400 text-sm">{apt.clientPhone}</p>
                                            </div>
                                            <div className="text-right">
                                                <div className="text-xl font-bold text-white">{apt.time}</div>
                                                <div className={`text-xs uppercase font-bold ${isToday ? 'text-green-400' : 'text-slate-500'}`}>
                                                    {isToday ? 'HOJE' : new Date(apt.date).toLocaleDateString('pt-BR', {day: '2-digit', month: 'short'})}
                                                </div>
                                            </div>
                                        </div>

                                        <div className="border-t border-slate-700/50 pt-3 flex flex-col sm:flex-row gap-3 justify-between items-center">
                                            <span className="text-sm font-medium" style={{ color: settings.primaryColor }}>
                                                R$ {apt.totalValue.toFixed(2)}
                                            </span>

                                            {/* Controles de Status Completo (Dropdown) */}
                                            <div className="w-full sm:w-auto">
                                                <select 
                                                    value={apt.status}
                                                    onChange={(e) => handleStatusChange(apt.id, e.target.value)}
                                                    disabled={isProcessing}
                                                    className={`w-full sm:w-auto bg-slate-900 border border-slate-600 text-xs font-bold uppercase rounded-lg p-2 focus:outline-none focus:border-orange-500 cursor-pointer hover:bg-slate-700 transition-colors ${STATUS_COLORS[apt.status].replace('border-', 'text-')}`}
                                                >
                                                    <option value="scheduled">Agendado</option>
                                                    <option value="confirmed">Confirmado</option>
                                                    <option value="completed">Finalizado</option>
                                                    <option value="noshow">Não veio (Falta)</option>
                                                    <option value="cancelled">Cancelado</option>
                                                </select>
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useState, useRef } from 'react';
import { useShop } from '../../../store';
import { supabase } from '../../../supabaseClient';
import { Professional, WorkSchedule, DaySchedule } from '../../../types';
import { ConfirmationModal } from '../../ui/ConfirmationModal';
import { Plus, Trash2, Edit2, Upload, Loader2, Clock, X } from 'lucide-react';
import { useToast } from '../../ui/ToastContext';

const DEFAULT_DAY: DaySchedule = { start: '09:00', end: '19:00', lunchStart: '12:00', lunchEnd: '13:00', active: true };

export const TeamPanel: React.FC = () => {
    const { professionals, addProfessional, updateProfessional, removeProfessional, blockedSlots, addBlockedSlot, removeBlockedSlot, settings } = useShop();
    const { showToast } = useToast();

    const [isFormOpen, setIsFormOpen] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [deleteId, setDeleteId] = useState<string | null>(null);

    // Modal de Bloqueios
    const [isBlockModalOpen, setIsBlockModalOpen] = useState(false);
    const [selectedProForBlock, setSelectedProForBlock] = useState<Professional | null>(null);
    const [blockDate, setBlockDate] = useState('');
    const [blockStart, setBlockStart] = useState('08:00');
    const [blockEnd, setBlockEnd] = useState('18:00');
    const [blockReason, setBlockReason] = useState('Folga / Médico');

    // Form States
    const [name, setName] = useState('');
    const [role, setRole] = useState('');
    const [email, setEmail] = useState('');
    const [commission, setCommission] = useState('50'); // Default 50%
    const [photo, setPhoto] = useState<string | null>(null);
    const [isUploading, setIsUploading] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    const [schedule, setSchedule] = useState<WorkSchedule>({
        monday: {...DEFAULT_DAY}, tuesday: {...DEFAULT_DAY}, wednesday: {...DEFAULT_DAY},
        thursday: {...DEFAULT_DAY}, friday: {...DEFAULT_DAY}, saturday: {...DEFAULT_DAY},
        sunday: {...DEFAULT_DAY, active: false}
    });

    const [isScheduleOpen, setIsScheduleOpen] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            setIsUploading(true);
            try {
                const fileExt = file.name.split('.').pop();
                const fileName = `${Date.now()}_${Math.random().toString(36).substring(2)}.${fileExt}`;
                const filePath = `professionals/${fileName}`;
                const { error: uploadError } = await supabase.storage.from('images').upload(filePath, file);
                if (uploadError) throw uploadError;
                const { data } = supabase.storage.from('images').getPublicUrl(filePath);
                setPhoto(data.publicUrl);
                showToast('Foto enviada com sucesso!');
            } catch (error) {
                console.error("Erro no upload:", error);
                showToast('Erro ao fazer upload da imagem.', 'error');
            } finally {
                setIsUploading(false);
            }
        }
    };

    const handleEdit = (pro: Professional) => {
        setEditingId(pro.id);
        setName(pro.name);
        setRole(pro.role);
        setEmail(pro.email || '');
        setCommission(pro.commissionPercentage ? pro.commissionPercentage.toString() : '50');
        setPhoto(pro.photoUrl);
        if (pro.workSchedule) setSchedule(pro.workSchedule);
        setIsFormOpen(true);
        setIsScheduleOpen(false);
    };

    const confirmDelete = async () => {
        if (deleteId) {
            const { success, error } = await removeProfessional(deleteId);
            if (success) {
                showToast('Profissional removido com sucesso!');
                setDeleteId(null);
            } else {
                showToast(error || 'Erro ao remover.', 'error');
            }
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        const proData = { 
            name, 
            role, 
            email: email.toLowerCase().trim(),
            photoUrl: photo || 'https://picsum.photos/200', 
            workSchedule: schedule,
            commissionPercentage: Number(commission)
        };

        let result;
        if (editingId) {
            result = await updateProfessional(editingId, proData);
        } else {
            result = await addProfessional(proData);
        }

        setIsSaving(false);

        if (result.success) {
            showToast(editingId ? 'Profissional atualizado!' : 'Profissional adicionado!');
            setIsFormOpen(false);
            setEditingId(null);
            setName(''); setRole(''); setEmail(''); setPhoto(null); setCommission('50');
        } else {
            showToast(result.error || 'Ocorreu um erro.', 'error');
        }
    };

    const handleAddBlock = async (e: React.FormEvent) => {
        e.preventDefault();
        if (selectedProForBlock) {
            const { success, error } = await addBlockedSlot({
                professionalId: selectedProForBlock.id,
                date: blockDate,
                startTime: blockStart,
                endTime: blockEnd,
                reason: blockReason
            });

            if (success) {
                showToast('Bloqueio adicionado!');
                setBlockReason('Folga / Médico');
            } else {
                showToast(error || 'Erro ao bloquear.', 'error');
            }
        }
    };

    const handleRemoveBlock = async (id: string) => {
        const { success, error } = await removeBlockedSlot(id);
        if (success) {
            showToast('Bloqueio removido.');
        } else {
            showToast(error || 'Erro ao remover.', 'error');
        }
    }

    const toggleDay = (day: keyof WorkSchedule) => {
        setSchedule(prev => ({ ...prev, [day]: { ...prev[day], active: !prev[day].active } }));
    };

    const updateDayTime = (day: keyof WorkSchedule, field: keyof DaySchedule, value: string) => {
        setSchedule(prev => ({ ...prev, [day]: { ...prev[day], [field]: value } }));
    };

    const daysMap: {[key: string]: string} = {
        monday: 'Segunda', tuesday: 'Terça', wednesday: 'Quarta', thursday: 'Quinta',
        friday: 'Sexta', saturday: 'Sábado', sunday: 'Domingo'
    };

    return (
        <div>
            <ConfirmationModal 
                isOpen={!!deleteId}
                onClose={() => setDeleteId(null)}
                onConfirm={confirmDelete}
                title="Remover Profissional"
                message="Tem certeza que deseja remover este profissional? Esta ação não pode ser desfeita."
                confirmText="Remover"
                isDestructive
            />

            {/* Modal de Bloqueios */}
            {isBlockModalOpen && selectedProForBlock && (
                <div 
                    className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-fade-in"
                    onClick={(e) => e.target === e.currentTarget && setIsBlockModalOpen(false)}
                >
                    <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 w-full max-w-md shadow-2xl relative animate-scale-up">
                        <button onClick={() => setIsBlockModalOpen(false)} className="absolute top-4 right-4 text-slate-500 hover:text-white"><X size={20} /></button>
                        <h3 className="text-lg font-bold text-white mb-4">Gerenciar Bloqueios: {selectedProForBlock.name.split(' ')[0]}</h3>

                        <div className="mb-6 bg-slate-900/50 rounded-lg p-3 max-h-40 overflow-y-auto border border-slate-700">
                            <h4 className="text-xs font-bold text-slate-400 uppercase mb-2">Bloqueios Ativos</h4>
                            {blockedSlots.filter(b => b.professionalId === selectedProForBlock.id).length === 0 ? (
                                <p className="text-sm text-slate-500 italic">Nenhum bloqueio cadastrado.</p>
                            ) : (
                                <div className="space-y-2">
                                    {blockedSlots.filter(b => b.professionalId === selectedProForBlock.id).map(b => (
                                        <div key={b.id} className="flex justify-between items-center bg-slate-800 p-2 rounded border border-slate-700">
                                            <div>
                                                <div className="text-sm text-white font-medium">{new Date(b.date + 'T12:00:00').toLocaleDateString('pt-BR')}</div>
                                                <div className="text-xs text-slate-400">{b.startTime} - {b.endTime} • {b.reason}</div>
                                            </div>
                                            <button onClick={() => handleRemoveBlock(b.id)} className="text-red-500 hover:text-red-400 p-1"><Trash2 size={16}/></button>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>

                        <form onSubmit={handleAddBlock} className="space-y-3">
                            <h4 className="text-xs font-bold text-slate-400 uppercase">Adicionar Novo</h4>
                            <input required type="date" value={blockDate} onChange={e => setBlockDate(e.target.value)} className="w-full bg-slate-900 border border-slate-700 rounded p-2 text-white text-sm" />
                            <div className="flex gap-2">
                                <input required type="time" value={blockStart} onChange={e => setBlockStart(e.target.value)} className="flex-1 bg-slate-900 border border-slate-700 rounded p-2 text-white text-sm" />
                                <span className="text-slate-400 self-center">-</span>
                                <input required type="time" value={blockEnd} onChange={e => setBlockEnd(e.target.value)} className="flex-1 bg-slate-900 border border-slate-700 rounded p-2 text-white text-sm" />
                            </div>
                            <input required type="text" value={blockReason} onChange={e => setBlockReason(e.target.value)} placeholder="Motivo (ex: Médico)" className="w-full bg-slate-900 border border-slate-700 rounded p-2 text-white text-sm" />
                            <button type="submit" className="w-full bg-orange-500 hover:bg-orange-600 text-white font-bold py-2 rounded-lg text-sm">Adicionar Bloqueio</button>
                        </form>
                    </div>
                </div>
            )}

            <div className="flex justify-between mb-8">
                <p className="text-slate-400">Adicione, edite ou remova profissionais da sua equipe.</p>
                <button onClick={() => { setIsFormOpen(true); setEditingId(null); setName(''); setRole(''); setEmail(''); setCommission('50'); setPhoto(null); }} className="flex items-center gap-2 px-4 py-2 rounded-lg text-white font-medium hover:opacity-90 transition-opacity" style={{ backgroundColor: settings.primaryColor }}>
                    <Plus size={18} /> Adicionar Profissional
                </button>
            </div>

            {isFormOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-fade-in" onClick={(e) => e.target === e.currentTarget && setIsFormOpen(false)}>
                <div className="mb-8 bg-slate-800 p-6 rounded-xl border border-slate-700 animate-scale-up max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                     <div className="flex justify-between items-center mb-4">
                        <h3 className="text-lg font-bold">{editingId ? 'Editar Profissional' : 'Novo Profissional'}</h3>
                        <button onClick={() => setIsFormOpen(false)}><X size={24} className="text-slate-400 hover:text-white"/></button>
                     </div>
                     <form onSubmit={handleSubmit} className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm text-slate-400 mb-1">Nome Completo</label>
                                <input required value={name} onChange={e => setName(e.target.value)} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" placeholder="Ex: Carlos Silva" />
                            </div>
                            <div>
                                <label className="block text-sm text-slate-400 mb-1">Especialidade/Cargo</label>
                                <input required value={role} onChange={e => setRole(e.target.value)} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" placeholder="Ex: Master Barber" />
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm text-slate-400 mb-1">Email de Acesso (Opcional)</label>
                                <input 
                                    type="email"
                                    value={email} 
                                    onChange={e => setEmail(e.target.value)} 
                                    className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" 
                                    placeholder="barbeiro@exemplo.com" 
                                />
                                <p className="text-xs text-slate-500 mt-1">Se preenchido, o barbeiro poderá fazer login.</p>
                            </div>
                            <div>
                                <label className="block text-sm text-slate-400 mb-1">Comissão (%)</label>
                                <input 
                                    type="number" 
                                    min="0"
                                    max="100"
                                    required
                                    value={commission} 
                                    onChange={e => setCommission(e.target.value)} 
                                    className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white focus:outline-none focus:border-orange-500" 
                                    placeholder="Ex: 50" 
                                />
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm text-slate-400 mb-1">Foto do Perfil</label>
                            <div className="flex items-center gap-4">
                                <div onClick={() => !isUploading && fileInputRef.current?.click()} className={`w-16 h-16 bg-slate-900 rounded-full border border-dashed border-slate-600 flex items-center justify-center cursor-pointer hover:border-orange-500 overflow-hidden relative ${isUploading ? 'opacity-50 cursor-not-allowed' : ''}`}>
                                    {isUploading ? <Loader2 size={24} className="text-orange-500 animate-spin" /> : (photo ? <img src={photo} alt="Preview" className="w-full h-full object-cover" /> : <Upload size={20} className="text-slate-500" />)}
                                </div>
                                <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" disabled={isUploading} />
                                <span className="text-sm text-slate-500">{isUploading ? 'Enviando...' : 'Clique para carregar uma foto'}</span>
                            </div>
                        </div>

                        <div className="border border-slate-700 rounded-lg overflow-hidden">
                             <button type="button" onClick={() => setIsScheduleOpen(!isScheduleOpen)} className="w-full bg-slate-800/50 p-3 flex justify-between items-center text-left hover:bg-slate-700 transition-colors">
                                 <span className="font-medium flex items-center gap-2"><Clock size={16} /> Horários de Atendimento</span>
                                 <span className="text-xs text-slate-400">{isScheduleOpen ? 'Recolher' : 'Configurar'}</span>
                             </button>
                             {isScheduleOpen && (
                                 <div className="p-4 bg-slate-900/50 space-y-3">
                                     {Object.entries(schedule).map(([key, val]) => {
                                         const day = val as DaySchedule;
                                         return (
                                             <div key={key} className="flex flex-col md:flex-row md:items-center gap-3 pb-3 border-b border-slate-800 last:border-0">
                                                 <div className="w-24">
                                                     <label className="flex items-center gap-2 cursor-pointer">
                                                         <input type="checkbox" checked={day.active} onChange={() => toggleDay(key as keyof WorkSchedule)} className="rounded border-slate-600 text-orange-500 focus:ring-orange-500 bg-slate-800" />
                                                         <span className={day.active ? 'text-white' : 'text-slate-500'}>{daysMap[key]}</span>
                                                     </label>
                                                 </div>
                                                 {day.active && (
                                                    <div className="flex flex-wrap items-center gap-2 text-sm">
                                                        <input type="time" value={day.start} onChange={e => updateDayTime(key as keyof WorkSchedule, 'start', e.target.value)} className="bg-slate-800 border border-slate-700 rounded px-2 py-1 text-white" />
                                                        <span className="text-slate-500">até</span>
                                                        <input type="time" value={day.end} onChange={e => updateDayTime(key as keyof WorkSchedule, 'end', e.target.value)} className="bg-slate-800 border border-slate-700 rounded px-2 py-1 text-white" />
                                                        <span className="text-slate-500 ml-2">Almoço:</span>
                                                        <input type="time" value={day.lunchStart} onChange={e => updateDayTime(key as keyof WorkSchedule, 'lunchStart', e.target.value)} className="bg-slate-800 border border-slate-700 rounded px-2 py-1 text-white" />
                                                        <span className="text-slate-500">-</span>
                                                        <input type="time" value={day.lunchEnd} onChange={e => updateDayTime(key as keyof WorkSchedule, 'lunchEnd', e.target.value)} className="bg-slate-800 border border-slate-700 rounded px-2 py-1 text-white" />
                                                    </div>
                                                 )}
                                             </div>
                                         );
                                     })}
                                 </div>
                             )}
                        </div>

                        <div className="flex gap-2 justify-end pt-2">
                             <button type="button" onClick={() => setIsFormOpen(false)} className="px-4 py-2 text-slate-400 hover:text-white" disabled={isUploading || isSaving}>Cancelar</button>
                             <button type="submit" className="px-6 py-2 rounded-lg text-white flex items-center gap-2" style={{ backgroundColor: settings.primaryColor }} disabled={isUploading || isSaving}>
                                {(isUploading || isSaving) && <Loader2 size={16} className="animate-spin"/>} Salvar
                             </button>
                        </div>
                     </form>
                </div>
                </div>
            )}

