    "lucide-react": "^0.563.0",
    "react-dom": "^19.2.4",
    "@supabase/supabase-js": "2",
    "react-router-dom": "6.22.3",
    "dompurify": "3.0.9",
    "recharts": "^2.12.2"
  },
  "devDependencies": {
    "@types/node": "^22.14.0",
